INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C1','sci',6,1,'u2',1,'나무토막 옮기기 — 색 테이프로 출발선과 결승선을 표시 → 모둠원끼리 옮기는 방법(머리에 얹고·어깨에 얹고·무릎에 끼고·발등에 얹고)을 정함 → 걸어서 옮김 → 떨어뜨리면 출발선으로 돌아와 다시 시작 → 먼저·나중에 통과한 친구 이야기 · 뛰지 않기, 떨어뜨린 나무토막은 바로 줍기, 던지며 장난치지 않기, 통과한 뒤 손으로 잡아 내려놓기 · 겨루기보다 걷는 모습 살펴보기',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C2','sci',6,1,'u2',1,'걷는 빠르기 — 같은 곳까지 걸어도 사람마다 걷는 빠르기가 다름 · 빠르게 걷는 친구도 느리게 걷는 친구도 있음 · 결승선을 가장 먼저 통과한 친구가 가장 빠르게 걸은 친구 · 머리에 얹고 걸은 친구가 가장 먼저, 발등에 얹고 걸은 친구가 가장 나중에 통과(한 걸음씩 조심조심) · 빠르기를 비교하는 방법은 다음 시간부터 알아봄',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C3','sci',6,1,'u2',2,'운동 — 시간이 지남에 따라 물체의 위치가 변할 때 물체가 운동한다고 함 · 과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함됨 · 운동하는 물체: 굴러가는 공, 날아가는 갈매기, 바다 위를 나아가는 배 등',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C4','sci',6,1,'u2',2,'일상의 운동과 과학의 운동 — 신체의 운동(몸을 단련하거나 건강을 위해 움직이는 일), 사회적 운동(물 절약 운동처럼 목적을 이루려고 힘쓰는 일), 운동 경기(규칙과 방법에 따라 기량을 겨루는 일)와 과학에서의 운동(시간이 지남에 따라 물체의 위치가 변하는 것)은 뜻이 다름 · 철봉에 가만히 매달려 있는 것은 위치가 변하지 않으므로 과학에서의 운동이 아님',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C5','sci',6,1,'u2',2,'두 사진 비교 — 삼각대에 스마트 기기를 고정하고(쓰러지지 않는지 확인) 5초 간격으로 사진을 두 번 찍음(타이머 기능) · 5초 뒤 같은 위치에 있는 물체(책상·창문·화분·창밖을 보는 친구·책 읽는 친구)와 다른 위치에 있는 물체(걸어가는 친구·시곗바늘) · 공원의 처음 모습과 얼마 뒤 모습에서 운동하는 물체(자전거 타는 사람·오리 배·비행기·달리는 사람) · 운동하는 물체와 부딪히지 않기, 창밖으로 고개·손 내밀지 않기, 다른 사람을 찍은 사진은 온라인에 올리지 않고 관찰이 끝나면 삭제',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C6','sci',6,1,'u2',2,'같은 물체도 운동할 때와 하지 않을 때가 있음 — 달리는 자동차는 운동하고 주차된 자동차는 운동하지 않음 · 운동하는 물체와 운동하지 않는 물체가 정해져 있는 것이 아님 · 물체의 모습이 아니라 시간이 지남에 따라 위치가 변했는지에 초점을 둠',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C7','sci',6,1,'u2',3,'운동의 표현 — 물체의 운동은 물체가 이동하는 데 걸린 시간과 물체의 위치 변화로 표현 · 위치 변화는 처음 위치(운동을 시작하는 곳)와 나중 위치(얼마 뒤 물체가 있는 곳)로 나타냄 · 걸린 시간·처음 위치·나중 위치를 모두 넣어 말함(예: 승강기가 15초 동안 1층에서 5층으로 이동했다, 기차가 1시간 동안 출발역에서 도착역으로 이동했다)',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C8','sci',6,1,'u2',3,'칸 모양 좌표평면 — 가로선과 세로선이 직각으로 만나는 평면으로 물체의 위치를 나타내는 데 도움을 줌 · 정원판에서 분수로부터 꽃이 있는 방향과 칸 수로 위치를 말함(수선화꽃: 왼쪽 3칸, 제비꽃: 위쪽 2칸, 유채꽃: 오른쪽 2칸·위쪽 3칸, 진달래꽃: 오른쪽 1칸·아래쪽 1칸) · 두 방향이 필요하면 두 방향을 모두 말함',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C9','sci',6,1,'u2',3,'꿀벌 놀이 — 꿀벌은 오른쪽·왼쪽·위쪽·아래쪽으로 한 칸씩 이동하고 한 칸에 1초 · 진달래꽃에서 유채꽃까지 5칸이면 「꿀벌은 5초 동안 진달래꽃에서 유채꽃으로 이동했다」 · 제비꽃→유채꽃 3초, 제비꽃→진달래꽃 4초 · 꽃 붙임딱지는 정해진 곳 이외에 얼굴이나 몸에 붙이지 않기',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C10','sci',6,1,'u2',4,'같은 시간 동안의 빠르기 비교 — 이동한 거리를 측정해 비교 · 같은 시간 동안 긴 거리를 이동한 물체가 더 빠름 · 5초 동안 빨간색 자동차 135 cm, 파란색 자동차 122 cm → 빨간색이 더 빠름 · 동시에 땅을 파기 시작해 동시에 나온 두더지와 개미는 더 길게 판 두더지가 더 빠름 · 「무궁화꽃이 피었습니다」 놀이는 같은 시간 동안 가장 긴 거리를 이동해야 먼저 도착',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C11','sci',6,1,'u2',4,'같은 시간 실험 — 색 테이프로 출발선, 줄자를 출발선과 수직으로 펼쳐 경주로(줄자는 가운데) · 경주로 전체가 보이게 스마트 기기를 삼각대에 고정 · 신호에 따라 태엽 자동차 두 대를 동시에 출발시키고 5초 뒤 사진 · 사진으로 이동 거리 확인(반올림하여 일의 자리까지) · 모둠원과 역할을 나누어 협력 · 줄자에 손 다치지 않게, 태엽을 과도하게 감지 않게',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C12','sci',6,1,'u2',4,'맨 앞의 물체 — 출발선이 다르거나 동시에 출발하지 않았다면 지금 맨 앞에 있는 물체가 가장 빠르다고 할 수 없음 · 그래서 같은 시간 동안의 빠르기를 비교할 때는 같은 출발선에서 동시에 출발시킴 · 앞서 출발한 오토바이, 다른 출발선의 자동차는 위치만으로 비교할 수 없음',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C13','sci',6,1,'u2',4,'1초 동안 이동할 수 있는 거리 — 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값: 거북 약 0.3 m, 사람 약 10 m, 루지 약 39 m, 송골매 약 108 m, 드론 약 133 m · 기록을 바탕으로 한 값이지 언제나 그 빠르기로 움직인다는 뜻이 아님 · 같은 시간(1초) 동안 이동할 수 있는 거리가 길수록 빠름',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C14','sci',6,1,'u2',5,'같은 거리의 빠르기 비교 — 걸린 시간을 측정해 비교 · 같은 거리를 이동하는 데 걸린 시간이 짧은 물체가 더 빠름 · 100 cm를 초록색 자동차 4.2초, 노란색 자동차 5.8초 → 초록색이 더 빠름 · 수영·달리기 경기는 결승선까지 걸린 시간이 짧은 순서대로 순위를 정함(50 m를 8초에 간 친구가 1위)',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C15','sci',6,1,'u2',5,'같은 거리 실험 — 출발선에서 수직으로 100 cm 떨어진 곳에 결승선 표시(줄자는 결승선 표시할 때만 쓰고 잘 말아 보관) · 자동차의 앞부분이 출발선에 오게 놓음 · 정확한 시간 측정과 편리한 초시계 사용을 위해 한 대씩 출발 · 초시계를 든 친구의 신호에 출발, 앞부분이 결승선에 닿은 시간을 반올림하여 소수 첫째 자리까지 · 역할을 나누어 협력',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C16','sci',6,1,'u2',5,'같은 거리를 이동하는 데 걸린 시간을 재는 종목 — 달리기(트랙을 달리는 데 걸린 시간), 조정(보트를 타고 노를 저어 결승선까지, 뒤로 나아감), 쇼트트랙(얼음 트랙을 돎), 알파인 스키(눈 덮인 슬로프를 내려감), 봅슬레이(썰매를 타고 얼음 트랙을 내려감, 0.01초 차이로 순위가 정해지기도) · 모두 걸린 시간이 짧은 순서대로 순위를 정함',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C17','sci',6,1,'u2',6,'속력 — 일정한 시간 동안 물체가 이동한 거리 · 속력 = 이동 거리 ÷ 걸린 시간 · 이동 거리와 걸린 시간이 모두 다른 물체의 빠르기는 속력을 구해 비교 · 속력은 숫자와 단위를 함께 씀 · 빨간색 자동차 135 cm ÷ 5 s = 27.0 cm/s, 파란색 122 cm ÷ 5 s = 24.4 cm/s',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C18','sci',6,1,'u2',6,'속력의 단위와 읽기 — km/h(킬로미터 매 시), m/s(미터 매 초), cm/s(센티미터 매 초) · 「매」는 「하나하나마다」라는 뜻 · 60 km/h는 「육십 킬로미터 매 시」로 읽고 1시간 동안 60 km를 이동한 것과 같은 빠르기 · 2 m/s는 1초 동안 2 m를 이동한 것과 같은 빠르기',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C19','sci',6,1,'u2',6,'속력으로 비교 — 속력의 단위가 같을 때 속력을 나타내는 숫자가 클수록 더 빠름 · 단위가 다르면(10 km/h와 5 m/s) 숫자만으로 바로 비교할 수 없음 · 자전거 20 km/h, 자동차 72.5 km/h, 기차 150 km/h, 배 34.5 km/h, 비행기 900 km/h → 비행기·기차·자동차·배·자전거 순 · 치타 50 m를 10초(5 m/s), 호랑이 100 m를 25초(4 m/s) → 치타가 더 빠름',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C20','sci',6,1,'u2',6,'속력이 뜻하는 것 — 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이 아니라 전체 이동 거리와 전체 걸린 시간으로 구한 값 · 빠르기를 속력으로 나타내면 숫자와 단위로 정확히 전할 수 있어 의사소통하기에 편리함',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C21','sci',6,1,'u2',7,'속력과 위험 — 속력은 먼 곳까지 빠르게 갈 수 있어 편리하지만 속력이 빠른 물체는 바로 멈추기 어려워 안전사고 위험이 커짐 · 제동 거리: 운전자가 브레이크를 밟은 뒤 자동차가 완전히 멈출 때까지 움직인 거리 · 같은 도로에서 속력이 빠를수록 제동 거리가 길어지고(30 km/h 1.5 m → 60 km/h 10.1 m, 마른 노면) 빙판길처럼 미끄러운 도로에서는 더 길어짐(30 km/h 10.7 m) · 지그재그 차선은 도로 폭을 좁게 느껴 속력을 줄이도록 유도',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C22','sci',6,1,'u2',7,'안전 수칙 — 계단은 뛰지 않고 걸어서 · 자동계단은 뛰거나 걷지 않고 손잡이를 잡고 서서 · 자전거는 보호 장비를 착용하고 적당한 속력으로 · 운전자는 어린이 보호 구역에서 정해진 속력보다 천천히 · 횡단보도는 좌우를 살피며 건너고 자전거·킥보드에서 내려서 건넘 · 길을 걸을 때 스마트 기기를 보지 않고 주위를 살핌 · 비나 눈이 오는 날 더 주의 · 교통안전 수칙은 어린이인 나부터 실천',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C23','sci',6,1,'u2',7,'안전장치 — 자동차: 안전띠(충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정), 에어백(빠른 속력으로 충돌할 때 공기주머니를 부풀려 탑승자 보호), 차간 거리 유지 장치(앞차가 갑자기 정지했을 때를 대비해 속력을 조절하고 안전거리 유지) · 도로: 과속 방지턱(운전자가 속력을 줄이도록 유도), 안전 울타리(충돌 때 충격을 흡수하고 보행자 보호), 과속 경보 시스템(자동차의 속력을 실시간으로 측정해 알려 줌) · 안전장치가 있어도 안전 수칙을 함께 지켜야 함',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C24','sci',6,1,'u2',7,'조사·공유 — 검색어(보행자 안전 수칙, 운전자 안전 수칙, 자전거 안전 수칙, 어린이 보호 구역, 자동차 안전장치, 도로 안전장치)로 조사 · 믿을 만한 자료인지 확인하고 출처를 밝힘 · 비슷한 내용끼리 묶어 공유 플랫폼에 올림 · 나와 다른 사람의 개인 정보를 누리망에 함부로 올리지 않고 바르고 고운 말로 댓글 · 다른 모둠의 내용을 읽고 새로 알게 된 점을 댓글로',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C25','sci',6,1,'u2',8,'실천 점검표 — 안전 수칙은 한 번 안다고 지켜지지 않아 매일 실천하고 점검해야 함 · 모둠원의 의견을 종합해 넣을 수칙을 정하고 만드는 방법은 너무 복잡하거나 어렵지 않게 계획 · 도화지·가위·풀·그림 도구로 병풍 책(앞 칸 수칙, 뒤 칸 일주일 점검표)·화분·수첩 모양 · 잘 보이는 곳에 두고 실천한 것만 양심적으로 표시 · 표시가 많은 것보다 꾸준히 실천해 습관이 되는 것이 중요 · 활동이 끝난 뒤에도 실천',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C26','sci',6,1,'u2',8,'실천 결과 나누기 — 일주일 동안 실천한 결과와 느낀 점을 발표 · 바른 자세로 경청하고 친구가 실천하려고 노력한 점을 찾아 칭찬 · 잘 지키지 못한 점은 탓하지 않고 다음 주에 더 노력할 점으로 정함',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u2-C27','sci',6,1,'u2',8,'스포츠 첨단 기술 — 움직임 센서(선수의 등에 부착, 위치와 속력을 실시간으로 측정, 장거리 경기에서 앞서는 선수 비교), 초고속 카메라(결승선, 1초에 수천 장의 사진으로 먼저 도착한 선수를 보여 줌, 사람의 눈으로 판단하기 어려울 때 공정한 판정), 3D 선수 추적 기술(경기장 주변 여러 대의 카메라, 선수의 움직임을 삼차원으로 보여 줌, 선수는 더 빠른 기록을 낼 방법을 찾고 관객은 경기에 몰입) · 첨단 기술은 공정한 경기와 기량 향상을 돕는 것이지 연습을 대신하지 않음 · 경기의 문제를 해결하려고 새 기술을 떠올리는 마음',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X01','sci',6,'u2',ARRAY['SC6-1-u2-C1']::text[],'나무토막 옮기기의 규칙을 잘못 안다(떨어뜨린 자리에서 이어 가기, 뛰어서 옮기기, 던지며 장난치기, 떨어진 나무토막을 그대로 두기 등)','떨어뜨리면 출발선으로 · 뛰지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X02','sci',6,'u2',ARRAY['SC6-1-u2-C1','SC6-1-u2-C2']::text[],'빠르기를 살펴보는 활동을 누가 이기는지 겨루는 일로만 여긴다','겨루기보다 살펴보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X03','sci',6,'u2',ARRAY['SC6-1-u2-C2']::text[],'모든 사람이 같은 빠르기로 걷는다고 여기거나, 옮기는 방법이 달라도 걷는 모습은 같다고 여긴다','사람마다 빠르기가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X04','sci',6,'u2',ARRAY['SC6-1-u2-C2']::text[],'결승선을 가장 나중에 통과한 친구가 가장 빠르게 걸었다고 거꾸로 판단한다','먼저 통과할수록 빨라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X05','sci',6,'u2',ARRAY['SC6-1-u2-C3','SC6-1-u2-C7']::text[],'운동이나 운동의 표현을 무게·색깔·크기 같은 다른 성질의 변화로 여긴다','시간에 따른 위치 변화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X06','sci',6,'u2',ARRAY['SC6-1-u2-C4']::text[],'일상에서 쓰는 「운동」의 뜻과 과학에서의 운동을 섞어, 철봉에 가만히 매달리기나 물 절약 운동도 과학에서의 운동이라고 여긴다','과학에서는 위치가 변해야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X07','sci',6,'u2',ARRAY['SC6-1-u2-C3']::text[],'사람이나 동물은 물체가 아니라서 운동하는 물체에 넣지 않는다고 여긴다','사람·동물도 물체에 포함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X08','sci',6,'u2',ARRAY['SC6-1-u2-C5']::text[],'두 장면을 비교할 때 같은 위치에 있는 물체와 다른 위치에 있는 물체를 바꾸어 가르거나, 운동하는 물체를 잘못 찾는다','처음과 얼마 뒤의 위치를 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X09','sci',6,'u2',ARRAY['SC6-1-u2-C6']::text[],'운동하는 물체와 운동하지 않는 물체가 정해져 있다고 여긴다(자동차는 언제나 운동한다, 주차된 자동차도 운동한다 등)','같은 물체도 경우에 따라 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X10','sci',6,'u2',ARRAY['SC6-1-u2-C5']::text[],'관찰할 때의 안전과 개인 정보 보호를 잘못 안다(창밖으로 몸을 내밀기, 다른 사람 사진을 누리망에 올리기, 사진을 지우지 않기 등)','올리지 않고 삭제해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X11','sci',6,'u2',ARRAY['SC6-1-u2-C6']::text[],'위치가 아니라 물체의 모습·자세·모양이 바뀌었는지로 운동을 판단한다','모습이 아니라 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X12','sci',6,'u2',ARRAY['SC6-1-u2-C7']::text[],'물체의 운동을 표현할 때 걸린 시간·처음 위치·나중 위치 가운데 하나라도 빠뜨려도 된다고 여긴다','세 가지를 모두 넣어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X13','sci',6,'u2',ARRAY['SC6-1-u2-C7','SC6-1-u2-C9']::text[],'처음 위치와 나중 위치를 바꾸어 말한다','시작한 곳이 처음 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X14','sci',6,'u2',ARRAY['SC6-1-u2-C8']::text[],'칸 모양 좌표평면에서 방향이나 칸 수를 잘못 읽거나, 두 방향이 필요한 위치를 한 방향으로만 말한다','기준에서 방향과 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X15','sci',6,'u2',ARRAY['SC6-1-u2-C9']::text[],'꿀벌이 이동한 칸 수(걸린 시간)를 잘못 세거나, 대각선으로 한 번에 갈 수 있다고 여긴다','상하좌우 한 칸에 1초') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X16','sci',6,'u2',ARRAY['SC6-1-u2-C7']::text[],'물체의 위치 변화를 「중간 위치」와 나중 위치로 나타낸다고 여긴다','처음 위치와 나중 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X17','sci',6,'u2',ARRAY['SC6-1-u2-C10']::text[],'같은 시간 동안 이동한 물체는 이동 거리가 짧을수록 더 빠르다고 여긴다','같은 시간이면 길게 간 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X18','sci',6,'u2',ARRAY['SC6-1-u2-C11']::text[],'같은 시간 동안의 빠르기를 비교하는 실험 방법을 잘못 안다(따로 출발시키기, 사진 찍는 시각을 다르게 하기, 줄자를 비스듬히 펼치기 등)','같은 출발선 · 동시에 출발 · 5초 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X19','sci',6,'u2',ARRAY['SC6-1-u2-C12']::text[],'출발선이나 출발 시각과 관계없이 지금 맨 앞에 있는 물체가 언제나 가장 빠르다고 여긴다','출발선과 출발 시각을 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X20','sci',6,'u2',ARRAY['SC6-1-u2-C10','SC6-1-u2-C14']::text[],'무게·색깔·태엽을 감은 정도처럼 측정하지 않은 것으로 빠르기를 판단한다','거리나 시간을 재어 비교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X21','sci',6,'u2',ARRAY['SC6-1-u2-C13']::text[],'1초 동안 이동할 수 있는 거리 자료를 언제나 그 빠르기로 움직인다는 뜻으로 여기거나, 대상과 값을 잘못 짝짓는다','기록을 바탕으로 한 값') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X22','sci',6,'u2',ARRAY['SC6-1-u2-C14']::text[],'같은 거리를 이동한 물체는 걸린 시간이 길수록 더 빠르다고 여긴다','같은 거리면 빨리 닿은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X23','sci',6,'u2',ARRAY['SC6-1-u2-C15']::text[],'같은 거리를 이동하는 데 걸린 시간을 재는 실험 방법을 잘못 안다(한꺼번에 출발시키기, 줄자를 펼쳐 둔 채 출발시키기, 뒷부분을 출발선에 맞추기 등)','한 대씩 · 앞부분 · 소수 첫째 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X24','sci',6,'u2',ARRAY['SC6-1-u2-C14','SC6-1-u2-C16']::text[],'이동한 거리가 다른데도 걸린 시간만으로 빠르기를 비교하거나, 걸린 시간을 재지 않고 지금 앞서 있는 선수로 순위를 정한다','거리가 같을 때 시간으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X25','sci',6,'u2',ARRAY['SC6-1-u2-C16']::text[],'걸린 시간을 재는 운동 종목과 그 설명을 잘못 짝짓는다','트랙·보트·얼음·슬로프·썰매') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X26','sci',6,'u2',ARRAY['SC6-1-u2-C17']::text[],'속력을 걸린 시간을 이동 거리로 나누거나, 이동 거리에 걸린 시간을 곱해 구한다고 여긴다','이동 거리 ÷ 걸린 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X27','sci',6,'u2',ARRAY['SC6-1-u2-C17']::text[],'속력을 숫자만 쓰고 단위를 빠뜨리거나, 이동 거리 자체를 속력으로 여긴다','숫자와 단위를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X28','sci',6,'u2',ARRAY['SC6-1-u2-C18']::text[],'속력의 단위를 잘못 읽거나 뜻을 잘못 안다(매 시와 매 초를 바꾸기, 60 km/h를 1초 동안 60 km로 여기기 등)','km/h는 1시간마다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X29','sci',6,'u2',ARRAY['SC6-1-u2-C19']::text[],'속력을 나타내는 숫자가 크면 단위와 관계없이 언제나 더 빠르다고 여긴다','단위가 같을 때만 숫자로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X30','sci',6,'u2',ARRAY['SC6-1-u2-C20']::text[],'27.0 cm/s 같은 속력을 매 초 똑같이 그만큼씩 이동했다는 뜻으로 여긴다','전체 거리와 전체 시간으로 구한 값') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X31','sci',6,'u2',ARRAY['SC6-1-u2-C19']::text[],'이동 거리와 걸린 시간이 모두 다를 때, 더 먼 거리를 갔거나 더 오래 달린 쪽이 더 빠르다고 여긴다','속력을 구해 비교해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X32','sci',6,'u2',ARRAY['SC6-1-u2-C21']::text[],'속력은 빠를수록 좋기만 하다고 여기거나, 반대로 속력은 위험만 만든다고 여긴다','편리함과 위험이 함께 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X33','sci',6,'u2',ARRAY['SC6-1-u2-C21']::text[],'브레이크를 밟으면 바로 멈춘다고 여기거나, 제동 거리가 속력·도로 상태와 관계없다고 여긴다','빠를수록·미끄러울수록 길어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X34','sci',6,'u2',ARRAY['SC6-1-u2-C22']::text[],'속력과 관련된 안전 수칙을 잘못 안다(자동계단에서 뛰기, 스마트 기기를 보며 건너기, 킥보드를 탄 채 횡단보도 건너기 등)','상황마다 지킬 수칙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X35','sci',6,'u2',ARRAY['SC6-1-u2-C22','SC6-1-u2-C25']::text[],'교통안전 수칙은 어른들만 신경 쓰면 되고 어린이와는 관계없다고 여긴다','나부터 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X36','sci',6,'u2',ARRAY['SC6-1-u2-C23']::text[],'안전장치가 설치된 곳(자동차·도로)이나 하는 일을 바꾸어 안다','안전띠·에어백은 자동차, 방지턱은 도로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X37','sci',6,'u2',ARRAY['SC6-1-u2-C23','SC6-1-u2-C22']::text[],'안전장치가 있으면 속력이 빨라도 안전하므로 안전 수칙은 지키지 않아도 된다고 여긴다','장치와 수칙을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X38','sci',6,'u2',ARRAY['SC6-1-u2-C24']::text[],'조사한 자료를 쓰고 나누는 태도를 잘못 안다(출처 없이 쓰기, 믿을 만한지 확인하지 않기, 개인 정보 올리기, 거친 댓글 등)','출처 · 확인 · 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X39','sci',6,'u2',ARRAY['SC6-1-u2-C25']::text[],'표시가 많은 점검표일수록 좋은 점검표라고 여겨, 실천하지 못한 날도 칸을 채운다','양심적으로 표시해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X40','sci',6,'u2',ARRAY['SC6-1-u2-C25']::text[],'실천 점검표를 만드는 방법을 잘못 안다(혼자 정하기, 너무 복잡하게 계획하기, 보이지 않는 곳에 두기, 일주일 뒤 실천을 그만두기 등)','함께 정하고 쉽게, 꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X41','sci',6,'u2',ARRAY['SC6-1-u2-C26']::text[],'실천 결과를 나눌 때 잘 지키지 못한 친구를 탓하거나 친구의 발표를 듣지 않는다','노력한 점을 칭찬해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X42','sci',6,'u2',ARRAY['SC6-1-u2-C27']::text[],'스포츠 첨단 기술이 하는 일이나 놓이는 곳을 서로 바꾸어 안다','센서 · 초고속 카메라 · 3D 추적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u2-X43','sci',6,'u2',ARRAY['SC6-1-u2-C27']::text[],'첨단 기술이 있으니 선수는 연습하지 않아도 된다고 여기거나, 첨단 기술은 재미만을 위한 것이라고 여긴다','공정한 판정과 기량 향상을 도와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#1','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',1,'mc','auto','출발선과 결승선은 무엇으로 표시하나요?',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"mc","stem":"출발선과 결승선은 무엇으로 표시하나요?","options":[{"t":"색 테이프","correct":true},{"t":"나무토막을 길게 늘어놓는다","mis":"SC6-1-u2-X01"},{"t":"바닥에 물을 뿌린다","mis":"SC6-1-u2-X01"},{"t":"연필로 바닥에 그린다","mis":"SC6-1-u2-X01"}],"explanation":["준비물을 떠올려요.","바닥에 붙여 표시해요.","색 테이프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#2','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',1,'mc','auto','나무토막을 옮기다 떨어뜨리면 어떻게 하나요?',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"mc","stem":"나무토막을 옮기다 떨어뜨리면 어떻게 하나요?","options":[{"t":"출발선으로 돌아와서 다시 시작한다","correct":true},{"t":"떨어진 자리에서 그대로 이어서 걷는다","mis":"SC6-1-u2-X01"},{"t":"친구에게 대신 옮겨 달라고 한다","mis":"SC6-1-u2-X01"},{"t":"그냥 두고 결승선까지 뛰어간다","mis":"SC6-1-u2-X01"}],"explanation":["놀이 규칙이에요.","처음부터 다시 해요.","출발선으로 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#3','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',1,'ox','auto','나무토막을 옮길 때는 뛰지 않고 걸어서 옮겨요.',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"ox","stem":"나무토막을 옮길 때는 뛰지 않고 걸어서 옮겨요.","answer":"O","reason_options":[{"t":"뛰다가 넘어져 다칠 수 있기 때문에","correct":true},{"t":"뛰면 나무토막이 무거워지기 때문에","mis":"SC6-1-u2-X01"}],"mis":"SC6-1-u2-X01","explanation":["걷는 놀이예요.","뛰면 넘어질 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#4','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C2',1,'sa','auto','「결승선을 가장 먼저 통과한 친구가 가장 □□□ 걸은 친구입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u2-C2","difficulty":1,"kind":"sa","stem":"「결승선을 가장 먼저 통과한 친구가 가장 □□□ 걸은 친구입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["빠르게","빨리"],"explanation":["먼저 들어온 친구예요.","느리게의 반대예요.","빠르게예요."],"mis":"SC6-1-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#5','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',2,'match','auto','걷는 방법과 나무토막을 두는 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"match","stem":"걷는 방법과 나무토막을 두는 자리를 알맞게 이으세요.","pairs":[{"l":"머리에 얹고 걷기","r":"정수리 위에 올리고 고개를 세워 걷는다"},{"l":"어깨에 얹고 걷기","r":"한쪽 어깨 위에 올리고 균형을 잡는다"},{"l":"무릎에 끼고 걷기","r":"두 무릎 사이에 끼워 종종걸음으로 간다"},{"l":"발등에 얹고 걷기","r":"발등 위에 올리고 한 걸음씩 옮긴다"}],"mis":"SC6-1-u2-X03","explanation":["나무토막이 있는 곳을 봐요.","몸의 자리가 달라요.","모습도 달라져요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#6','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C2',2,'mc','auto','결과에서 가장 빠르게 걸은 친구는 누구인가요?',ARRAY['SC6-1-u2-X04','SC6-1-u2-X03']::text[],false,'{"seq":6,"concept":"SC6-1-u2-C2","difficulty":2,"kind":"mc","stem":"결과에서 가장 빠르게 걸은 친구는 누구인가요?","options":[{"t":"머리에 얹고 걸은 친구","correct":true},{"t":"발등에 얹고 걸은 친구","mis":"SC6-1-u2-X04"},{"t":"무릎에 끼고 걸은 친구","mis":"SC6-1-u2-X04"},{"t":"네 친구의 빠르기는 모두 같다","mis":"SC6-1-u2-X03"}],"explanation":["가장 먼저 통과한 친구예요.","머리에 얹은 친구예요.","가장 빠르게 걸었어요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#7','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',2,'error','auto','활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X02','SC6-1-u2-X01']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"error","stem":"활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「누가 이기는지 겨루는 게 가장 중요해.」","correct":true,"mis_target":"SC6-1-u2-X02"},{"t":"하린 — 「떨어뜨린 나무토막은 바로 주워야 해.」","mis":"SC6-1-u2-X01"},{"t":"지민 — 「통과한 뒤에는 손으로 잡아 내려놓자.」","mis":"SC6-1-u2-X01"}],"explanation":["무엇에 집중하나요?","걷는 모습을 살펴봐요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#8','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C2',2,'blank','auto','「같은 곳까지 걸어도 사람마다 걷는 (    )가 다릅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X03']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C2","difficulty":2,"kind":"blank","stem":"「같은 곳까지 걸어도 사람마다 걷는 (    )가 다릅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"빠르기","correct":true},{"t":"무게","mis":"SC6-1-u2-X03"},{"t":"색깔","mis":"SC6-1-u2-X03"},{"t":"출발선","mis":"SC6-1-u2-X03"}],"explanation":["먼저·나중을 떠올려요.","빠르게, 느리게예요.","빠르기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#9','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',2,'ox','auto','떨어뜨린 나무토막은 그대로 두고 계속 걸어가요.',ARRAY['SC6-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"ox","stem":"떨어뜨린 나무토막은 그대로 두고 계속 걸어가요.","answer":"X","reason_options":[{"t":"떨어진 나무토막을 밟고 넘어질 수 있어 바로 주워야 하기 때문에","correct":true},{"t":"결승선에 먼저 닿는 것이 가장 중요하기 때문에","mis":"SC6-1-u2-X02"}],"mis":"SC6-1-u2-X02","explanation":["바닥에 남으면 어떨까요?","밟고 넘어질 수 있어요.","바로 주워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_basic#10','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C2',3,'mc','auto','오늘 활동으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u2-X03','SC6-1-u2-X04','SC6-1-u2-X02']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C2","difficulty":3,"kind":"mc","stem":"오늘 활동으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"빠르게 걷는 사람도 있고 느리게 걷는 사람도 있다","correct":true},{"t":"모든 사람은 똑같은 빠르기로 걷는다","mis":"SC6-1-u2-X03"},{"t":"가장 나중에 통과한 친구가 가장 빠르다","mis":"SC6-1-u2-X04"},{"t":"이 활동에서는 겨루어 이기는 것이 가장 중요하다","mis":"SC6-1-u2-X02"}],"explanation":["통과한 차례가 달랐어요.","빠르기가 달라요.","빠른 사람, 느린 사람이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#1','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C1',2,'sa','auto','머리·어깨·무릎·발등에 얹거나 끼우고 옮기는 물건은 무엇인가요? (□□□)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"sa","stem":"머리·어깨·무릎·발등에 얹거나 끼우고 옮기는 물건은 무엇인가요? (□□□)","answer":["나무토막"],"explanation":["가벼운 물건이에요.","나무로 만들었어요.","나무토막이에요."],"mis":"SC6-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#2','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C1',2,'mc','auto','활동하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"mc","stem":"활동하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"출발선·결승선 표시 → 옮기는 방법 정하기 → 걸어서 옮기기 → 먼저·나중에 통과한 친구 이야기하기","correct":true},{"t":"옮기는 방법 정하기 → 걸어서 옮기기 → 출발선·결승선 표시 → 먼저·나중에 통과한 친구 이야기하기","mis":"SC6-1-u2-X01"},{"t":"걸어서 옮기기 → 출발선·결승선 표시 → 옮기는 방법 정하기 → 먼저·나중에 통과한 친구 이야기하기","mis":"SC6-1-u2-X01"},{"t":"출발선·결승선 표시 → 걸어서 옮기기 → 먼저·나중에 통과한 친구 이야기하기 → 옮기는 방법 정하기","mis":"SC6-1-u2-X01"}],"explanation":["먼저 선을 그어요.","방법을 정하고 걸어요.","마지막에 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#3','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',3,'mc','auto','발등에 얹고 걸은 친구가 가장 나중에 통과한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X20','SC6-1-u2-X03','SC6-1-u2-X04']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C2","difficulty":3,"kind":"mc","stem":"발등에 얹고 걸은 친구가 가장 나중에 통과한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나무토막이 떨어지지 않게 한 걸음씩 조심조심 옮겨야 해서","correct":true},{"t":"발등에 얹으면 나무토막이 더 무거워져서","mis":"SC6-1-u2-X20"},{"t":"모든 친구가 같은 빠르기로 걸어서 차례는 우연이라서","mis":"SC6-1-u2-X03"},{"t":"가장 나중에 통과해야 가장 빠른 것이라서","mis":"SC6-1-u2-X04"}],"explanation":["걷는 모습을 떠올려요.","한 걸음씩 옮겼어요.","조심조심 걸어서예요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#4','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',3,'error','auto','결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X04','SC6-1-u2-X03']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C2","difficulty":3,"kind":"error","stem":"결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「발등에 얹은 친구가 가장 늦게 들어왔으니 가장 빠르게 걸었어.」","correct":true,"mis_target":"SC6-1-u2-X04"},{"t":"예준 — 「머리에 얹은 친구가 가장 먼저 통과했어.」","mis":"SC6-1-u2-X04"},{"t":"다인 — 「옮기는 방법에 따라 걷는 모습이 달랐어.」","mis":"SC6-1-u2-X03"}],"explanation":["먼저 통과한 친구가 빨라요.","늦게 들어오면 느려요.","수아가 잘못 말했어요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#5','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',3,'ox','auto','같은 출발선에서 출발해 같은 결승선까지 걸었다면, 결승선을 먼저 통과한 친구가 더 빠르게 걸은 거예요.',ARRAY['SC6-1-u2-X04']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C2","difficulty":3,"kind":"ox","stem":"같은 출발선에서 출발해 같은 결승선까지 걸었다면, 결승선을 먼저 통과한 친구가 더 빠르게 걸은 거예요.","answer":"O","reason_options":[{"t":"같은 곳까지 걸었을 때 먼저 닿은 친구가 더 빠르게 걸었기 때문에","correct":true},{"t":"결승선을 늦게 통과할수록 더 빠르기 때문에","mis":"SC6-1-u2-X04"}],"mis":"SC6-1-u2-X04","explanation":["같은 곳까지 걸었어요.","먼저 닿은 친구예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#6','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',3,'match','auto','친구와 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C2","difficulty":3,"kind":"match","stem":"친구와 결과를 알맞게 이으세요.","pairs":[{"l":"머리에 얹고 걸은 친구","r":"가장 먼저 통과했다"},{"l":"발등에 얹고 걸은 친구","r":"가장 나중에 통과했다"},{"l":"무릎에 끼고 걸은 친구","r":"다리를 벌리지 못해 종종걸음으로 갔다"}],"mis":"SC6-1-u2-X03","explanation":["결과를 하나씩 읽어요.","먼저와 나중이 있어요.","무릎은 종종걸음이에요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#7','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C1',3,'mc','auto','활동할 때 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X01','SC6-1-u2-X02']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C1","difficulty":3,"kind":"mc","stem":"활동할 때 알맞은 행동은 어느 것인가요?","options":[{"t":"결승선을 통과한 뒤 나무토막을 손으로 잡아 내려놓는다","correct":true},{"t":"남은 나무토막을 친구에게 던지며 장난친다","mis":"SC6-1-u2-X01"},{"t":"더 빨리 가려고 결승선까지 뛰어간다","mis":"SC6-1-u2-X02"},{"t":"떨어진 나무토막을 그대로 두고 걸어간다","mis":"SC6-1-u2-X01"}],"explanation":["안전을 떠올려요.","던지거나 뛰지 않아요.","손으로 내려놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#8','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',4,'mc','auto','「빠르기를 어떻게 하면 더 정확하게 비교할 수 있을까?」라고 묻는 친구에게 오늘 할 수 있는 가장 알맞은 대답은 어느 것인가요?',ARRAY['SC6-1-u2-X03','SC6-1-u2-X02','SC6-1-u2-X20']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C2","difficulty":4,"kind":"mc","stem":"「빠르기를 어떻게 하면 더 정확하게 비교할 수 있을까?」라고 묻는 친구에게 오늘 할 수 있는 가장 알맞은 대답은 어느 것인가요?","options":[{"t":"오늘은 먼저·나중에 통과한 친구를 살펴봤고, 빠르기를 비교하는 방법은 다음 시간부터 하나씩 알아봐","correct":true},{"t":"빠르기는 사람마다 같아서 비교할 필요가 없어","mis":"SC6-1-u2-X03"},{"t":"겨루어 이긴 친구가 빠른 친구니까 순서만 정하면 돼","mis":"SC6-1-u2-X02"},{"t":"나무토막이 무거운 친구가 더 빠른 거야","mis":"SC6-1-u2-X20"}],"explanation":["오늘 한 일을 떠올려요.","먼저·나중을 살폈어요.","방법은 다음 시간부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#9','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C1',4,'mc','auto','친구가 「나는 꼭 이기고 싶으니까 뛰어서 옮길래.」라고 말했어요. 가장 알맞은 조언은 어느 것인가요?',ARRAY['SC6-1-u2-X02','SC6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C1","difficulty":4,"kind":"mc","stem":"친구가 「나는 꼭 이기고 싶으니까 뛰어서 옮길래.」라고 말했어요. 가장 알맞은 조언은 어느 것인가요?","options":[{"t":"뛰면 넘어져 다칠 수 있고, 이 활동은 겨루기보다 친구들의 걷는 모습을 살펴보는 거야","correct":true},{"t":"이기고 싶으면 조금은 뛰어도 괜찮아","mis":"SC6-1-u2-X02"},{"t":"떨어뜨려도 그 자리에서 계속 가면 더 빨라","mis":"SC6-1-u2-X01"},{"t":"나무토막을 결승선 쪽으로 던지면 더 빨라","mis":"SC6-1-u2-X01"}],"explanation":["규칙과 안전을 떠올려요.","뛰지 않아요.","걷는 모습을 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L01_challenge#10','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C2',4,'essay','teacher','나무토막 옮기기 결과를 보고 가장 빠르게 걸은 친구와 가장 느리게 걸은 친구를 까닭과 함께 쓰고, 이 활동으로 알게 된 점과 활동할 때 지킬 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C2","difficulty":4,"kind":"essay","stem":"나무토막 옮기기 결과를 보고 가장 빠르게 걸은 친구와 가장 느리게 걸은 친구를 까닭과 함께 쓰고, 이 활동으로 알게 된 점과 활동할 때 지킬 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 가장 빠르게 걸은 친구는 머리에 얹고 걸은 친구이다. 같은 출발선에서 같은 결승선까지 걸었는데 가장 먼저 통과했기 때문이다. 가장 느리게 걸은 친구는 발등에 얹고 걸은 친구이다. 한 걸음씩 조심조심 옮겨서 가장 나중에 통과했다. 사람마다, 옮기는 방법마다 걷는 빠르기가 다르다는 것을 알게 되었다. 활동할 때는 뛰지 않고 걸으며, 겨루기보다 친구들의 걷는 모습을 살펴본다.","scoring_points":["가장 빠른 친구·가장 느린 친구를 까닭과 함께 썼는가","걷는 빠르기가 다름을 썼는가","지킬 점을 썼는가"]},"explanation":["결과를 읽어요.","먼저와 나중을 견줘요.","알게 된 점과 지킬 점을 써요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#1','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',1,'blank','auto','「운동하는 물체는 (    )이 지남에 따라 물체의 위치가 변합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X05']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C3","difficulty":1,"kind":"blank","stem":"「운동하는 물체는 (    )이 지남에 따라 물체의 위치가 변합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"시간","correct":true},{"t":"색깔","mis":"SC6-1-u2-X05"},{"t":"무게","mis":"SC6-1-u2-X05"},{"t":"크기","mis":"SC6-1-u2-X05"}],"explanation":["사진을 5초 간격으로 찍었어요.","시간이 흘렀어요.","시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#2','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',1,'mc','auto','운동하는 물체는 어느 것인가요?',ARRAY['SC6-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C3","difficulty":1,"kind":"mc","stem":"운동하는 물체는 어느 것인가요?","options":[{"t":"굴러가는 공","correct":true},{"t":"축구 골대","mis":"SC6-1-u2-X08"},{"t":"미끄럼틀","mis":"SC6-1-u2-X08"},{"t":"운동장의 나무","mis":"SC6-1-u2-X08"}],"explanation":["위치가 변하는 것을 찾아요.","공이 굴러가요.","굴러가는 공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#3','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C4',1,'ox','auto','철봉에 가만히 매달려 있는 것은 과학에서 말하는 운동이에요.',ARRAY['SC6-1-u2-X06']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C4","difficulty":1,"kind":"ox","stem":"철봉에 가만히 매달려 있는 것은 과학에서 말하는 운동이에요.","answer":"X","reason_options":[{"t":"시간이 지나도 위치가 변하지 않기 때문에","correct":true},{"t":"몸에 힘을 주고 있으면 운동이기 때문에","mis":"SC6-1-u2-X06"}],"mis":"SC6-1-u2-X06","explanation":["위치가 변했나요?","그 자리 그대로예요.","과학에서의 운동이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#4','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',1,'sa','auto','「시간이 지남에 따라 물체의 □□가 변할 때 물체가 운동한다고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u2-C3","difficulty":1,"kind":"sa","stem":"「시간이 지남에 따라 물체의 □□가 변할 때 물체가 운동한다고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["위치"],"explanation":["운동의 뜻이에요.","어디에 있는지예요.","위치예요."],"mis":"SC6-1-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#5','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C5',2,'mc','auto','5초 뒤에 다른 위치에 있는 것은 어느 것인가요?',ARRAY['SC6-1-u2-X08']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"mc","stem":"5초 뒤에 다른 위치에 있는 것은 어느 것인가요?","options":[{"t":"걸어가는 친구","correct":true},{"t":"책상","mis":"SC6-1-u2-X08"},{"t":"화분","mis":"SC6-1-u2-X08"},{"t":"책 읽는 친구","mis":"SC6-1-u2-X08"}],"explanation":["처음과 5초 뒤를 견줘요.","뒤쪽에서 앞쪽으로 갔어요.","걸어가는 친구예요."],"asset":{"type":"passage","lines":["책상 — 처음: 교실 가운데 · 5초 뒤: 교실 가운데","화분 — 처음: 창가 · 5초 뒤: 창가","창밖을 보는 친구 — 처음: 창가에 섬 · 5초 뒤: 창가에 그대로 섬","책 읽는 친구 — 처음: 자리에 앉음 · 5초 뒤: 자리에 그대로 앉음","걸어가는 친구 — 처음: 교실 뒤쪽 · 5초 뒤: 교실 앞쪽","시곗바늘 — 처음: 초바늘이 12 · 5초 뒤: 초바늘이 1"],"title":"5초 간격으로 찍은 두 사진 비교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#6','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',2,'match','auto','바닷가의 물체와 관찰한 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C3","difficulty":2,"kind":"match","stem":"바닷가의 물체와 관찰한 결과를 알맞게 이으세요.","pairs":[{"l":"갈매기","r":"하늘을 날아 시간이 지나면 위치가 변한다"},{"l":"배","r":"바다 위를 나아가 시간이 지나면 위치가 변한다"},{"l":"등대","r":"그 자리에 그대로 있어 운동하지 않는다"},{"l":"바위","r":"시간이 지나도 위치가 변하지 않아 운동하지 않는다"}],"mis":"SC6-1-u2-X08","explanation":["위치가 변하는지 봐요.","날거나 나아가면 변해요.","등대와 바위는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#7','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',2,'ox','auto','과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함돼요.',ARRAY['SC6-1-u2-X07']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C3","difficulty":2,"kind":"ox","stem":"과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함돼요.","answer":"O","reason_options":[{"t":"사람이나 동물도 시간이 지남에 따라 위치가 변하면 운동하는 물체이기 때문에","correct":true},{"t":"물체는 사람이 만든 물건만을 뜻하기 때문에","mis":"SC6-1-u2-X07"}],"mis":"SC6-1-u2-X07","explanation":["걸어가는 친구를 떠올려요.","운동하는 물체였어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#8','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C5',2,'error','auto','사진 관찰을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"error","stem":"사진 관찰을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「찍은 친구 사진을 누리망에 올려서 보여 주자.」","correct":true,"mis_target":"SC6-1-u2-X10"},{"t":"채윤 — 「관찰이 끝나면 찍은 사진을 삭제하자.」","mis":"SC6-1-u2-X10"},{"t":"도현 — 「창밖으로 손을 내밀지 말자.」","mis":"SC6-1-u2-X10"}],"explanation":["다른 사람을 찍은 사진이에요.","온라인에 올리지 않아요.","준서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#9','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C6',2,'mc','auto','같은 자동차를 두고 옳게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X09']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C6","difficulty":2,"kind":"mc","stem":"같은 자동차를 두고 옳게 말한 것은 어느 것인가요?","options":[{"t":"달릴 때는 운동하고, 주차되어 있을 때는 운동하지 않는다","correct":true},{"t":"자동차는 언제나 운동하는 물체이다","mis":"SC6-1-u2-X09"},{"t":"주차된 자동차도 운동하는 물체이다","mis":"SC6-1-u2-X09"},{"t":"운동하는 물체와 운동하지 않는 물체는 정해져 있다","mis":"SC6-1-u2-X09"}],"explanation":["달릴 때와 서 있을 때를 견줘요.","위치가 변할 때만 운동해요.","경우에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_basic#10','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C6',3,'mc','auto','물체가 운동하는지 판단할 때 무엇에 초점을 두어야 하나요?',ARRAY['SC6-1-u2-X05','SC6-1-u2-X11']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C6","difficulty":3,"kind":"mc","stem":"물체가 운동하는지 판단할 때 무엇에 초점을 두어야 하나요?","options":[{"t":"시간이 지난 뒤 물체의 위치가 변했는지","correct":true},{"t":"물체의 색깔이 변했는지","mis":"SC6-1-u2-X05"},{"t":"물체의 자세나 모양이 바뀌었는지","mis":"SC6-1-u2-X11"},{"t":"물체가 무거운지 가벼운지","mis":"SC6-1-u2-X05"}],"explanation":["운동의 뜻을 떠올려요.","모습이 아니에요.","위치가 변했는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#1','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C5',2,'sa','auto','시곗바늘의 초바늘은 처음에 12를 가리켰어요. 5초 뒤에는 어느 숫자를 가리키나요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"sa","stem":"시곗바늘의 초바늘은 처음에 12를 가리켰어요. 5초 뒤에는 어느 숫자를 가리키나요?","answer":["1"],"explanation":["기록을 읽어요.","5초 뒤 초바늘이에요.","1을 가리켜요."],"asset":{"type":"passage","lines":["책상 — 처음: 교실 가운데 · 5초 뒤: 교실 가운데","화분 — 처음: 창가 · 5초 뒤: 창가","창밖을 보는 친구 — 처음: 창가에 섬 · 5초 뒤: 창가에 그대로 섬","책 읽는 친구 — 처음: 자리에 앉음 · 5초 뒤: 자리에 그대로 앉음","걸어가는 친구 — 처음: 교실 뒤쪽 · 5초 뒤: 교실 앞쪽","시곗바늘 — 처음: 초바늘이 12 · 5초 뒤: 초바늘이 1"],"title":"5초 간격으로 찍은 두 사진 비교"},"mis":"SC6-1-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#2','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C5',2,'mc','auto','두 사진을 비교하는 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"mc","stem":"두 사진을 비교하는 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"삼각대에 스마트 기기 고정 → 5초 간격으로 두 번 찍기 → 두 사진 비교 → 운동하는 물체 이야기하기","correct":true},{"t":"5초 간격으로 두 번 찍기 → 삼각대에 스마트 기기 고정 → 두 사진 비교 → 운동하는 물체 이야기하기","mis":"SC6-1-u2-X08"},{"t":"두 사진 비교 → 삼각대에 스마트 기기 고정 → 5초 간격으로 두 번 찍기 → 운동하는 물체 이야기하기","mis":"SC6-1-u2-X08"},{"t":"삼각대에 스마트 기기 고정 → 한 번만 찍기 → 운동하는 물체 이야기하기 → 두 사진 비교","mis":"SC6-1-u2-X08"}],"explanation":["먼저 기기를 고정해요.","두 번 찍고 비교해요.","마지막에 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#3','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C6',3,'mc','auto','창밖을 보는 친구는 5초 동안 고개를 돌렸지만 창가 그 자리에 그대로 서 있었어요. 어떻게 판단하는 것이 알맞나요?',ARRAY['SC6-1-u2-X11','SC6-1-u2-X07','SC6-1-u2-X09']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C6","difficulty":3,"kind":"mc","stem":"창밖을 보는 친구는 5초 동안 고개를 돌렸지만 창가 그 자리에 그대로 서 있었어요. 어떻게 판단하는 것이 알맞나요?","options":[{"t":"위치가 변하지 않았으므로 운동하지 않는 물체로 본다","correct":true},{"t":"고개를 돌렸으니 운동하는 물체로 본다","mis":"SC6-1-u2-X11"},{"t":"사람은 물체가 아니라서 판단할 수 없다","mis":"SC6-1-u2-X07"},{"t":"사람은 언제나 운동하는 물체이다","mis":"SC6-1-u2-X09"}],"explanation":["5초 뒤 위치를 봐요.","창가 그대로예요.","운동하지 않는 물체예요."],"asset":{"type":"passage","lines":["책상 — 처음: 교실 가운데 · 5초 뒤: 교실 가운데","화분 — 처음: 창가 · 5초 뒤: 창가","창밖을 보는 친구 — 처음: 창가에 섬 · 5초 뒤: 창가에 그대로 섬","책 읽는 친구 — 처음: 자리에 앉음 · 5초 뒤: 자리에 그대로 앉음","걸어가는 친구 — 처음: 교실 뒤쪽 · 5초 뒤: 교실 앞쪽","시곗바늘 — 처음: 초바늘이 12 · 5초 뒤: 초바늘이 1"],"title":"5초 간격으로 찍은 두 사진 비교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#4','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C4',3,'error','auto','운동의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X05']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C4","difficulty":3,"kind":"error","stem":"운동의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「물 절약 운동에 참여한 우리 반은 과학에서 말하는 운동을 한 거야.」","correct":true,"mis_target":"SC6-1-u2-X06"},{"t":"시우 — 「과학에서 운동은 시간이 지남에 따라 위치가 변하는 거야.」","mis":"SC6-1-u2-X05"},{"t":"가람 — 「철봉에 가만히 매달린 건 과학에서는 운동이 아니야.」","mis":"SC6-1-u2-X06"}],"explanation":["운동의 여러 뜻을 떠올려요.","물 절약 운동은 사회적 운동이에요.","은재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#5','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C5',3,'mc','auto','공원의 두 장면에서 운동하는 물체만 모은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X08']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C5","difficulty":3,"kind":"mc","stem":"공원의 두 장면에서 운동하는 물체만 모은 것은 어느 것인가요?","options":[{"t":"자전거 타는 사람, 오리 배, 비행기, 달리는 사람","correct":true},{"t":"운동 기구, 의자, 오리 배","mis":"SC6-1-u2-X06"},{"t":"의자에 앉아 책 읽는 사람, 비행기","mis":"SC6-1-u2-X08"},{"t":"자전거 타는 사람, 의자, 운동 기구","mis":"SC6-1-u2-X08"}],"explanation":["처음과 얼마 뒤를 견줘요.","자리가 바뀐 것을 골라요.","넷이 움직였어요."],"asset":{"type":"passage","lines":["처음 — 자전거 타는 사람은 연못 왼쪽, 오리 배는 연못 가운데에 있다.","처음 — 비행기는 하늘 왼쪽, 달리는 사람은 정문 앞에 있다.","처음 — 운동 기구와 의자는 잔디밭 옆, 의자에 앉아 책 읽는 사람이 있다.","얼마 뒤 — 자전거 타는 사람은 연못 오른쪽, 오리 배는 연못 끝에 있다.","얼마 뒤 — 비행기는 하늘 오른쪽, 달리는 사람은 분수 옆에 있다.","얼마 뒤 — 운동 기구, 의자, 책 읽는 사람은 처음 자리 그대로이다."],"title":"공원의 처음 모습과 얼마 뒤 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#6','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C6',3,'ox','auto','지금 운동하지 않는 물체는 앞으로도 운동할 수 없어요.',ARRAY['SC6-1-u2-X09']::text[],false,'{"seq":6,"concept":"SC6-1-u2-C6","difficulty":3,"kind":"ox","stem":"지금 운동하지 않는 물체는 앞으로도 운동할 수 없어요.","answer":"X","reason_options":[{"t":"같은 물체도 운동할 때와 운동하지 않을 때가 있기 때문에","correct":true},{"t":"운동하는 물체와 운동하지 않는 물체는 정해져 있기 때문에","mis":"SC6-1-u2-X09"}],"mis":"SC6-1-u2-X09","explanation":["자동차를 떠올려요.","주차했다가 달려요.","운동할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#7','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C4',3,'match','auto','「운동」이라는 말의 쓰임과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-1-u2-C4","difficulty":3,"kind":"match","stem":"「운동」이라는 말의 쓰임과 뜻을 알맞게 이으세요.","pairs":[{"l":"신체의 운동","r":"몸을 단련하거나 건강을 위해 움직이는 일"},{"l":"사회적 운동","r":"목적을 이루려고 여럿이 힘쓰는 일"},{"l":"운동 경기","r":"규칙과 방법에 따라 기량을 겨루는 일"},{"l":"과학에서의 운동","r":"시간이 지남에 따라 물체의 위치가 변하는 것"}],"mis":"SC6-1-u2-X06","explanation":["같은 낱말, 다른 뜻이에요.","과학의 뜻은 하나예요.","위치가 변하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#8','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C3',4,'mc','auto','바닷가에서 개와 함께 산책하는 사람과 휠체어를 타고 이동하는 사람을 보았어요. 가장 알맞게 판단한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X07','SC6-1-u2-X11','SC6-1-u2-X09']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C3","difficulty":4,"kind":"mc","stem":"바닷가에서 개와 함께 산책하는 사람과 휠체어를 타고 이동하는 사람을 보았어요. 가장 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"시간이 지나 위치가 변했다면 사람과 개 모두 운동하는 물체이다","correct":true},{"t":"개는 동물이라 물체에 넣지 않는다","mis":"SC6-1-u2-X07"},{"t":"휠체어를 탄 사람은 앉아 있으니 운동하지 않는다","mis":"SC6-1-u2-X11"},{"t":"사람은 어느 때나 운동하는 물체이다","mis":"SC6-1-u2-X09"}],"explanation":["위치가 변했는지 봐요.","사람·동물도 물체예요.","모두 운동하는 물체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#9','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C5',4,'mc','auto','교실과 창밖을 관찰하는 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X10','SC6-1-u2-X08']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C5","difficulty":4,"kind":"mc","stem":"교실과 창밖을 관찰하는 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"삼각대가 쓰러지지 않는지 확인하고 타이머로 5초 간격 두 장을 찍은 뒤, 관찰이 끝나면 사진을 삭제한다","correct":true},{"t":"창밖으로 몸을 내밀어 찍고 바로 누리망에 올린다","mis":"SC6-1-u2-X10"},{"t":"손으로 들고 아무 때나 한 장만 찍는다","mis":"SC6-1-u2-X08"},{"t":"친구 얼굴이 잘 나오게 찍어 반 누리집에 올린다","mis":"SC6-1-u2-X10"}],"explanation":["안전과 개인 정보를 봐요.","두 장을 견줘야 해요.","끝나면 삭제해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L02_challenge#10','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C6',4,'essay','teacher','달리는 자동차와 주차된 자동차를 예로 들어 과학에서 말하는 「운동」의 뜻을 설명하고, 「철봉에 가만히 매달려 있어도 운동이다」라는 말이 왜 과학에서는 옳지 않은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C6","difficulty":4,"kind":"essay","stem":"달리는 자동차와 주차된 자동차를 예로 들어 과학에서 말하는 「운동」의 뜻을 설명하고, 「철봉에 가만히 매달려 있어도 운동이다」라는 말이 왜 과학에서는 옳지 않은지 쓰세요.","answer_guide":{"answer":"예: 과학에서는 시간이 지남에 따라 물체의 위치가 변할 때 물체가 운동한다고 한다. 달리는 자동차는 시간이 지나면 위치가 변하므로 운동하고, 주차된 자동차는 같은 위치에 있으므로 운동하지 않는다. 같은 자동차도 운동할 때와 운동하지 않을 때가 있다. 철봉에 가만히 매달려 있으면 몸에 힘은 들지만 시간이 지나도 위치가 변하지 않으므로 과학에서 말하는 운동이 아니다.","scoring_points":["운동의 뜻(시간에 따른 위치 변화)을 썼는가","두 자동차를 견주어 설명했는가","철봉 예가 옳지 않은 까닭을 위치로 설명했는가"]},"explanation":["운동의 뜻을 써요.","두 자동차를 견줘요.","철봉을 위치로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#1','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',1,'blank','auto','「물체의 운동은 물체가 이동하는 데 걸린 시간과 물체의 (    ) 변화로 표현합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X05']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"blank","stem":"「물체의 운동은 물체가 이동하는 데 걸린 시간과 물체의 (    ) 변화로 표현합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"위치","correct":true},{"t":"색깔","mis":"SC6-1-u2-X05"},{"t":"무게","mis":"SC6-1-u2-X05"},{"t":"크기","mis":"SC6-1-u2-X05"}],"explanation":["운동의 뜻을 떠올려요.","어디에 있는지가 바뀌어요.","위치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#2','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',1,'mc','auto','물체의 위치 변화는 무엇으로 나타내나요?',ARRAY['SC6-1-u2-X16','SC6-1-u2-X12','SC6-1-u2-X05']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"mc","stem":"물체의 위치 변화는 무엇으로 나타내나요?","options":[{"t":"처음 위치와 나중 위치","correct":true},{"t":"중간 위치와 나중 위치","mis":"SC6-1-u2-X16"},{"t":"처음 위치 하나","mis":"SC6-1-u2-X12"},{"t":"물체의 무게와 크기","mis":"SC6-1-u2-X05"}],"explanation":["어디서 어디로 갔나요?","시작한 곳과 도착한 곳이에요.","처음 위치와 나중 위치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#3','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C9',1,'sa','auto','정원판 놀이에서 꿀벌이 한 칸 이동할 때 걸리는 시간은 몇 초인가요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C9","difficulty":1,"kind":"sa","stem":"정원판 놀이에서 꿀벌이 한 칸 이동할 때 걸리는 시간은 몇 초인가요?","answer":["1","1초","일 초"],"explanation":["규칙을 읽어요.","한 칸에 걸리는 시간이에요.","1초예요."],"asset":{"type":"passage","lines":["꿀벌은 오른쪽·왼쪽·위쪽·아래쪽으로 한 칸씩만 이동한다.","한 칸 이동할 때 걸리는 시간은 1초이다.","꽃의 위치는 분수에서 꽃이 있는 방향과 칸 수로 말한다."],"title":"정원판 놀이 규칙"},"mis":"SC6-1-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#4','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',1,'ox','auto','「비둘기는 1분 동안 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.',ARRAY['SC6-1-u2-X12']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"ox","stem":"「비둘기는 1분 동안 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.","answer":"X","reason_options":[{"t":"처음 위치와 나중 위치가 빠졌기 때문에","correct":true},{"t":"걸린 시간만 있으면 운동을 표현할 수 있기 때문에","mis":"SC6-1-u2-X12"}],"mis":"SC6-1-u2-X12","explanation":["세 가지를 확인해요.","어디서 어디로가 없어요.","알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#5','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',2,'mc','auto','물체의 운동을 옳게 표현한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X12']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C7","difficulty":2,"kind":"mc","stem":"물체의 운동을 옳게 표현한 것은 어느 것인가요?","options":[{"t":"자전거를 타는 사람은 10분 동안 도서관에서 은행으로 이동했다","correct":true},{"t":"기차는 2시간 동안 서울로 이동했다","mis":"SC6-1-u2-X12"},{"t":"자동차는 3분 동안 시청에서 이동했다","mis":"SC6-1-u2-X12"},{"t":"사람은 공원에서 상점으로 이동했다","mis":"SC6-1-u2-X12"}],"explanation":["걸린 시간을 찾아요.","처음·나중 위치도 찾아요.","셋 다 있는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#6','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C8',2,'match','auto','정원판에서 꽃과 분수로부터의 위치를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C8","difficulty":2,"kind":"match","stem":"정원판에서 꽃과 분수로부터의 위치를 알맞게 이으세요.","pairs":[{"l":"수선화꽃","r":"왼쪽으로 3칸 떨어진 곳"},{"l":"제비꽃","r":"위쪽으로 2칸 떨어진 곳"},{"l":"유채꽃","r":"오른쪽으로 2칸, 위쪽으로 3칸 떨어진 곳"},{"l":"진달래꽃","r":"오른쪽으로 1칸, 아래쪽으로 1칸 떨어진 곳"}],"mis":"SC6-1-u2-X14","explanation":["분수에서 출발해 세어요.","방향과 칸 수를 함께 봐요.","두 방향이 필요한 꽃도 있어요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#7','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C9',2,'mc','auto','꿀벌이 제비꽃에서 유채꽃까지 가장 짧게 이동했어요. 걸린 시간은 몇 초인가요?',ARRAY['SC6-1-u2-X15']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C9","difficulty":2,"kind":"mc","stem":"꿀벌이 제비꽃에서 유채꽃까지 가장 짧게 이동했어요. 걸린 시간은 몇 초인가요?","options":[{"t":"3초","correct":true},{"t":"2초","mis":"SC6-1-u2-X15"},{"t":"5초","mis":"SC6-1-u2-X15"},{"t":"1초","mis":"SC6-1-u2-X15"}],"explanation":["오른쪽으로 몇 칸인가요?","위쪽으로 몇 칸인가요?","모두 3칸, 3초예요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#8','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',2,'error','auto','승강기의 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X13','SC6-1-u2-X12']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C7","difficulty":2,"kind":"error","stem":"승강기의 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「승강기가 15초 동안 1층에서 5층으로 갔으니 처음 위치는 5층이야.」","correct":true,"mis_target":"SC6-1-u2-X13"},{"t":"지호 — 「걸린 시간은 15초야.」","mis":"SC6-1-u2-X12"},{"t":"서준 — 「나중 위치는 5층이야.」","mis":"SC6-1-u2-X13"}],"explanation":["어디서 출발했나요?","1층에서 출발했어요.","하윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#9','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C9',2,'ox','auto','정원판 놀이에서 꿀벌은 대각선으로 한 번에 이동할 수도 있어요.',ARRAY['SC6-1-u2-X15']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C9","difficulty":2,"kind":"ox","stem":"정원판 놀이에서 꿀벌은 대각선으로 한 번에 이동할 수도 있어요.","answer":"X","reason_options":[{"t":"꿀벌은 오른쪽·왼쪽·위쪽·아래쪽으로 한 칸씩만 이동하기 때문에","correct":true},{"t":"가까운 꽃으로는 비스듬히 가도 되기 때문에","mis":"SC6-1-u2-X15"}],"mis":"SC6-1-u2-X15","explanation":["규칙을 다시 읽어요.","네 방향뿐이에요.","대각선은 안 돼요."],"asset":{"type":"passage","lines":["꿀벌은 오른쪽·왼쪽·위쪽·아래쪽으로 한 칸씩만 이동한다.","한 칸 이동할 때 걸리는 시간은 1초이다.","꽃의 위치는 분수에서 꽃이 있는 방향과 칸 수로 말한다."],"title":"정원판 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_basic#10','sci',6,1,'u2','L03','g6_1_sci_u2_L03_basic','lesson_basic','SC6-1-u2-C7',3,'mc','auto','「코딩 로봇이 10초 동안 입구에서 출구로 이동했다.」에서 처음 위치는 어디인가요?',ARRAY['SC6-1-u2-X13','SC6-1-u2-X12','SC6-1-u2-X16']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「코딩 로봇이 10초 동안 입구에서 출구로 이동했다.」에서 처음 위치는 어디인가요?","options":[{"t":"입구","correct":true},{"t":"출구","mis":"SC6-1-u2-X13"},{"t":"10초","mis":"SC6-1-u2-X12"},{"t":"입구와 출구의 가운데","mis":"SC6-1-u2-X16"}],"explanation":["어디서 출발했나요?","「~에서」가 처음이에요.","입구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#1','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C9',2,'sa','auto','꿀벌이 진달래꽃에서 유채꽃까지 가장 짧게 이동하면 몇 초가 걸리나요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C9","difficulty":2,"kind":"sa","stem":"꿀벌이 진달래꽃에서 유채꽃까지 가장 짧게 이동하면 몇 초가 걸리나요?","answer":["5","5초"],"explanation":["오른쪽으로 1칸이에요.","위쪽으로 4칸이에요.","모두 5칸, 5초예요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false},"mis":"SC6-1-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#2','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C8',2,'mc','auto','분수에서 오른쪽으로 2칸, 위쪽으로 3칸 떨어진 곳에 있는 꽃은 어느 것인가요?',ARRAY['SC6-1-u2-X14']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C8","difficulty":2,"kind":"mc","stem":"분수에서 오른쪽으로 2칸, 위쪽으로 3칸 떨어진 곳에 있는 꽃은 어느 것인가요?","options":[{"t":"유채꽃","correct":true},{"t":"제비꽃","mis":"SC6-1-u2-X14"},{"t":"진달래꽃","mis":"SC6-1-u2-X14"},{"t":"수선화꽃","mis":"SC6-1-u2-X14"}],"explanation":["분수에서 출발해요.","오른쪽 2칸, 위쪽 3칸이에요.","유채꽃이에요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#3','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C9',3,'mc','auto','꿀벌이 4초 동안 이동해 제비꽃에서 다른 꽃에 닿았어요. 꿀벌의 운동을 알맞게 표현한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X13','SC6-1-u2-X12']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C9","difficulty":3,"kind":"mc","stem":"꿀벌이 4초 동안 이동해 제비꽃에서 다른 꽃에 닿았어요. 꿀벌의 운동을 알맞게 표현한 것은 어느 것인가요?","options":[{"t":"꿀벌은 4초 동안 제비꽃에서 진달래꽃으로 이동했다","correct":true},{"t":"꿀벌은 4초 동안 진달래꽃에서 제비꽃으로 이동했다","mis":"SC6-1-u2-X13"},{"t":"꿀벌은 4초 동안 이동했다","mis":"SC6-1-u2-X12"},{"t":"꿀벌은 제비꽃에서 진달래꽃으로 이동했다","mis":"SC6-1-u2-X12"}],"explanation":["제비꽃에서 4칸인 꽃을 찾아요.","진달래꽃이에요.","세 가지를 모두 넣어요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#4','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C8',3,'error','auto','정원판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X14']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C8","difficulty":3,"kind":"error","stem":"정원판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「진달래꽃은 분수에서 아래쪽으로 1칸 떨어진 곳에 있어.」","correct":true,"mis_target":"SC6-1-u2-X14"},{"t":"예나 — 「수선화꽃은 분수에서 왼쪽으로 3칸 떨어진 곳에 있어.」","mis":"SC6-1-u2-X14"},{"t":"주원 — 「제비꽃은 분수에서 위쪽으로 2칸 떨어진 곳에 있어.」","mis":"SC6-1-u2-X14"}],"explanation":["진달래꽃 자리를 봐요.","오른쪽으로도 1칸 가야 해요.","라온이 잘못 말했어요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#5','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C7',3,'ox','auto','「야구 선수가 5초 동안 1루에서 2루로 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.',ARRAY['SC6-1-u2-X07']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C7","difficulty":3,"kind":"ox","stem":"「야구 선수가 5초 동안 1루에서 2루로 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.","answer":"O","reason_options":[{"t":"걸린 시간, 처음 위치, 나중 위치가 모두 들어 있기 때문에","correct":true},{"t":"선수는 사람이라서 물체의 운동이 아니기 때문에","mis":"SC6-1-u2-X07"}],"mis":"SC6-1-u2-X07","explanation":["세 가지를 찾아요.","5초, 1루, 2루예요.","알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#6','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C7',3,'match','auto','승강기가 15초 동안 1층에서 5층으로 이동했어요. 낱말과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C7","difficulty":3,"kind":"match","stem":"승강기가 15초 동안 1층에서 5층으로 이동했어요. 낱말과 알맞은 것을 이으세요.","pairs":[{"l":"걸린 시간","r":"15초"},{"l":"처음 위치","r":"1층"},{"l":"나중 위치","r":"5층"}],"mis":"SC6-1-u2-X13","explanation":["시간부터 찾아요.","출발한 곳이 처음이에요.","도착한 곳이 나중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#7','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C9',3,'mc','auto','꿀벌이 수선화꽃에서 출발해 분수를 지나 제비꽃까지 가장 짧게 이동했어요. 걸린 시간은 몇 초인가요?',ARRAY['SC6-1-u2-X15']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C9","difficulty":3,"kind":"mc","stem":"꿀벌이 수선화꽃에서 출발해 분수를 지나 제비꽃까지 가장 짧게 이동했어요. 걸린 시간은 몇 초인가요?","options":[{"t":"5초","correct":true},{"t":"3초","mis":"SC6-1-u2-X15"},{"t":"2초","mis":"SC6-1-u2-X15"},{"t":"6초","mis":"SC6-1-u2-X15"}],"explanation":["수선화꽃에서 분수까지 3칸이에요.","분수에서 제비꽃까지 2칸이에요.","모두 5칸, 5초예요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#8','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C8',4,'mc','auto','꿀벌이 진달래꽃에서 출발해 왼쪽으로 1칸, 위쪽으로 1칸 이동했어요. 꿀벌이 멈춘 곳은 어디인가요?',ARRAY['SC6-1-u2-X14']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C8","difficulty":4,"kind":"mc","stem":"꿀벌이 진달래꽃에서 출발해 왼쪽으로 1칸, 위쪽으로 1칸 이동했어요. 꿀벌이 멈춘 곳은 어디인가요?","options":[{"t":"분수","correct":true},{"t":"제비꽃","mis":"SC6-1-u2-X14"},{"t":"수선화꽃","mis":"SC6-1-u2-X14"},{"t":"유채꽃","mis":"SC6-1-u2-X14"}],"explanation":["진달래꽃 자리에서 출발해요.","왼쪽 1칸, 위쪽 1칸이에요.","분수에 닿아요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#9','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C7',4,'mc','auto','「기차가 출발역에서 도착역으로 이동했다.」를 운동의 표현으로 완성하려면 무엇을 더해야 하나요?',ARRAY['SC6-1-u2-X05','SC6-1-u2-X16','SC6-1-u2-X12']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C7","difficulty":4,"kind":"mc","stem":"「기차가 출발역에서 도착역으로 이동했다.」를 운동의 표현으로 완성하려면 무엇을 더해야 하나요?","options":[{"t":"이동하는 데 걸린 시간","correct":true},{"t":"기차의 색깔","mis":"SC6-1-u2-X05"},{"t":"출발역과 도착역의 가운데 역","mis":"SC6-1-u2-X16"},{"t":"아무것도 더하지 않아도 된다","mis":"SC6-1-u2-X12"}],"explanation":["세 가지를 확인해요.","처음·나중 위치는 있어요.","걸린 시간이 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L03_challenge#10','sci',6,1,'u2','L03','g6_1_sci_u2_L03_challenge','lesson_challenge','SC6-1-u2-C9',4,'essay','teacher','정원판에서 꿀벌을 제비꽃에서 출발시켜 다른 꽃 하나까지 가장 짧게 이동시키는 계획을 세우고, 이동한 방향과 칸 수, 걸린 시간을 쓰세요. 그리고 꿀벌의 운동을 걸린 시간·처음 위치·나중 위치가 모두 들어가게 한 문장으로 표현하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C9","difficulty":4,"kind":"essay","stem":"정원판에서 꿀벌을 제비꽃에서 출발시켜 다른 꽃 하나까지 가장 짧게 이동시키는 계획을 세우고, 이동한 방향과 칸 수, 걸린 시간을 쓰세요. 그리고 꿀벌의 운동을 걸린 시간·처음 위치·나중 위치가 모두 들어가게 한 문장으로 표현하세요.","answer_guide":{"answer":"예: 제비꽃에서 오른쪽으로 2칸, 위쪽으로 1칸 이동해 유채꽃에 닿는다. 모두 3칸을 이동했고 한 칸에 1초가 걸리므로 걸린 시간은 3초이다. 꿀벌은 3초 동안 제비꽃에서 유채꽃으로 이동했다.","scoring_points":["방향과 칸 수를 바르게 썼는가","칸 수로 걸린 시간을 바르게 구했는가","세 가지가 모두 들어간 문장으로 표현했는가"]},"explanation":["도착할 꽃을 골라요.","칸을 세어 시간을 구해요.","한 문장으로 표현해요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"분수"],[[20,140],"수선화"],[[140,60],"제비꽃"],[[220,20],"유채꽃"],[[180,180],"진달래"]],"cap":"정원판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#1','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C10',1,'blank','auto','「같은 시간 동안 이동한 물체는 이동 거리가 (    ) 더 빠릅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"blank","stem":"「같은 시간 동안 이동한 물체는 이동 거리가 (    ) 더 빠릅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"길수록","correct":true},{"t":"짧을수록","mis":"SC6-1-u2-X17"},{"t":"무거울수록","mis":"SC6-1-u2-X20"},{"t":"밝을수록","mis":"SC6-1-u2-X20"}],"explanation":["같은 시간이에요.","더 멀리 간 쪽이에요.","길수록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#2','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C10',1,'mc','auto','5초 동안 더 긴 거리를 이동한 태엽 자동차는 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"mc","stem":"5초 동안 더 긴 거리를 이동한 태엽 자동차는 어느 것인가요?","options":[{"t":"빨간색 자동차","correct":true},{"t":"파란색 자동차","mis":"SC6-1-u2-X17"},{"t":"두 자동차가 같다","mis":"SC6-1-u2-X17"},{"t":"알 수 없다","mis":"SC6-1-u2-X20"}],"explanation":["5초 뒤 기록을 봐요.","135 cm와 122 cm예요.","빨간색이에요."],"asset":{"type":"passage","lines":["같은 출발선에서 두 태엽 자동차를 동시에 출발시켰다.","1초 뒤 — 빨간색 27 cm · 파란색 24 cm","2초 뒤 — 빨간색 54 cm · 파란색 49 cm","3초 뒤 — 빨간색 81 cm · 파란색 73 cm","4초 뒤 — 빨간색 108 cm · 파란색 98 cm","5초 뒤 — 빨간색 135 cm · 파란색 122 cm"],"title":"5초 동안 이동한 거리(일의 자리까지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#3','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C10',1,'sa','auto','빨간색 자동차는 5초 동안 몇 cm를 이동했나요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"sa","stem":"빨간색 자동차는 5초 동안 몇 cm를 이동했나요?","answer":["135","135 cm","135cm"],"explanation":["5초 뒤 줄을 봐요.","빨간색 기록이에요.","135 cm예요."],"asset":{"type":"passage","lines":["같은 출발선에서 두 태엽 자동차를 동시에 출발시켰다.","1초 뒤 — 빨간색 27 cm · 파란색 24 cm","2초 뒤 — 빨간색 54 cm · 파란색 49 cm","3초 뒤 — 빨간색 81 cm · 파란색 73 cm","4초 뒤 — 빨간색 108 cm · 파란색 98 cm","5초 뒤 — 빨간색 135 cm · 파란색 122 cm"],"title":"5초 동안 이동한 거리(일의 자리까지)"},"mis":"SC6-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#4','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C11',1,'ox','auto','같은 시간 동안의 빠르기를 비교할 때는 두 자동차를 같은 출발선에서 동시에 출발시켜요.',ARRAY['SC6-1-u2-X18']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C11","difficulty":1,"kind":"ox","stem":"같은 시간 동안의 빠르기를 비교할 때는 두 자동차를 같은 출발선에서 동시에 출발시켜요.","answer":"O","reason_options":[{"t":"같은 출발선과 같은 출발 시각이어야 이동한 거리를 견줄 수 있기 때문에","correct":true},{"t":"먼저 출발한 자동차가 더 빠르게 보이게 하려고","mis":"SC6-1-u2-X18"}],"mis":"SC6-1-u2-X18","explanation":["같아야 하는 것을 떠올려요.","출발선과 출발 시각이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#5','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C10',2,'mc','auto','동시에 땅을 파기 시작해 동시에 땅 위로 나온 두더지와 개미 가운데 두더지가 더 길게 팠어요. 더 빠른 동물은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C10","difficulty":2,"kind":"mc","stem":"동시에 땅을 파기 시작해 동시에 땅 위로 나온 두더지와 개미 가운데 두더지가 더 길게 팠어요. 더 빠른 동물은 어느 것인가요?","options":[{"t":"두더지","correct":true},{"t":"개미","mis":"SC6-1-u2-X17"},{"t":"둘의 빠르기는 같다","mis":"SC6-1-u2-X17"},{"t":"몸이 무거운 쪽은 알 수 없다","mis":"SC6-1-u2-X20"}],"explanation":["걸린 시간이 같아요.","판 거리를 견줘요.","두더지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#6','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C13',2,'match','auto','1초 동안 이동할 수 있는 거리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C13","difficulty":2,"kind":"match","stem":"1초 동안 이동할 수 있는 거리를 알맞게 이으세요.","pairs":[{"l":"거북","r":"약 0.3 m"},{"l":"사람","r":"약 10 m"},{"l":"송골매","r":"약 108 m"},{"l":"드론","r":"약 133 m"}],"mis":"SC6-1-u2-X21","explanation":["자료를 하나씩 읽어요.","거북이 가장 짧아요.","드론이 가장 길어요."],"asset":{"type":"passage","lines":["거북 — 약 0.3 m","사람 — 약 10 m","루지 — 약 39 m","송골매 — 약 108 m","드론 — 약 133 m","※ 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값이다."],"title":"1초 동안 이동할 수 있는 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#7','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C11',2,'error','auto','실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X18']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C11","difficulty":2,"kind":"error","stem":"실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「빨간색 자동차를 먼저 보내고 잠시 뒤 파란색을 보내자.」","correct":true,"mis_target":"SC6-1-u2-X18"},{"t":"규리 — 「줄자는 출발선과 수직으로 펼치자.」","mis":"SC6-1-u2-X18"},{"t":"태윤 — 「경주로 전체가 보이게 기기를 삼각대에 고정하자.」","mis":"SC6-1-u2-X18"}],"explanation":["출발 시각을 봐요.","동시에 출발해야 해요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#8','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C12',2,'ox','auto','출발선이 달라도 지금 맨 앞에 있는 자동차가 언제나 가장 빨라요.',ARRAY['SC6-1-u2-X19']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C12","difficulty":2,"kind":"ox","stem":"출발선이 달라도 지금 맨 앞에 있는 자동차가 언제나 가장 빨라요.","answer":"X","reason_options":[{"t":"출발선이 다르면 앞에 있다고 해서 가장 빠르다고 할 수 없기 때문에","correct":true},{"t":"맨 앞에 있으면 무조건 가장 긴 거리를 갔기 때문에","mis":"SC6-1-u2-X19"}],"mis":"SC6-1-u2-X19","explanation":["출발한 곳이 달라요.","앞에서 출발했을 수 있어요.","언제나는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#9','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C11',2,'mc','auto','태엽 자동차 실험에서 지킬 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X20','SC6-1-u2-X18']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C11","difficulty":2,"kind":"mc","stem":"태엽 자동차 실험에서 지킬 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄자에 손을 다치지 않게 하고 태엽을 지나치게 감지 않는다","correct":true},{"t":"태엽을 끝까지 세게 감아 더 빠르게 한다","mis":"SC6-1-u2-X20"},{"t":"혼자서 모든 역할을 맡는다","mis":"SC6-1-u2-X18"},{"t":"줄자를 비스듬히 펼쳐 둔다","mis":"SC6-1-u2-X18"}],"explanation":["안전과 협력을 떠올려요.","태엽은 알맞게 감아요.","손을 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_basic#10','sci',6,1,'u2','L04','g6_1_sci_u2_L04_basic','lesson_basic','SC6-1-u2-C10',3,'mc','auto','1시간 동안 ㈎ 기차는 150 km, ㈏ 기차는 120 km를 이동했어요. 옳게 비교한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C10","difficulty":3,"kind":"mc","stem":"1시간 동안 ㈎ 기차는 150 km, ㈏ 기차는 120 km를 이동했어요. 옳게 비교한 것은 어느 것인가요?","options":[{"t":"㈎ 기차가 더 빠르다 — 같은 시간 동안 이동한 거리가 더 길기 때문","correct":true},{"t":"㈏ 기차가 더 빠르다 — 이동한 거리가 더 짧기 때문","mis":"SC6-1-u2-X17"},{"t":"두 기차의 빠르기는 같다 — 걸린 시간이 같기 때문","mis":"SC6-1-u2-X17"},{"t":"이동한 거리만으로는 비교할 수 없다","mis":"SC6-1-u2-X20"}],"explanation":["시간이 같아요.","거리를 견줘요.","㈎가 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#1','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C10',2,'sa','auto','3초 뒤 빨간색 자동차와 파란색 자동차는 몇 cm 차이가 나나요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C10","difficulty":2,"kind":"sa","stem":"3초 뒤 빨간색 자동차와 파란색 자동차는 몇 cm 차이가 나나요?","answer":["8","8 cm","8cm"],"explanation":["3초 뒤 줄을 봐요.","81 cm와 73 cm예요.","8 cm 차이예요."],"asset":{"type":"passage","lines":["같은 출발선에서 두 태엽 자동차를 동시에 출발시켰다.","1초 뒤 — 빨간색 27 cm · 파란색 24 cm","2초 뒤 — 빨간색 54 cm · 파란색 49 cm","3초 뒤 — 빨간색 81 cm · 파란색 73 cm","4초 뒤 — 빨간색 108 cm · 파란색 98 cm","5초 뒤 — 빨간색 135 cm · 파란색 122 cm"],"title":"5초 동안 이동한 거리(일의 자리까지)"},"mis":"SC6-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#2','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C11',2,'mc','auto','같은 시간 실험에서 5초 뒤에 사진을 찍는 까닭은 무엇인가요?',ARRAY['SC6-1-u2-X18','SC6-1-u2-X20']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C11","difficulty":2,"kind":"mc","stem":"같은 시간 실험에서 5초 뒤에 사진을 찍는 까닭은 무엇인가요?","options":[{"t":"두 자동차가 같은 시간 동안 이동한 거리를 한 장면에서 견주려고","correct":true},{"t":"먼저 도착한 자동차를 찾으려고","mis":"SC6-1-u2-X18"},{"t":"자동차의 색깔을 기록하려고","mis":"SC6-1-u2-X20"},{"t":"자동차마다 찍는 시각을 다르게 하려고","mis":"SC6-1-u2-X18"}],"explanation":["같은 시간이 중요해요.","같은 순간을 찍어요.","거리를 한 번에 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#3','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C12',3,'mc','auto','파란색 자동차를 출발선보다 20 cm 앞에 놓고 두 자동차를 동시에 출발시켰더니 5초 뒤 파란색이 더 앞에 있었어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['SC6-1-u2-X19','SC6-1-u2-X18','SC6-1-u2-X20']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C12","difficulty":3,"kind":"mc","stem":"파란색 자동차를 출발선보다 20 cm 앞에 놓고 두 자동차를 동시에 출발시켰더니 5초 뒤 파란색이 더 앞에 있었어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"출발선이 달라 맨 앞에 있다고 더 빠르다고 할 수 없으니, 각자 이동한 거리를 견주어야 한다","correct":true},{"t":"맨 앞에 있는 파란색 자동차가 더 빠르다","mis":"SC6-1-u2-X19"},{"t":"동시에 출발했으니 출발선은 달라도 된다","mis":"SC6-1-u2-X18"},{"t":"파란색 자동차가 더 무거워서 앞에 있다","mis":"SC6-1-u2-X20"}],"explanation":["출발선이 같았나요?","파란색이 앞에서 출발했어요.","이동한 거리를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#4','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C10',3,'error','auto','기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X17']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C10","difficulty":3,"kind":"error","stem":"기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「파란색이 5초 동안 덜 갔으니 파란색이 더 빨라.」","correct":true,"mis_target":"SC6-1-u2-X17"},{"t":"소이 — 「5초 동안 빨간색이 더 길게 갔어.」","mis":"SC6-1-u2-X17"},{"t":"유찬 — 「1초 뒤에도 빨간색이 더 멀리 있었어.」","mis":"SC6-1-u2-X17"}],"explanation":["같은 시간이에요.","길게 간 쪽이 빨라요.","하람이 잘못 말했어요."],"asset":{"type":"passage","lines":["같은 출발선에서 두 태엽 자동차를 동시에 출발시켰다.","1초 뒤 — 빨간색 27 cm · 파란색 24 cm","2초 뒤 — 빨간색 54 cm · 파란색 49 cm","3초 뒤 — 빨간색 81 cm · 파란색 73 cm","4초 뒤 — 빨간색 108 cm · 파란색 98 cm","5초 뒤 — 빨간색 135 cm · 파란색 122 cm"],"title":"5초 동안 이동한 거리(일의 자리까지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#5','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C13',3,'ox','auto','자료에서 사람이 1초에 약 10 m를 이동한다는 것은 모든 사람이 언제나 그 빠르기로 달린다는 뜻이에요.',ARRAY['SC6-1-u2-X21']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C13","difficulty":3,"kind":"ox","stem":"자료에서 사람이 1초에 약 10 m를 이동한다는 것은 모든 사람이 언제나 그 빠르기로 달린다는 뜻이에요.","answer":"X","reason_options":[{"t":"공식 경기 기록을 바탕으로 나타낸 값이기 때문에","correct":true},{"t":"사람은 누구나 똑같은 빠르기로 달리기 때문에","mis":"SC6-1-u2-X21"}],"mis":"SC6-1-u2-X21","explanation":["자료 끝의 설명을 읽어요.","기록을 바탕으로 했어요.","언제나는 아니에요."],"asset":{"type":"passage","lines":["거북 — 약 0.3 m","사람 — 약 10 m","루지 — 약 39 m","송골매 — 약 108 m","드론 — 약 133 m","※ 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값이다."],"title":"1초 동안 이동할 수 있는 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#6','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C12',3,'match','auto','상황과 빠르기 비교 여부를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C12","difficulty":3,"kind":"match","stem":"상황과 빠르기 비교 여부를 알맞게 이으세요.","pairs":[{"l":"같은 출발선에서 동시에 출발해 5초 동안 달린 두 자동차","r":"이동한 거리로 비교할 수 있다"},{"l":"서로 다른 출발선에서 출발해 지금 맨 앞에 있는 자동차","r":"출발선이 달라 위치만으로 비교할 수 없다"},{"l":"먼저 출발해 앞서 달리고 있는 오토바이","r":"출발 시각이 달라 위치만으로 비교할 수 없다"}],"mis":"SC6-1-u2-X19","explanation":["출발선과 출발 시각을 봐요.","둘 다 같아야 해요.","하나만 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#7','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C13',3,'mc','auto','1초 동안 이동할 수 있는 거리 자료에서 가장 빠른 것과 가장 느린 것을 차례로 고른 것은 어느 것인가요?',ARRAY['SC6-1-u2-X21','SC6-1-u2-X17']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C13","difficulty":3,"kind":"mc","stem":"1초 동안 이동할 수 있는 거리 자료에서 가장 빠른 것과 가장 느린 것을 차례로 고른 것은 어느 것인가요?","options":[{"t":"드론, 거북","correct":true},{"t":"송골매, 사람","mis":"SC6-1-u2-X21"},{"t":"거북, 드론","mis":"SC6-1-u2-X17"},{"t":"루지, 거북","mis":"SC6-1-u2-X21"}],"explanation":["같은 1초예요.","거리가 가장 긴 것과 짧은 것이에요.","드론과 거북이에요."],"asset":{"type":"passage","lines":["거북 — 약 0.3 m","사람 — 약 10 m","루지 — 약 39 m","송골매 — 약 108 m","드론 — 약 133 m","※ 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값이다."],"title":"1초 동안 이동할 수 있는 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#8','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C10',4,'mc','auto','「무궁화꽃이 피었습니다」 놀이에서 술래가 외치는 동안 가장 멀리 간 친구가 있어요. 이 친구에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X19','SC6-1-u2-X02']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C10","difficulty":4,"kind":"mc","stem":"「무궁화꽃이 피었습니다」 놀이에서 술래가 외치는 동안 가장 멀리 간 친구가 있어요. 이 친구에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"술래가 외치는 같은 시간 동안 가장 긴 거리를 이동했으니 가장 빠르게 움직였다","correct":true},{"t":"가장 짧은 거리를 이동한 친구가 가장 빠르다","mis":"SC6-1-u2-X17"},{"t":"출발선이 달라도 앞에 있으면 가장 빠르다","mis":"SC6-1-u2-X19"},{"t":"놀이에서는 누가 이기는지만 중요하다","mis":"SC6-1-u2-X02"}],"explanation":["외치는 시간은 모두 같아요.","거리를 견줘요.","가장 멀리 간 친구가 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#9','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C11',4,'mc','auto','모둠이 실험한 뒤 「파란색 자동차가 출발 신호보다 늦게 출발했어.」라는 것을 알았어요. 가장 알맞은 다음 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X19','SC6-1-u2-X18','SC6-1-u2-X20']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C11","difficulty":4,"kind":"mc","stem":"모둠이 실험한 뒤 「파란색 자동차가 출발 신호보다 늦게 출발했어.」라는 것을 알았어요. 가장 알맞은 다음 행동은 어느 것인가요?","options":[{"t":"역할을 다시 나누고 신호에 맞춰 두 대를 동시에 출발시켜 다시 잰다","correct":true},{"t":"그대로 두고 맨 앞에 있는 자동차를 더 빠르다고 적는다","mis":"SC6-1-u2-X19"},{"t":"파란색 자동차를 혼자 다시 보내 시각을 다르게 찍는다","mis":"SC6-1-u2-X18"},{"t":"태엽을 더 세게 감아 늦은 만큼 따라잡게 한다","mis":"SC6-1-u2-X20"}],"explanation":["같은 시간이 깨졌어요.","동시에 출발해야 해요.","다시 재어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L04_challenge#10','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C12',4,'essay','teacher','「지금 맨 앞에 있는 자동차가 가장 빠르다」는 말이 언제 옳지 않은지 두 가지 경우를 들어 설명하고, 같은 시간 동안의 빠르기를 바르게 비교하는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C12","difficulty":4,"kind":"essay","stem":"「지금 맨 앞에 있는 자동차가 가장 빠르다」는 말이 언제 옳지 않은지 두 가지 경우를 들어 설명하고, 같은 시간 동안의 빠르기를 바르게 비교하는 방법을 쓰세요.","answer_guide":{"answer":"예: 출발선이 다를 때는 앞에서 출발한 자동차가 덜 이동하고도 맨 앞에 있을 수 있다. 동시에 출발하지 않았을 때도 먼저 출발한 자동차가 앞에 있을 수 있다. 그래서 맨 앞에 있다고 가장 빠르다고 할 수 없다. 같은 출발선에서 동시에 출발시킨 뒤 같은 시간 동안 이동한 거리를 재어, 이동 거리가 긴 자동차가 더 빠르다고 비교한다.","scoring_points":["출발선이 다른 경우를 설명했는가","동시에 출발하지 않은 경우를 설명했는가","바른 비교 방법(같은 출발선·동시 출발·이동 거리)을 썼는가"]},"explanation":["출발선을 떠올려요.","출발 시각을 떠올려요.","바른 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#1','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',1,'blank','auto','「같은 거리를 이동한 물체는 걸린 시간이 (    ) 더 빠릅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X20']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"blank","stem":"「같은 거리를 이동한 물체는 걸린 시간이 (    ) 더 빠릅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"짧을수록","correct":true},{"t":"길수록","mis":"SC6-1-u2-X22"},{"t":"무거울수록","mis":"SC6-1-u2-X20"},{"t":"밝을수록","mis":"SC6-1-u2-X20"}],"explanation":["같은 거리예요.","빨리 닿은 쪽이에요.","짧을수록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#2','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',1,'mc','auto','100 cm를 이동하는 데 걸린 시간을 보고 더 빠른 태엽 자동차를 고르면 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"mc","stem":"100 cm를 이동하는 데 걸린 시간을 보고 더 빠른 태엽 자동차를 고르면 어느 것인가요?","options":[{"t":"초록색 자동차","correct":true},{"t":"노란색 자동차","mis":"SC6-1-u2-X22"},{"t":"두 자동차가 같다","mis":"SC6-1-u2-X22"},{"t":"알 수 없다","mis":"SC6-1-u2-X24"}],"explanation":["거리가 같아요.","4.2초와 5.8초예요.","초록색이 더 빨라요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#3','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',1,'sa','auto','노란색 자동차가 100 cm를 이동하는 데 걸린 시간은 몇 초인가요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"sa","stem":"노란색 자동차가 100 cm를 이동하는 데 걸린 시간은 몇 초인가요?","answer":["5.8","5.8초"],"explanation":["기록을 읽어요.","노란색 줄이에요.","5.8초예요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"},"mis":"SC6-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#4','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C15',1,'ox','auto','같은 거리 실험에서는 태엽 자동차를 한 대씩 출발시켜 걸린 시간을 재요.',ARRAY['SC6-1-u2-X23']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C15","difficulty":1,"kind":"ox","stem":"같은 거리 실험에서는 태엽 자동차를 한 대씩 출발시켜 걸린 시간을 재요.","answer":"O","reason_options":[{"t":"한 대씩 보내야 초시계로 걸린 시간을 정확하고 편하게 잴 수 있기 때문에","correct":true},{"t":"두 대를 함께 보내면 결승선이 멀어지기 때문에","mis":"SC6-1-u2-X23"}],"mis":"SC6-1-u2-X23","explanation":["초시계를 떠올려요.","한 대씩이 정확해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#5','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',2,'mc','auto','수영 경기에서 순위를 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24','SC6-1-u2-X20']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"mc","stem":"수영 경기에서 순위를 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"출발선에서 결승선까지 걸린 시간이 짧은 순서대로 정한다","correct":true},{"t":"걸린 시간이 긴 순서대로 정한다","mis":"SC6-1-u2-X22"},{"t":"출발하고 3초 뒤 앞서 있는 순서대로 정한다","mis":"SC6-1-u2-X24"},{"t":"키가 큰 순서대로 정한다","mis":"SC6-1-u2-X20"}],"explanation":["모두 같은 거리를 헤엄쳐요.","시간을 재요.","짧은 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#6','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C16',2,'match','auto','운동 종목과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C16","difficulty":2,"kind":"match","stem":"운동 종목과 알맞은 설명을 이으세요.","pairs":[{"l":"쇼트트랙","r":"얼음으로 된 트랙을 돈다"},{"l":"조정","r":"보트를 타고 노를 저어 결승선까지 간다"},{"l":"봅슬레이","r":"썰매를 타고 얼음 트랙을 내려간다"},{"l":"알파인 스키","r":"눈으로 덮인 슬로프를 내려간다"}],"mis":"SC6-1-u2-X25","explanation":["자료를 읽어요.","얼음·보트·썰매·눈을 찾아요.","모두 걸린 시간을 재요."],"asset":{"type":"passage","lines":["달리기 — 트랙을 달리는 데 걸린 시간을 잰다.","조정 — 보트를 타고 노를 저어 결승선까지 간다. 뒤로 나아간다.","쇼트트랙 — 얼음으로 된 트랙을 돈다.","알파인 스키 — 눈으로 덮인 슬로프를 내려간다.","봅슬레이 — 썰매를 타고 얼음 트랙을 내려간다."],"title":"걸린 시간을 재는 운동 종목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#7','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C15',2,'error','auto','같은 거리 실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X23']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C15","difficulty":2,"kind":"error","stem":"같은 거리 실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「줄자를 경주로에 펼쳐 둔 채로 자동차를 보내자.」","correct":true,"mis_target":"SC6-1-u2-X23"},{"t":"보민 — 「자동차의 앞부분이 출발선에 오게 놓자.」","mis":"SC6-1-u2-X23"},{"t":"세하 — 「결승선은 출발선에서 수직으로 100 cm 떨어진 곳에 표시하자.」","mis":"SC6-1-u2-X23"}],"explanation":["줄자는 언제 쓰나요?","결승선을 표시할 때만이에요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#8','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',2,'ox','auto','같은 거리를 이동했다면 걸린 시간이 긴 물체가 더 빨라요.',ARRAY['SC6-1-u2-X22']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"ox","stem":"같은 거리를 이동했다면 걸린 시간이 긴 물체가 더 빨라요.","answer":"X","reason_options":[{"t":"같은 거리를 더 짧은 시간에 이동한 물체가 더 빠르기 때문에","correct":true},{"t":"오래 움직일수록 더 힘차게 움직이기 때문에","mis":"SC6-1-u2-X22"}],"mis":"SC6-1-u2-X22","explanation":["같은 거리예요.","빨리 닿을수록 빨라요.","짧은 쪽이 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#9','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C15',2,'mc','auto','같은 거리 실험에서 걸린 시간을 기록하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X23','SC6-1-u2-X20']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C15","difficulty":2,"kind":"mc","stem":"같은 거리 실험에서 걸린 시간을 기록하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞부분이 결승선에 닿은 시간을 반올림해 소수 첫째 자리까지 쓴다","correct":true},{"t":"뒷부분이 결승선을 지난 시간을 쓴다","mis":"SC6-1-u2-X23"},{"t":"어림으로 생각나는 시간을 쓴다","mis":"SC6-1-u2-X20"},{"t":"두 대를 함께 보내고 마지막에 닿은 시간만 쓴다","mis":"SC6-1-u2-X23"}],"explanation":["앞부분이 기준이에요.","반올림해요.","소수 첫째 자리까지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_basic#10','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',3,'mc','auto','50 m를 이동하는 데 ㈎는 9초, ㈏는 10초, ㈐는 8초가 걸렸어요. 1위를 한 친구와 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C14","difficulty":3,"kind":"mc","stem":"50 m를 이동하는 데 ㈎는 9초, ㈏는 10초, ㈐는 8초가 걸렸어요. 1위를 한 친구와 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"㈐ — 50 m를 이동하는 데 걸린 시간이 가장 짧기 때문","correct":true},{"t":"㈏ — 걸린 시간이 가장 길기 때문","mis":"SC6-1-u2-X22"},{"t":"㈎ — 걸린 시간이 가운데이기 때문","mis":"SC6-1-u2-X22"},{"t":"세 친구 모두 같다 — 이동한 거리가 같기 때문","mis":"SC6-1-u2-X24"}],"explanation":["거리가 같아요.","시간이 가장 짧은 친구예요.","㈐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#1','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',2,'sa','auto','초록색 자동차는 노란색 자동차보다 몇 초 먼저 결승선에 닿았나요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"sa","stem":"초록색 자동차는 노란색 자동차보다 몇 초 먼저 결승선에 닿았나요?","answer":["1.6","1.6초"],"explanation":["두 기록을 견줘요.","5.8에서 4.2를 빼요.","1.6초예요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"},"mis":"SC6-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#2','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C16',2,'mc','auto','봅슬레이에서 0.01초 차이로 순위가 정해지기도 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X24','SC6-1-u2-X22','SC6-1-u2-X20']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C16","difficulty":2,"kind":"mc","stem":"봅슬레이에서 0.01초 차이로 순위가 정해지기도 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"모든 선수가 같은 트랙을 내려가 걸린 시간으로 빠르기를 견주기 때문","correct":true},{"t":"선수마다 다른 길이의 트랙을 내려가기 때문","mis":"SC6-1-u2-X24"},{"t":"걸린 시간이 긴 선수가 1위이기 때문","mis":"SC6-1-u2-X22"},{"t":"썰매가 무거운 선수가 1위이기 때문","mis":"SC6-1-u2-X20"}],"explanation":["같은 트랙이에요.","시간을 재요.","아주 작은 차이도 견줘요."],"asset":{"type":"passage","lines":["달리기 — 트랙을 달리는 데 걸린 시간을 잰다.","조정 — 보트를 타고 노를 저어 결승선까지 간다. 뒤로 나아간다.","쇼트트랙 — 얼음으로 된 트랙을 돈다.","알파인 스키 — 눈으로 덮인 슬로프를 내려간다.","봅슬레이 — 썰매를 타고 얼음 트랙을 내려간다."],"title":"걸린 시간을 재는 운동 종목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#3','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',3,'mc','auto','걸린 시간으로 빠르기를 바로 비교할 수 있는 경우는 어느 것인가요?',ARRAY['SC6-1-u2-X24','SC6-1-u2-X19']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C14","difficulty":3,"kind":"mc","stem":"걸린 시간으로 빠르기를 바로 비교할 수 있는 경우는 어느 것인가요?","options":[{"t":"같은 거리를 헤엄쳐 결승선에 닿은 두 선수의 걸린 시간","correct":true},{"t":"서로 다른 거리를 달린 두 친구의 걸린 시간","mis":"SC6-1-u2-X24"},{"t":"걸린 시간을 재지 않고 지금 앞서 있는 선수","mis":"SC6-1-u2-X24"},{"t":"출발선이 다른 두 자동차의 지금 위치","mis":"SC6-1-u2-X19"}],"explanation":["거리가 같아야 해요.","시간을 재야 해요.","같은 거리의 두 선수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#4','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',3,'error','auto','100 cm 기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X22']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C14","difficulty":3,"kind":"error","stem":"100 cm 기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다올 — 「노란색이 더 오래 달렸으니 노란색이 더 빨라.」","correct":true,"mis_target":"SC6-1-u2-X22"},{"t":"하진 — 「두 자동차는 같은 100 cm를 이동했어.」","mis":"SC6-1-u2-X22"},{"t":"윤슬 — 「초록색이 더 짧은 시간에 닿았어.」","mis":"SC6-1-u2-X22"}],"explanation":["거리가 같아요.","시간이 짧을수록 빨라요.","다올이 잘못 말했어요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#5','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C16',3,'ox','auto','조정은 보트를 타고 결승선까지 가는 데 걸린 시간을 재는 경기예요.',ARRAY['SC6-1-u2-X25']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C16","difficulty":3,"kind":"ox","stem":"조정은 보트를 타고 결승선까지 가는 데 걸린 시간을 재는 경기예요.","answer":"O","reason_options":[{"t":"같은 거리를 노를 저어 가는 데 걸린 시간으로 빠르기를 견주기 때문에","correct":true},{"t":"조정은 걸린 시간이 아니라 노를 저은 횟수로 순위를 정하기 때문에","mis":"SC6-1-u2-X25"}],"mis":"SC6-1-u2-X25","explanation":["자료를 읽어요.","결승선까지 가요.","맞는 말이에요."],"asset":{"type":"passage","lines":["달리기 — 트랙을 달리는 데 걸린 시간을 잰다.","조정 — 보트를 타고 노를 저어 결승선까지 간다. 뒤로 나아간다.","쇼트트랙 — 얼음으로 된 트랙을 돈다.","알파인 스키 — 눈으로 덮인 슬로프를 내려간다.","봅슬레이 — 썰매를 타고 얼음 트랙을 내려간다."],"title":"걸린 시간을 재는 운동 종목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#6','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C15',3,'match','auto','실험에서 맡은 역할과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C15","difficulty":3,"kind":"match","stem":"실험에서 맡은 역할과 하는 일을 알맞게 이으세요.","pairs":[{"l":"초시계를 든 친구","r":"시작 단추를 누르며 「출발」을 외친다"},{"l":"자동차를 놓는 친구","r":"앞부분이 출발선에 오게 놓는다"},{"l":"기록하는 친구","r":"걸린 시간을 소수 첫째 자리까지 쓴다"}],"mis":"SC6-1-u2-X23","explanation":["역할을 나눠요.","서로 협력해요.","하는 일을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#7','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',3,'mc','auto','100 m 달리기에서 ㈎ 21초, ㈏ 30초, ㈐ 25초, ㈑ 27초가 걸렸어요. 빠른 순서대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C14","difficulty":3,"kind":"mc","stem":"100 m 달리기에서 ㈎ 21초, ㈏ 30초, ㈐ 25초, ㈑ 27초가 걸렸어요. 빠른 순서대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㈎, ㈐, ㈑, ㈏","correct":true},{"t":"㈏, ㈑, ㈐, ㈎","mis":"SC6-1-u2-X22"},{"t":"㈎, ㈏, ㈐, ㈑","mis":"SC6-1-u2-X24"},{"t":"㈐, ㈎, ㈑, ㈏","mis":"SC6-1-u2-X24"}],"explanation":["거리가 같아요.","짧은 시간부터예요.","21, 25, 27, 30초 순이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#8','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',4,'mc','auto','친구 셋이 서로 다른 거리를 달렸어요. 민규는 50 m를 9초, 아라는 60 m를 9초, 준이는 50 m를 11초에 달렸어요. 가장 알맞게 판단한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C14","difficulty":4,"kind":"mc","stem":"친구 셋이 서로 다른 거리를 달렸어요. 민규는 50 m를 9초, 아라는 60 m를 9초, 준이는 50 m를 11초에 달렸어요. 가장 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"민규와 준이는 거리가 같아 시간으로 견줄 수 있어 민규가 더 빠르고, 아라와 민규는 시간이 같아 거리로 견줄 수 있어 아라가 더 빠르다","correct":true},{"t":"준이가 가장 오래 달렸으니 가장 빠르다","mis":"SC6-1-u2-X22"},{"t":"세 친구는 거리가 달라 아무도 비교할 수 없다","mis":"SC6-1-u2-X24"},{"t":"걸린 시간만 보면 되니 민규와 아라는 빠르기가 같고 거리는 상관없다","mis":"SC6-1-u2-X24"}],"explanation":["같은 것을 먼저 찾아요.","거리가 같으면 시간으로, 시간이 같으면 거리로 견줘요.","아라가 가장 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#9','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C15',4,'mc','auto','모둠이 두 자동차를 한꺼번에 출발시켰더니 초시계 한 개로 두 시간을 정확히 재기 어려웠어요. 가장 알맞은 해결 방법은 어느 것인가요?',ARRAY['SC6-1-u2-X23','SC6-1-u2-X24','SC6-1-u2-X19']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C15","difficulty":4,"kind":"mc","stem":"모둠이 두 자동차를 한꺼번에 출발시켰더니 초시계 한 개로 두 시간을 정확히 재기 어려웠어요. 가장 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"한 대씩 출발시켜 각각 결승선까지 걸린 시간을 잰다","correct":true},{"t":"먼저 닿은 자동차만 재고 나머지는 어림한다","mis":"SC6-1-u2-X23"},{"t":"결승선을 자동차마다 다르게 옮겨 놓는다","mis":"SC6-1-u2-X24"},{"t":"지금 앞서 있는 자동차를 더 빠르다고 적는다","mis":"SC6-1-u2-X19"}],"explanation":["초시계는 하나예요.","정확하게 재야 해요.","한 대씩 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L05_challenge#10','sci',6,1,'u2','L05','g6_1_sci_u2_L05_challenge','lesson_challenge','SC6-1-u2-C14',4,'essay','teacher','같은 거리를 이동한 두 태엽 자동차의 기록을 보고 더 빠른 자동차를 까닭과 함께 쓰고, 같은 시간 동안의 비교 방법과 무엇이 다른지 견주어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C14","difficulty":4,"kind":"essay","stem":"같은 거리를 이동한 두 태엽 자동차의 기록을 보고 더 빠른 자동차를 까닭과 함께 쓰고, 같은 시간 동안의 비교 방법과 무엇이 다른지 견주어 설명하세요.","answer_guide":{"answer":"예: 두 자동차는 같은 100 cm를 이동했고 초록색 자동차가 4.2초, 노란색 자동차가 5.8초 걸렸으므로 걸린 시간이 더 짧은 초록색 자동차가 더 빠르다. 같은 시간 동안 비교할 때는 시간을 같게 하고 이동한 거리를 재어 거리가 긴 쪽이 빠르다고 했다. 같은 거리를 비교할 때는 거리를 같게 하고 걸린 시간을 재어 시간이 짧은 쪽이 빠르다고 한다.","scoring_points":["더 빠른 자동차와 까닭을 썼는가","같은 시간 비교 방법을 썼는가","두 방법이 무엇을 같게 하고 무엇을 재는지 견주었는가"]},"explanation":["기록을 읽어요.","같게 한 것을 찾아요.","잰 것을 견줘요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#1','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C17',1,'blank','auto','「물체의 속력은 이동 거리를 (    )(으)로 나누어 구합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X26','SC6-1-u2-X20']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C17","difficulty":1,"kind":"blank","stem":"「물체의 속력은 이동 거리를 (    )(으)로 나누어 구합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"걸린 시간","correct":true},{"t":"이동 거리","mis":"SC6-1-u2-X26"},{"t":"물체의 무게","mis":"SC6-1-u2-X20"},{"t":"물체의 크기","mis":"SC6-1-u2-X20"}],"explanation":["속력 구하는 법이에요.","거리를 시간으로 나눠요.","걸린 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#2','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C18',1,'mc','auto','「60 km/h」를 바르게 읽은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X28','SC6-1-u2-X27']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C18","difficulty":1,"kind":"mc","stem":"「60 km/h」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"육십 킬로미터 매 시","correct":true},{"t":"육십 킬로미터 매 초","mis":"SC6-1-u2-X28"},{"t":"육십 미터 매 시","mis":"SC6-1-u2-X28"},{"t":"육십 킬로미터","mis":"SC6-1-u2-X27"}],"explanation":["km는 킬로미터예요.","h는 시간이에요.","육십 킬로미터 매 시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#3','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C19',1,'sa','auto','자료에서 자전거의 속력은 몇 km/h인가요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C19","difficulty":1,"kind":"sa","stem":"자료에서 자전거의 속력은 몇 km/h인가요?","answer":["20","20 km/h","20km/h"],"explanation":["1시간 동안 간 거리예요.","20 km를 1시간에 갔어요.","20 km/h예요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"},"mis":"SC6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#4','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C18',1,'ox','auto','60 km/h는 1시간 동안 60 km를 이동한 것과 같은 빠르기예요.',ARRAY['SC6-1-u2-X28']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C18","difficulty":1,"kind":"ox","stem":"60 km/h는 1시간 동안 60 km를 이동한 것과 같은 빠르기예요.","answer":"O","reason_options":[{"t":"「매 시」는 1시간마다라는 뜻이기 때문에","correct":true},{"t":"km/h는 1초마다 움직인 거리를 나타내기 때문에","mis":"SC6-1-u2-X28"}],"mis":"SC6-1-u2-X28","explanation":["「매」의 뜻을 떠올려요.","하나하나마다예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#5','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C19',2,'mc','auto','자료의 다섯 교통수단 가운데 속력이 가장 빠른 것은 어느 것인가요?',ARRAY['SC6-1-u2-X31']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C19","difficulty":2,"kind":"mc","stem":"자료의 다섯 교통수단 가운데 속력이 가장 빠른 것은 어느 것인가요?","options":[{"t":"비행기","correct":true},{"t":"기차","mis":"SC6-1-u2-X31"},{"t":"자동차","mis":"SC6-1-u2-X31"},{"t":"배","mis":"SC6-1-u2-X31"}],"explanation":["속력을 각각 구해요.","단위가 모두 km/h예요.","900 km/h인 비행기예요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#6','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C17',2,'match','auto','교통수단과 속력을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C17","difficulty":2,"kind":"match","stem":"교통수단과 속력을 알맞게 이으세요.","pairs":[{"l":"자전거로 1시간 동안 20 km","r":"20 km/h"},{"l":"자동차로 2시간 동안 145 km","r":"72.5 km/h"},{"l":"기차로 3시간 동안 450 km","r":"150 km/h"},{"l":"배로 4시간 동안 138 km","r":"34.5 km/h"}],"mis":"SC6-1-u2-X26","explanation":["거리를 시간으로 나눠요.","145 ÷ 2, 450 ÷ 3이에요.","단위를 붙여요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#7','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C19',2,'error','auto','속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X29']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C19","difficulty":2,"kind":"error","stem":"속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「10 km/h가 5 m/s보다 빨라. 10이 5보다 크잖아.」","correct":true,"mis_target":"SC6-1-u2-X29"},{"t":"하율 — 「30 km/h보다 50 km/h가 더 빨라.」","mis":"SC6-1-u2-X29"},{"t":"로운 — 「4 m/s보다 7 m/s가 더 빨라.」","mis":"SC6-1-u2-X29"}],"explanation":["단위를 먼저 봐요.","km/h와 m/s는 달라요.","지유가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#8','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C20',2,'ox','auto','빨간색 자동차의 속력 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이에요.',ARRAY['SC6-1-u2-X30']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C20","difficulty":2,"kind":"ox","stem":"빨간색 자동차의 속력 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이에요.","answer":"X","reason_options":[{"t":"전체 이동 거리를 전체 걸린 시간으로 나누어 구한 값이기 때문에","correct":true},{"t":"속력은 언제나 매 초 똑같이 움직인 거리를 잰 것이기 때문에","mis":"SC6-1-u2-X30"}],"mis":"SC6-1-u2-X30","explanation":["기록을 떠올려요.","1초 뒤 27 cm, 2초 뒤 54 cm처럼 재지 않았어요.","전체로 구한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#9','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C17',2,'mc','auto','빨간색 자동차가 5초 동안 135 cm를 이동했어요. 속력을 바르게 구한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X26','SC6-1-u2-X27']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C17","difficulty":2,"kind":"mc","stem":"빨간색 자동차가 5초 동안 135 cm를 이동했어요. 속력을 바르게 구한 것은 어느 것인가요?","options":[{"t":"135 cm ÷ 5 s = 27.0 cm/s","correct":true},{"t":"5 s ÷ 135 cm","mis":"SC6-1-u2-X26"},{"t":"135 cm × 5 s","mis":"SC6-1-u2-X26"},{"t":"135 cm","mis":"SC6-1-u2-X27"}],"explanation":["거리를 시간으로 나눠요.","135를 5로 나눠요.","27.0 cm/s예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_basic#10','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C19',3,'mc','auto','치타는 50 m를 10초에, 호랑이는 100 m를 25초에 달릴 수 있어요. 더 빠른 동물과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X31','SC6-1-u2-X26']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C19","difficulty":3,"kind":"mc","stem":"치타는 50 m를 10초에, 호랑이는 100 m를 25초에 달릴 수 있어요. 더 빠른 동물과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"치타 — 치타의 속력은 5 m/s, 호랑이의 속력은 4 m/s이기 때문","correct":true},{"t":"호랑이 — 더 먼 거리를 달렸기 때문","mis":"SC6-1-u2-X31"},{"t":"호랑이 — 달린 시간이 더 길기 때문","mis":"SC6-1-u2-X31"},{"t":"두 동물의 빠르기는 같다","mis":"SC6-1-u2-X26"}],"explanation":["거리도 시간도 달라요.","속력을 구해요.","5 m/s가 4 m/s보다 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#1','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C17',2,'sa','auto','자료에서 기차의 속력은 몇 km/h인가요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C17","difficulty":2,"kind":"sa","stem":"자료에서 기차의 속력은 몇 km/h인가요?","answer":["150","150 km/h","150km/h"],"explanation":["450 km를 3시간에 갔어요.","450 ÷ 3이에요.","150 km/h예요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"},"mis":"SC6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#2','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C18',2,'mc','auto','「2 m/s」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X28','SC6-1-u2-X26']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C18","difficulty":2,"kind":"mc","stem":"「2 m/s」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"1초 동안 2 m를 이동한 것과 같은 빠르기","correct":true},{"t":"1시간 동안 2 m를 이동한 것과 같은 빠르기","mis":"SC6-1-u2-X28"},{"t":"2초 동안 1 m를 이동한 것과 같은 빠르기","mis":"SC6-1-u2-X26"},{"t":"2 m를 이동하는 데 1분이 걸린 빠르기","mis":"SC6-1-u2-X28"}],"explanation":["m/s는 미터 매 초예요.","1초마다예요.","1초에 2 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#3','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C19',3,'mc','auto','숫자만 보고 바로 빠르기를 비교할 수 없는 것은 어느 것인가요?',ARRAY['SC6-1-u2-X29']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C19","difficulty":3,"kind":"mc","stem":"숫자만 보고 바로 빠르기를 비교할 수 없는 것은 어느 것인가요?","options":[{"t":"20 cm/s와 3 km/h","correct":true},{"t":"30 km/h와 50 km/h","mis":"SC6-1-u2-X29"},{"t":"4 m/s와 7 m/s","mis":"SC6-1-u2-X29"},{"t":"24.4 cm/s와 27.0 cm/s","mis":"SC6-1-u2-X29"}],"explanation":["단위를 견줘요.","같은 단위끼리는 숫자로 견줘요.","단위가 다른 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#4','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C20',3,'error','auto','속력이 뜻하는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X30']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C20","difficulty":3,"kind":"error","stem":"속력이 뜻하는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태리 — 「72.5 km/h로 달린 자동차는 1시간째에도 2시간째에도 똑같이 72.5 km씩 갔어.」","correct":true,"mis_target":"SC6-1-u2-X30"},{"t":"누리 — 「속력은 전체 이동 거리를 전체 걸린 시간으로 나눈 값이야.」","mis":"SC6-1-u2-X30"},{"t":"이든 — 「속력으로 나타내면 빠르기를 정확히 전할 수 있어.」","mis":"SC6-1-u2-X30"}],"explanation":["속력을 어떻게 구했나요?","전체 거리 ÷ 전체 시간이에요.","태리가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#5','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C17',3,'ox','auto','속력은 숫자만 쓰고 단위는 쓰지 않아도 돼요.',ARRAY['SC6-1-u2-X27']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C17","difficulty":3,"kind":"ox","stem":"속력은 숫자만 쓰고 단위는 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"단위가 없으면 1초마다인지 1시간마다인지 알 수 없기 때문에","correct":true},{"t":"속력의 숫자는 어느 단위든 뜻이 같기 때문에","mis":"SC6-1-u2-X27"}],"mis":"SC6-1-u2-X27","explanation":["20만 쓰면 어떨까요?","무엇마다 얼마인지 몰라요.","단위를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#6','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C18',3,'match','auto','속력과 읽는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C18","difficulty":3,"kind":"match","stem":"속력과 읽는 방법을 알맞게 이으세요.","pairs":[{"l":"20 km/h","r":"이십 킬로미터 매 시"},{"l":"20 cm/s","r":"이십 센티미터 매 초"},{"l":"2 m/s","r":"이 미터 매 초"}],"mis":"SC6-1-u2-X28","explanation":["앞 단위부터 읽어요.","h는 시, s는 초예요.","「매」를 넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#7','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C17',3,'mc','auto','초록색 자동차가 100 cm를 이동하는 데 4.2초가 걸렸어요. 속력을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X26']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C17","difficulty":3,"kind":"mc","stem":"초록색 자동차가 100 cm를 이동하는 데 4.2초가 걸렸어요. 속력을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"100 cm ÷ 4.2 s","correct":true},{"t":"4.2 s ÷ 100 cm","mis":"SC6-1-u2-X26"},{"t":"100 cm × 4.2 s","mis":"SC6-1-u2-X26"},{"t":"100 cm − 4.2 s","mis":"SC6-1-u2-X26"}],"explanation":["거리를 시간으로 나눠요.","거리는 100 cm예요.","100 ÷ 4.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#8','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C19',4,'mc','auto','네 태엽 자동차의 속력이 빨간색 27.0 cm/s, 파란색 24.4 cm/s, 초록색 23.8 cm/s, 노란색 17.2 cm/s예요. 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X31','SC6-1-u2-X29']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C19","difficulty":4,"kind":"mc","stem":"네 태엽 자동차의 속력이 빨간색 27.0 cm/s, 파란색 24.4 cm/s, 초록색 23.8 cm/s, 노란색 17.2 cm/s예요. 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"단위가 모두 cm/s로 같으므로 빨간색, 파란색, 초록색, 노란색 순으로 빠르다","correct":true},{"t":"노란색이 가장 오래 달렸으니 가장 빠르다","mis":"SC6-1-u2-X31"},{"t":"잰 방법이 달라 속력으로도 비교할 수 없다","mis":"SC6-1-u2-X31"},{"t":"숫자가 작을수록 빠르므로 노란색이 가장 빠르다","mis":"SC6-1-u2-X29"}],"explanation":["단위를 먼저 봐요.","모두 cm/s예요.","숫자가 큰 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#9','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C20',4,'mc','auto','친구에게 빠르기를 전할 때 「아주 빨라」보다 「72.5 km/h야」라고 말하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X30','SC6-1-u2-X29','SC6-1-u2-X27']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C20","difficulty":4,"kind":"mc","stem":"친구에게 빠르기를 전할 때 「아주 빨라」보다 「72.5 km/h야」라고 말하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"숫자와 단위로 정확하게 전할 수 있어 다른 물체와 견주기 쉽다","correct":true},{"t":"매 시간 똑같이 72.5 km씩 갔다는 것까지 알려 준다","mis":"SC6-1-u2-X30"},{"t":"숫자가 크면 단위와 관계없이 늘 더 빠르다는 것을 알려 준다","mis":"SC6-1-u2-X29"},{"t":"걸린 시간을 몰라도 이동 거리만으로 알 수 있다","mis":"SC6-1-u2-X27"}],"explanation":["말로만 하면 어떨까요?","사람마다 다르게 느껴요.","숫자와 단위가 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L06_challenge#10','sci',6,1,'u2','L06','g6_1_sci_u2_L06_challenge','lesson_challenge','SC6-1-u2-C19',4,'essay','teacher','「자동차가 2시간 동안 145 km를 이동했다」와 「배가 4시간 동안 138 km를 이동했다」를 보고, 이동 거리와 걸린 시간이 모두 다를 때 빠르기를 비교하는 방법을 설명하고 어느 쪽이 더 빠른지 속력을 구해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C19","difficulty":4,"kind":"essay","stem":"「자동차가 2시간 동안 145 km를 이동했다」와 「배가 4시간 동안 138 km를 이동했다」를 보고, 이동 거리와 걸린 시간이 모두 다를 때 빠르기를 비교하는 방법을 설명하고 어느 쪽이 더 빠른지 속력을 구해 쓰세요.","answer_guide":{"answer":"예: 이동 거리도 걸린 시간도 다르면 같은 출발선에 놓고 견줄 수 없으므로 속력을 구해 비교한다. 속력은 이동 거리를 걸린 시간으로 나누어 구한다. 자동차는 145 km ÷ 2 h = 72.5 km/h, 배는 138 km ÷ 4 h = 34.5 km/h이다. 단위가 km/h로 같으므로 숫자가 큰 자동차가 더 빠르다.","scoring_points":["속력으로 비교해야 하는 까닭을 썼는가","두 속력을 바르게 구했는가","단위가 같음을 확인하고 더 빠른 쪽을 썼는가"]},"explanation":["비교 방법을 써요.","속력을 각각 구해요.","단위를 확인하고 견줘요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#1','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C23',1,'mc','auto','「자동차가 충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정해 주는 안전장치」는 어느 것인가요?',ARRAY['SC6-1-u2-X36']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C23","difficulty":1,"kind":"mc","stem":"「자동차가 충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정해 주는 안전장치」는 어느 것인가요?","options":[{"t":"안전띠","correct":true},{"t":"에어백","mis":"SC6-1-u2-X36"},{"t":"과속 방지턱","mis":"SC6-1-u2-X36"},{"t":"안전 울타리","mis":"SC6-1-u2-X36"}],"explanation":["좌석에 고정해요.","몸에 매는 띠예요.","안전띠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#2','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C22',1,'mc','auto','자동계단을 이용할 때 지켜야 할 안전 수칙은 어느 것인가요?',ARRAY['SC6-1-u2-X34']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C22","difficulty":1,"kind":"mc","stem":"자동계단을 이용할 때 지켜야 할 안전 수칙은 어느 것인가요?","options":[{"t":"뛰거나 걷지 않고 손잡이를 잡고 서서 이용한다","correct":true},{"t":"빨리 가려고 두 칸씩 뛰어 올라간다","mis":"SC6-1-u2-X34"},{"t":"손잡이를 잡지 않고 가운데에 서 있는다","mis":"SC6-1-u2-X34"},{"t":"친구와 자리를 바꾸며 이용한다","mis":"SC6-1-u2-X34"}],"explanation":["움직이는 계단이에요.","손잡이를 잡아요.","서서 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#3','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C21',1,'sa','auto','「운전자가 브레이크를 밟은 뒤 자동차가 완전히 멈출 때까지 움직인 거리」를 무엇이라고 하나요? (□□ □□)','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C21","difficulty":1,"kind":"sa","stem":"「운전자가 브레이크를 밟은 뒤 자동차가 완전히 멈출 때까지 움직인 거리」를 무엇이라고 하나요? (□□ □□)","answer":["제동 거리","제동거리"],"explanation":["자료 아래를 읽어요.","멈출 때까지의 거리예요.","제동 거리예요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"},"mis":"SC6-1-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#4','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C21',1,'ox','auto','속력이 빠른 물체는 바로 멈추기 어려워 안전사고가 날 위험이 더 커요.',ARRAY['SC6-1-u2-X33']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C21","difficulty":1,"kind":"ox","stem":"속력이 빠른 물체는 바로 멈추기 어려워 안전사고가 날 위험이 더 커요.","answer":"O","reason_options":[{"t":"속력이 빠를수록 브레이크를 밟은 뒤 멈출 때까지 더 많이 움직이기 때문에","correct":true},{"t":"속력이 빠르면 오히려 더 빨리 멈추기 때문에","mis":"SC6-1-u2-X33"}],"mis":"SC6-1-u2-X33","explanation":["제동 거리를 떠올려요.","빠를수록 길어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#5','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C21',2,'mc','auto','자료에서 마른 노면을 달리는 자동차의 속력이 30 km/h에서 60 km/h로 빨라지면 제동 거리는 어떻게 되나요?',ARRAY['SC6-1-u2-X33']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C21","difficulty":2,"kind":"mc","stem":"자료에서 마른 노면을 달리는 자동차의 속력이 30 km/h에서 60 km/h로 빨라지면 제동 거리는 어떻게 되나요?","options":[{"t":"1.5 m에서 10.1 m로 길어진다","correct":true},{"t":"10.1 m에서 1.5 m로 짧아진다","mis":"SC6-1-u2-X33"},{"t":"속력과 관계없이 그대로이다","mis":"SC6-1-u2-X33"},{"t":"브레이크를 밟는 순간 바로 멈춘다","mis":"SC6-1-u2-X33"}],"explanation":["마른 노면 칸을 봐요.","30과 60을 견줘요.","길어져요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#6','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C23',2,'match','auto','안전장치와 설치된 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C23","difficulty":2,"kind":"match","stem":"안전장치와 설치된 곳을 알맞게 이으세요.","pairs":[{"l":"에어백","r":"자동차에 설치한다"},{"l":"과속 방지턱","r":"도로에 설치해 속력을 줄이게 한다"},{"l":"과속 경보 시스템","r":"도로에서 자동차의 속력을 재어 알려 준다"}],"mis":"SC6-1-u2-X36","explanation":["어디에 있는지 떠올려요.","에어백은 차 안이에요.","방지턱과 경보는 도로예요."],"asset":{"type":"passage","lines":["안전띠 — 충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정한다.","에어백 — 빠른 속력으로 충돌할 때 공기주머니를 부풀려 보호한다.","차간 거리 유지 장치 — 앞차와의 안전거리를 유지하게 한다.","과속 방지턱 — 운전자가 속력을 줄이도록 유도한다.","안전 울타리 — 충돌할 때 충격을 흡수하고 보행자를 보호한다.","과속 경보 시스템 — 자동차의 속력을 실시간으로 재어 알려 준다."],"title":"안전장치와 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#7','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C22',2,'error','auto','안전 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X34']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C22","difficulty":2,"kind":"error","stem":"안전 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「킥보드를 탄 채로 횡단보도를 빨리 건너는 게 안전해.」","correct":true,"mis_target":"SC6-1-u2-X34"},{"t":"나래 — 「길을 걸을 때는 스마트 기기를 보지 않고 주위를 살펴야 해.」","mis":"SC6-1-u2-X34"},{"t":"도윤 — 「계단은 뛰지 않고 걸어서 오르내려야 해.」","mis":"SC6-1-u2-X34"}],"explanation":["횡단보도를 떠올려요.","내려서 건너요.","건우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#8','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C23',2,'ox','auto','안전장치가 있으면 속력이 빨라도 안전하므로 안전 수칙은 지키지 않아도 돼요.',ARRAY['SC6-1-u2-X37']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C23","difficulty":2,"kind":"ox","stem":"안전장치가 있으면 속력이 빨라도 안전하므로 안전 수칙은 지키지 않아도 돼요.","answer":"X","reason_options":[{"t":"안전장치가 있어도 안전 수칙을 함께 지켜야 사고를 줄일 수 있기 때문에","correct":true},{"t":"안전장치는 모든 사고를 막아 주기 때문에","mis":"SC6-1-u2-X37"}],"mis":"SC6-1-u2-X37","explanation":["장치와 수칙을 견줘요.","둘이 함께 필요해요.","지켜야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#9','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C24',2,'mc','auto','조사한 자료를 쓰고 나눌 때 알맞은 태도는 어느 것인가요?',ARRAY['SC6-1-u2-X38']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C24","difficulty":2,"kind":"mc","stem":"조사한 자료를 쓰고 나눌 때 알맞은 태도는 어느 것인가요?","options":[{"t":"믿을 만한 자료인지 확인하고 출처를 밝힌다","correct":true},{"t":"출처 없이 그대로 옮겨 쓴다","mis":"SC6-1-u2-X38"},{"t":"친구의 이름과 사진을 함께 누리망에 올린다","mis":"SC6-1-u2-X38"},{"t":"다른 모둠 글에 거친 말로 댓글을 단다","mis":"SC6-1-u2-X38"}],"explanation":["자료를 쓸 때 무엇을 밝히나요?","출처예요.","믿을 만한지도 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_basic#10','sci',6,1,'u2','L07','g6_1_sci_u2_L07_basic','lesson_basic','SC6-1-u2-C21',3,'mc','auto','속력에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X32','SC6-1-u2-X33']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C21","difficulty":3,"kind":"mc","stem":"속력에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"먼 곳까지 빠르게 갈 수 있어 편리하지만, 바로 멈추기 어려워 위험할 수도 있다","correct":true},{"t":"속력은 빠를수록 언제나 좋다","mis":"SC6-1-u2-X32"},{"t":"속력은 위험만 만들 뿐 생활에 도움이 되지 않는다","mis":"SC6-1-u2-X32"},{"t":"속력이 빨라도 브레이크만 밟으면 바로 멈춘다","mis":"SC6-1-u2-X33"}],"explanation":["좋은 점을 떠올려요.","위험한 점도 떠올려요.","둘 다 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#1','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C21',2,'sa','auto','자료에서 속력 50 km/h일 때 빙판길의 제동 거리는 몇 m인가요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C21","difficulty":2,"kind":"sa","stem":"자료에서 속력 50 km/h일 때 빙판길의 제동 거리는 몇 m인가요?","answer":["33.2","33.2 m","33.2m"],"explanation":["50 km/h 줄을 봐요.","빙판길 칸이에요.","33.2 m예요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"},"mis":"SC6-1-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#2','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C21',2,'mc','auto','학교 앞 도로에 차선을 지그재그로 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X32','SC6-1-u2-X33']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C21","difficulty":2,"kind":"mc","stem":"학교 앞 도로에 차선을 지그재그로 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"운전자가 도로 폭을 좁게 느껴 속력을 줄이도록 하려고","correct":true},{"t":"자동차가 더 빨리 지나가게 하려고","mis":"SC6-1-u2-X32"},{"t":"도로를 예쁘게 꾸미려고","mis":"SC6-1-u2-X32"},{"t":"브레이크 없이도 바로 멈추게 하려고","mis":"SC6-1-u2-X33"}],"explanation":["어디에 그렸나요?","학교 앞, 횡단보도 앞이에요.","속력을 줄이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#3','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C21',3,'mc','auto','같은 속력으로 달릴 때 비나 눈이 내리는 날 더 주의해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X33','SC6-1-u2-X32']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C21","difficulty":3,"kind":"mc","stem":"같은 속력으로 달릴 때 비나 눈이 내리는 날 더 주의해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"도로가 미끄러우면 제동 거리가 마른 노면보다 길어지기 때문","correct":true},{"t":"미끄러운 도로에서는 제동 거리가 짧아지기 때문","mis":"SC6-1-u2-X33"},{"t":"비가 오면 속력이 저절로 0이 되기 때문","mis":"SC6-1-u2-X33"},{"t":"비나 눈은 속력과 아무 관계가 없기 때문","mis":"SC6-1-u2-X32"}],"explanation":["자료에서 노면을 견줘요.","빙판길이 더 길어요.","미끄러우면 길어져요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#4','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C23',3,'error','auto','안전장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X36']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C23","difficulty":3,"kind":"error","stem":"안전장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「안전 울타리는 자동차의 속력을 실시간으로 재어 알려 줘.」","correct":true,"mis_target":"SC6-1-u2-X36"},{"t":"하준 — 「차간 거리 유지 장치는 앞차와의 안전거리를 유지하게 해.」","mis":"SC6-1-u2-X36"},{"t":"미르 — 「과속 방지턱은 운전자가 속력을 줄이도록 해.」","mis":"SC6-1-u2-X36"}],"explanation":["속력을 재어 알려 주는 것은 무엇인가요?","과속 경보 시스템이에요.","서윤이 잘못 말했어요."],"asset":{"type":"passage","lines":["안전띠 — 충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정한다.","에어백 — 빠른 속력으로 충돌할 때 공기주머니를 부풀려 보호한다.","차간 거리 유지 장치 — 앞차와의 안전거리를 유지하게 한다.","과속 방지턱 — 운전자가 속력을 줄이도록 유도한다.","안전 울타리 — 충돌할 때 충격을 흡수하고 보행자를 보호한다.","과속 경보 시스템 — 자동차의 속력을 실시간으로 재어 알려 준다."],"title":"안전장치와 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#5','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C22',3,'ox','auto','교통안전 수칙은 운전하는 어른들만 신경 쓰면 돼요.',ARRAY['SC6-1-u2-X35']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C22","difficulty":3,"kind":"ox","stem":"교통안전 수칙은 운전하는 어른들만 신경 쓰면 돼요.","answer":"X","reason_options":[{"t":"보행자인 어린이도 횡단보도·계단·자전거에서 지킬 수칙이 있어 나부터 실천해야 하기 때문에","correct":true},{"t":"어린이는 자동차를 운전하지 않아 안전과 관계없기 때문에","mis":"SC6-1-u2-X35"}],"mis":"SC6-1-u2-X35","explanation":["어린이가 지킬 수칙을 떠올려요.","횡단보도, 자전거가 있어요.","나부터 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#6','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C22',3,'match','auto','상황과 지켜야 할 안전 수칙을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C22","difficulty":3,"kind":"match","stem":"상황과 지켜야 할 안전 수칙을 알맞게 이으세요.","pairs":[{"l":"계단을 오르내릴 때","r":"뛰지 않고 걸어서 오르내린다"},{"l":"자전거를 탈 때","r":"보호 장비를 착용하고 알맞은 속력으로 탄다"},{"l":"자동차를 운전할 때","r":"어린이 보호 구역에서는 정해진 속력보다 천천히 달린다"},{"l":"횡단보도를 건널 때","r":"좌우를 살피며 천천히 건넌다"}],"mis":"SC6-1-u2-X34","explanation":["상황을 하나씩 봐요.","속력과 관계있어요.","알맞은 수칙을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#7','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C24',3,'mc','auto','모둠이 조사한 내용을 공유 플랫폼에 올리려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC6-1-u2-X38']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C24","difficulty":3,"kind":"mc","stem":"모둠이 조사한 내용을 공유 플랫폼에 올리려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"비슷한 내용끼리 묶어 출처와 함께 올리고, 다른 모둠 글에는 고운 말로 새로 알게 된 점을 댓글로 단다","correct":true},{"t":"모둠원 얼굴 사진과 집 주소를 함께 올려 누가 썼는지 알린다","mis":"SC6-1-u2-X38"},{"t":"찾은 글을 출처 없이 그대로 붙여 넣는다","mis":"SC6-1-u2-X38"},{"t":"다른 모둠 글은 읽지 않고 내 글만 올린다","mis":"SC6-1-u2-X38"}],"explanation":["나누는 방법을 떠올려요.","출처와 개인 정보를 봐요.","고운 말로 댓글을 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#8','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C21',4,'mc','auto','자료를 보고 「속력이 같아도 도로 상태에 따라 제동 거리가 다르다」를 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['SC6-1-u2-X33']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C21","difficulty":4,"kind":"mc","stem":"자료를 보고 「속력이 같아도 도로 상태에 따라 제동 거리가 다르다」를 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"30 km/h에서 마른 노면은 1.5 m, 빙판길은 10.7 m이다","correct":true},{"t":"마른 노면에서 30 km/h는 1.5 m, 60 km/h는 10.1 m이다","mis":"SC6-1-u2-X33"},{"t":"빙판길에서 50 km/h는 33.2 m, 60 km/h는 49.9 m이다","mis":"SC6-1-u2-X33"},{"t":"브레이크를 밟으면 어느 도로에서나 바로 멈춘다","mis":"SC6-1-u2-X33"}],"explanation":["속력을 같게 해요.","도로만 달라야 해요.","30 km/h의 두 칸이에요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#9','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C23',4,'mc','auto','「에어백이 있으니 안전띠는 매지 않아도 돼.」라고 말하는 친구에게 가장 알맞은 대답은 어느 것인가요?',ARRAY['SC6-1-u2-X37','SC6-1-u2-X36']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C23","difficulty":4,"kind":"mc","stem":"「에어백이 있으니 안전띠는 매지 않아도 돼.」라고 말하는 친구에게 가장 알맞은 대답은 어느 것인가요?","options":[{"t":"안전띠는 탑승자를 좌석에 고정하고 에어백은 충돌할 때 보호해 하는 일이 다르니 둘 다 필요하고, 수칙도 함께 지켜야 해","correct":true},{"t":"에어백이 있으면 속력이 빨라도 안전하니 괜찮아","mis":"SC6-1-u2-X37"},{"t":"안전띠와 에어백은 하는 일이 같아서 하나만 있으면 돼","mis":"SC6-1-u2-X36"},{"t":"안전장치는 도로에만 있어서 자동차 안에서는 상관없어","mis":"SC6-1-u2-X36"}],"explanation":["두 장치가 하는 일을 견줘요.","하는 일이 달라요.","둘 다 필요해요."],"asset":{"type":"passage","lines":["안전띠 — 충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정한다.","에어백 — 빠른 속력으로 충돌할 때 공기주머니를 부풀려 보호한다.","차간 거리 유지 장치 — 앞차와의 안전거리를 유지하게 한다.","과속 방지턱 — 운전자가 속력을 줄이도록 유도한다.","안전 울타리 — 충돌할 때 충격을 흡수하고 보행자를 보호한다.","과속 경보 시스템 — 자동차의 속력을 실시간으로 재어 알려 준다."],"title":"안전장치와 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L07_challenge#10','sci',6,1,'u2','L07','g6_1_sci_u2_L07_challenge','lesson_challenge','SC6-1-u2-C21',4,'essay','teacher','속력이 우리 생활에 주는 편리한 점과 위험한 점을 하나씩 쓰고, 제동 거리 자료를 근거로 비나 눈이 오는 날 자동차가 어떻게 달려야 하는지, 그리고 보행자인 내가 지킬 안전 수칙 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C21","difficulty":4,"kind":"essay","stem":"속력이 우리 생활에 주는 편리한 점과 위험한 점을 하나씩 쓰고, 제동 거리 자료를 근거로 비나 눈이 오는 날 자동차가 어떻게 달려야 하는지, 그리고 보행자인 내가 지킬 안전 수칙 한 가지를 쓰세요.","answer_guide":{"answer":"예: 속력이 빠르면 먼 곳까지 빠르게 갈 수 있어 편리하지만, 바로 멈추기 어려워 안전사고가 날 위험이 커진다. 자료에서 30 km/h로 달릴 때 마른 노면의 제동 거리는 1.5 m인데 빙판길은 10.7 m로 훨씬 길다. 그래서 비나 눈이 오는 날에는 자동차가 평소보다 천천히 달리고 앞차와의 거리를 넉넉히 두어야 한다. 보행자인 나는 횡단보도를 건널 때 스마트 기기를 보지 않고 좌우를 살피며 건넌다.","scoring_points":["편리한 점과 위험한 점을 썼는가","제동 거리 자료를 근거로 들었는가","보행자의 안전 수칙을 썼는가"]},"explanation":["두 면을 써요.","자료를 근거로 들어요.","나의 수칙을 써요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#1','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C25',1,'mc','auto','교통안전 실천 점검표를 만드는 까닭은 무엇인가요?',ARRAY['SC6-1-u2-X39','SC6-1-u2-X40']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"mc","stem":"교통안전 실천 점검표를 만드는 까닭은 무엇인가요?","options":[{"t":"매일 실천하고 있는지 스스로 점검하기 위해서","correct":true},{"t":"친구보다 표시를 더 많이 하기 위해서","mis":"SC6-1-u2-X39"},{"t":"도화지를 예쁘게 꾸미는 연습을 하기 위해서","mis":"SC6-1-u2-X40"},{"t":"한 번 만들고 끝내기 위해서","mis":"SC6-1-u2-X40"}],"explanation":["수칙은 한 번 안다고 지켜지지 않아요.","매일 실천해야 해요.","스스로 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#2','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C27',1,'mc','auto','선수의 등에 붙여 위치와 속력을 실시간으로 재는 첨단 기술은 어느 것인가요?',ARRAY['SC6-1-u2-X42']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C27","difficulty":1,"kind":"mc","stem":"선수의 등에 붙여 위치와 속력을 실시간으로 재는 첨단 기술은 어느 것인가요?","options":[{"t":"움직임 센서","correct":true},{"t":"초고속 카메라","mis":"SC6-1-u2-X42"},{"t":"3D 선수 추적 기술","mis":"SC6-1-u2-X42"},{"t":"가상 현실 관람 기술","mis":"SC6-1-u2-X42"}],"explanation":["선수 몸에 붙여요.","위치와 속력을 재요.","움직임 센서예요."],"asset":{"type":"passage","lines":["움직임 센서 — 선수의 등에 붙여 위치와 속력을 실시간으로 잰다.","초고속 카메라 — 결승선에서 1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다.","3D 선수 추적 기술 — 경기장 둘레의 여러 카메라로 선수의 움직임을 삼차원으로 보여 준다."],"title":"스포츠에 활용하는 첨단 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#3','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C25',1,'ox','auto','점검표에는 실천한 날만 양심적으로 표시해요.',ARRAY['SC6-1-u2-X39']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"ox","stem":"점검표에는 실천한 날만 양심적으로 표시해요.","answer":"O","reason_options":[{"t":"표시를 채우는 것이 아니라 실제로 실천했는지 점검하는 것이기 때문에","correct":true},{"t":"칸을 모두 채워야 좋은 점검표이기 때문에","mis":"SC6-1-u2-X39"}],"mis":"SC6-1-u2-X39","explanation":["점검표의 목적이에요.","정직하게 표시해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#4','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C25',1,'sa','auto','점검표의 뒤 칸은 며칠 단위로 만드나요? (□일)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"sa","stem":"점검표의 뒤 칸은 며칠 단위로 만드나요? (□일)","answer":["7","7일","칠일"],"explanation":["월요일부터 일요일까지예요.","일주일이에요.","7일이에요."],"asset":{"type":"passage","lines":["수칙 ① 횡단보도에서 한 발짝 뒤에 서서 신호를 기다린다.","수칙 ② 신호등이 바뀌면 좌우를 살피고 건넌다.","수칙 ③ 자동차를 타면 안전띠를 맨다.","앞 칸 — 지켜야 할 수칙 · 뒤 칸 — 월~일 일주일 점검표","만든 점검표는 책상 옆 잘 보이는 곳에 세워 둔다."],"title":"우리 모둠 병풍 책 점검표 계획"},"mis":"SC6-1-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#5','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C25',2,'mc','auto','병풍 책 점검표의 앞 칸과 뒤 칸에 쓸 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X40']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C25","difficulty":2,"kind":"mc","stem":"병풍 책 점검표의 앞 칸과 뒤 칸에 쓸 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 칸에는 지켜야 할 수칙, 뒤 칸에는 일주일 점검표","correct":true},{"t":"앞 칸에는 받고 싶은 선물, 뒤 칸에는 친구 이름","mis":"SC6-1-u2-X40"},{"t":"앞 칸과 뒤 칸 모두 오늘 날짜만","mis":"SC6-1-u2-X40"},{"t":"앞 칸에는 그림만, 뒤 칸은 비워 둔다","mis":"SC6-1-u2-X40"}],"explanation":["계획을 읽어요.","수칙과 점검표예요.","앞은 수칙, 뒤는 점검표예요."],"asset":{"type":"passage","lines":["수칙 ① 횡단보도에서 한 발짝 뒤에 서서 신호를 기다린다.","수칙 ② 신호등이 바뀌면 좌우를 살피고 건넌다.","수칙 ③ 자동차를 타면 안전띠를 맨다.","앞 칸 — 지켜야 할 수칙 · 뒤 칸 — 월~일 일주일 점검표","만든 점검표는 책상 옆 잘 보이는 곳에 세워 둔다."],"title":"우리 모둠 병풍 책 점검표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#6','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C27',2,'match','auto','첨단 기술과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C27","difficulty":2,"kind":"match","stem":"첨단 기술과 하는 일을 알맞게 이으세요.","pairs":[{"l":"움직임 센서","r":"선수의 위치와 속력을 실시간으로 잰다"},{"l":"초고속 카메라","r":"1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다"},{"l":"3D 선수 추적 기술","r":"선수의 움직임을 삼차원으로 만들어 보여 준다"}],"mis":"SC6-1-u2-X42","explanation":["자료를 읽어요.","하는 일이 각각 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["움직임 센서 — 선수의 등에 붙여 위치와 속력을 실시간으로 잰다.","초고속 카메라 — 결승선에서 1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다.","3D 선수 추적 기술 — 경기장 둘레의 여러 카메라로 선수의 움직임을 삼차원으로 보여 준다."],"title":"스포츠에 활용하는 첨단 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#7','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C26',2,'error','auto','실천 결과를 나누며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X41']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C26","difficulty":2,"kind":"error","stem":"실천 결과를 나누며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「너는 세 번이나 못 지켰잖아. 왜 그렇게 못 했어?」","correct":true,"mis_target":"SC6-1-u2-X41"},{"t":"하늘 — 「스마트 기기를 보지 않고 건너려고 노력한 점이 좋았어.」","mis":"SC6-1-u2-X41"},{"t":"라희 — 「나는 다음 주에 안전띠를 더 잘 매도록 노력할게.」","mis":"SC6-1-u2-X41"}],"explanation":["친구를 대하는 태도를 봐요.","노력한 점을 칭찬해요.","지안이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#8','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C27',2,'ox','auto','첨단 기술이 있으면 선수는 연습하지 않아도 좋은 기록을 낼 수 있어요.',ARRAY['SC6-1-u2-X43']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C27","difficulty":2,"kind":"ox","stem":"첨단 기술이 있으면 선수는 연습하지 않아도 좋은 기록을 낼 수 있어요.","answer":"X","reason_options":[{"t":"첨단 기술은 공정한 판정과 기량 향상을 돕는 것이지 연습을 대신하지 않기 때문에","correct":true},{"t":"첨단 기술이 선수 대신 경기를 하기 때문에","mis":"SC6-1-u2-X43"}],"mis":"SC6-1-u2-X43","explanation":["기술이 하는 일을 떠올려요.","판정과 분석을 도와요.","연습은 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#9','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C25',2,'mc','auto','점검표에 넣을 수칙을 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X40']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C25","difficulty":2,"kind":"mc","stem":"점검표에 넣을 수칙을 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠원의 의견을 모아 함께 정한다","correct":true},{"t":"모둠장이 혼자 정한다","mis":"SC6-1-u2-X40"},{"t":"지키기 쉬운 수칙은 빼고 아무도 못 지킬 수칙만 고른다","mis":"SC6-1-u2-X40"},{"t":"수칙 없이 꾸미기부터 한다","mis":"SC6-1-u2-X40"}],"explanation":["모둠 활동이에요.","의견을 모아요.","함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_basic#10','sci',6,1,'u2','L08','g6_1_sci_u2_L08_basic','lesson_basic','SC6-1-u2-C27',3,'mc','auto','두 선수가 거의 동시에 결승선에 들어와 사람의 눈으로는 판단하기 어려워요. 무엇이 판정을 가장 잘 도울까요?',ARRAY['SC6-1-u2-X42','SC6-1-u2-X43']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C27","difficulty":3,"kind":"mc","stem":"두 선수가 거의 동시에 결승선에 들어와 사람의 눈으로는 판단하기 어려워요. 무엇이 판정을 가장 잘 도울까요?","options":[{"t":"결승선에서 1초에 수천 장을 찍는 초고속 카메라","correct":true},{"t":"선수의 등에 붙인 움직임 센서","mis":"SC6-1-u2-X42"},{"t":"경기를 가상 현실로 보여 주는 기술","mis":"SC6-1-u2-X42"},{"t":"기술 없이 관객이 손을 들어 정한다","mis":"SC6-1-u2-X43"}],"explanation":["결승선에서 무엇이 필요한가요?","아주 짧은 순간을 봐야 해요.","초고속 카메라예요."],"asset":{"type":"passage","lines":["움직임 센서 — 선수의 등에 붙여 위치와 속력을 실시간으로 잰다.","초고속 카메라 — 결승선에서 1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다.","3D 선수 추적 기술 — 경기장 둘레의 여러 카메라로 선수의 움직임을 삼차원으로 보여 준다."],"title":"스포츠에 활용하는 첨단 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#1','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',2,'sa','auto','점검표에 넣을 수칙은 모둠에서 몇 가지를 골랐나요?','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C25","difficulty":2,"kind":"sa","stem":"점검표에 넣을 수칙은 모둠에서 몇 가지를 골랐나요?","answer":["3","3가지","세 가지"],"explanation":["계획을 읽어요.","①, ②, ③이에요.","3가지예요."],"asset":{"type":"passage","lines":["수칙 ① 횡단보도에서 한 발짝 뒤에 서서 신호를 기다린다.","수칙 ② 신호등이 바뀌면 좌우를 살피고 건넌다.","수칙 ③ 자동차를 타면 안전띠를 맨다.","앞 칸 — 지켜야 할 수칙 · 뒤 칸 — 월~일 일주일 점검표","만든 점검표는 책상 옆 잘 보이는 곳에 세워 둔다."],"title":"우리 모둠 병풍 책 점검표 계획"},"mis":"SC6-1-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#2','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C27',2,'mc','auto','3D 선수 추적 기술이 주는 도움으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X43','SC6-1-u2-X42']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C27","difficulty":2,"kind":"mc","stem":"3D 선수 추적 기술이 주는 도움으로 알맞은 것은 어느 것인가요?","options":[{"t":"선수는 더 빠른 기록을 낼 방법을 찾고 관객은 경기에 더 몰입할 수 있다","correct":true},{"t":"선수가 연습하지 않아도 기록이 저절로 좋아진다","mis":"SC6-1-u2-X43"},{"t":"먼저 도착한 선수를 1초에 수천 장의 사진으로 가려낸다","mis":"SC6-1-u2-X42"},{"t":"선수의 등에 붙여 속력을 잰다","mis":"SC6-1-u2-X42"}],"explanation":["삼차원으로 보여 줘요.","선수와 관객 모두에게 도움을 줘요.","기록과 몰입이에요."],"asset":{"type":"passage","lines":["움직임 센서 — 선수의 등에 붙여 위치와 속력을 실시간으로 잰다.","초고속 카메라 — 결승선에서 1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다.","3D 선수 추적 기술 — 경기장 둘레의 여러 카메라로 선수의 움직임을 삼차원으로 보여 준다."],"title":"스포츠에 활용하는 첨단 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#3','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',3,'mc','auto','일주일 뒤 점검표에 빈칸이 두 개 남았어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X39','SC6-1-u2-X40']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C25","difficulty":3,"kind":"mc","stem":"일주일 뒤 점검표에 빈칸이 두 개 남았어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"빈칸은 그대로 두고 왜 못 지켰는지 생각해 다음 주에 더 노력한다","correct":true},{"t":"못 지킨 날도 표시해 칸을 모두 채운다","mis":"SC6-1-u2-X39"},{"t":"빈칸이 있으니 점검표를 버리고 실천을 그만둔다","mis":"SC6-1-u2-X40"},{"t":"잘 지킨 친구의 점검표를 보고 따라 표시한다","mis":"SC6-1-u2-X39"}],"explanation":["점검표는 점수판이 아니에요.","정직하게 남겨요.","다음 주에 더 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#4','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',3,'error','auto','점검표 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X40']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C25","difficulty":3,"kind":"error","stem":"점검표 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규민 — 「멋지게 보이게 만드는 방법을 최대한 복잡하고 어렵게 정하자.」","correct":true,"mis_target":"SC6-1-u2-X40"},{"t":"소연 — 「만든 점검표는 잘 보이는 곳에 두자.」","mis":"SC6-1-u2-X40"},{"t":"태현 — 「활동이 끝나도 수칙은 꾸준히 실천하자.」","mis":"SC6-1-u2-X40"}],"explanation":["만드는 방법을 떠올려요.","너무 복잡하지 않게 해요.","규민이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#5','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C26',3,'ox','auto','실천 결과를 발표할 때는 친구가 노력한 점을 찾아 칭찬해요.',ARRAY['SC6-1-u2-X41']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C26","difficulty":3,"kind":"ox","stem":"실천 결과를 발표할 때는 친구가 노력한 점을 찾아 칭찬해요.","answer":"O","reason_options":[{"t":"서로 격려하면 교통안전을 꾸준히 실천해 습관으로 만드는 데 도움이 되기 때문에","correct":true},{"t":"잘 못 지킨 친구를 가려내는 것이 발표의 목적이기 때문에","mis":"SC6-1-u2-X41"}],"mis":"SC6-1-u2-X41","explanation":["발표하는 까닭을 떠올려요.","함께 습관을 만들어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#6','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',3,'match','auto','점검표 모양과 만드는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C25","difficulty":3,"kind":"match","stem":"점검표 모양과 만드는 방법을 알맞게 이으세요.","pairs":[{"l":"병풍 책","r":"도화지를 접어 앞 칸에 수칙, 뒤 칸에 점검표를 만든다"},{"l":"화분","r":"화분 모양에 수칙을 붙이고 실천한 날 잎을 단다"},{"l":"수첩","r":"작은 수첩에 날마다 실천한 수칙을 적는다"}],"mis":"SC6-1-u2-X40","explanation":["여러 모양으로 만들 수 있어요.","모두 실천을 점검해요.","모양마다 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#7','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C27',3,'mc','auto','마라톤처럼 긴 거리를 달리는 경기에서 어떤 선수가 앞서는지 견주는 데 가장 알맞은 기술은 어느 것인가요?',ARRAY['SC6-1-u2-X42','SC6-1-u2-X43']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C27","difficulty":3,"kind":"mc","stem":"마라톤처럼 긴 거리를 달리는 경기에서 어떤 선수가 앞서는지 견주는 데 가장 알맞은 기술은 어느 것인가요?","options":[{"t":"선수의 위치와 속력을 실시간으로 재는 움직임 센서","correct":true},{"t":"결승선에만 놓인 초고속 카메라","mis":"SC6-1-u2-X42"},{"t":"경기를 가상 현실로 보여 주는 기술","mis":"SC6-1-u2-X42"},{"t":"기술 없이 선수의 이름으로 견준다","mis":"SC6-1-u2-X43"}],"explanation":["경기 중 내내 알아야 해요.","위치와 속력을 재요.","움직임 센서예요."],"asset":{"type":"passage","lines":["움직임 센서 — 선수의 등에 붙여 위치와 속력을 실시간으로 잰다.","초고속 카메라 — 결승선에서 1초에 수천 장을 찍어 먼저 도착한 선수를 보여 준다.","3D 선수 추적 기술 — 경기장 둘레의 여러 카메라로 선수의 움직임을 삼차원으로 보여 준다."],"title":"스포츠에 활용하는 첨단 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#8','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',4,'mc','auto','친구가 「점검표 칸을 다 채운 사람이 제일 잘한 거야.」라고 말했어요. 가장 알맞은 대답은 어느 것인가요?',ARRAY['SC6-1-u2-X39','SC6-1-u2-X40','SC6-1-u2-X41']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C25","difficulty":4,"kind":"mc","stem":"친구가 「점검표 칸을 다 채운 사람이 제일 잘한 거야.」라고 말했어요. 가장 알맞은 대답은 어느 것인가요?","options":[{"t":"칸을 채우는 것보다 실제로 꾸준히 실천해 습관이 되는 것이 중요하니, 실천한 날만 정직하게 표시하자","correct":true},{"t":"맞아, 못 지킨 날도 표시해서 칸을 채우자","mis":"SC6-1-u2-X39"},{"t":"그럼 점검표 없이 그냥 마음속으로만 하자","mis":"SC6-1-u2-X40"},{"t":"칸을 가장 적게 채운 친구를 발표 때 알려 주자","mis":"SC6-1-u2-X41"}],"explanation":["점검표의 목적을 떠올려요.","실천이 중요해요.","정직하게 표시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#9','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C27',4,'mc','auto','「경기에서 생기는 문제를 해결하는 첨단 기술」을 새로 떠올린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X43']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C27","difficulty":4,"kind":"mc","stem":"「경기에서 생기는 문제를 해결하는 첨단 기술」을 새로 떠올린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빠르게 날아온 축구공이 선수의 손에 닿았는지 알려 주는 감지기","correct":true},{"t":"선수 대신 경기를 뛰어 주는 기술","mis":"SC6-1-u2-X43"},{"t":"경기 결과를 미리 정해 두는 기술","mis":"SC6-1-u2-X43"},{"t":"선수의 연습을 없애 주는 기술","mis":"SC6-1-u2-X43"}],"explanation":["경기의 문제를 떠올려요.","반칙을 가리기 어려워요.","공정한 판정을 돕는 감지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_L08_challenge#10','sci',6,1,'u2','L08','g6_1_sci_u2_L08_challenge','lesson_challenge','SC6-1-u2-C25',4,'essay','teacher','우리 모둠 병풍 책 점검표 계획을 보고 잘 세운 점 두 가지를 까닭과 함께 쓰고, 일주일 동안 실천한 뒤 결과를 나눌 때 어떤 태도로 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C25","difficulty":4,"kind":"essay","stem":"우리 모둠 병풍 책 점검표 계획을 보고 잘 세운 점 두 가지를 까닭과 함께 쓰고, 일주일 동안 실천한 뒤 결과를 나눌 때 어떤 태도로 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 횡단보도·신호등·안전띠처럼 우리가 매일 겪는 상황의 수칙 세 가지를 골라 실천하기 쉽다. 둘째, 앞 칸에 수칙을, 뒤 칸에 일주일 점검표를 만들고 잘 보이는 곳에 두어 매일 확인할 수 있다. 실천한 날만 양심적으로 표시하고, 결과를 나눌 때는 친구의 발표를 바른 자세로 듣고 노력한 점을 칭찬하며, 못 지킨 점은 다음 주에 더 노력할 점으로 정한다.","scoring_points":["잘 세운 점 두 가지를 찾았는가","각각의 까닭을 썼는가","나누는 태도(정직한 표시·경청·칭찬)를 썼는가"]},"explanation":["계획을 하나씩 살펴요.","까닭을 붙여요.","나누는 태도를 써요."],"asset":{"type":"passage","lines":["수칙 ① 횡단보도에서 한 발짝 뒤에 서서 신호를 기다린다.","수칙 ② 신호등이 바뀌면 좌우를 살피고 건넌다.","수칙 ③ 자동차를 타면 안전띠를 맨다.","앞 칸 — 지켜야 할 수칙 · 뒤 칸 — 월~일 일주일 점검표","만든 점검표는 책상 옆 잘 보이는 곳에 세워 둔다."],"title":"우리 모둠 병풍 책 점검표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#1','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C3',1,'mc','auto','푸름반 일지 ①에서 10초 동안 운동한 사람은 누구인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X08']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C3","difficulty":1,"kind":"mc","stem":"푸름반 일지 ①에서 10초 동안 운동한 사람은 누구인가요?","options":[{"t":"서진","correct":true},{"t":"지우","mis":"SC6-1-u2-X06"},{"t":"학교 버스에 탄 사람이 없으니 아무도 없다","mis":"SC6-1-u2-X08"},{"t":"국기 게양대 옆의 사람","mis":"SC6-1-u2-X08"}],"explanation":["위치가 바뀐 사람을 찾아요.","정문 앞에서 화단 옆으로 갔어요.","서진이에요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#2','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C7',1,'mc','auto','물체의 운동을 표현할 때 꼭 넣어야 할 것을 모두 모은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X05','SC6-1-u2-X12','SC6-1-u2-X16']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"mc","stem":"물체의 운동을 표현할 때 꼭 넣어야 할 것을 모두 모은 것은 어느 것인가요?","options":[{"t":"걸린 시간, 처음 위치, 나중 위치","correct":true},{"t":"물체의 색깔, 모양, 무게","mis":"SC6-1-u2-X05"},{"t":"걸린 시간 하나","mis":"SC6-1-u2-X12"},{"t":"중간 위치와 나중 위치","mis":"SC6-1-u2-X16"}],"explanation":["세 가지예요.","시간과 두 위치예요.","걸린 시간, 처음 위치, 나중 위치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#3','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C10',1,'mc','auto','푸름반 일지 ③에서 가장 빠르게 달린 친구는 누구인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"mc","stem":"푸름반 일지 ③에서 가장 빠르게 달린 친구는 누구인가요?","options":[{"t":"바다","correct":true},{"t":"솔","mis":"SC6-1-u2-X17"},{"t":"하늘","mis":"SC6-1-u2-X17"},{"t":"셋 모두 같다","mis":"SC6-1-u2-X20"}],"explanation":["같은 10초예요.","가장 길게 간 친구예요.","55 m인 바다예요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#4','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C14',1,'mc','auto','푸름반 일지 ④에서 가장 빠르게 달린 친구는 누구인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"mc","stem":"푸름반 일지 ④에서 가장 빠르게 달린 친구는 누구인가요?","options":[{"t":"바다","correct":true},{"t":"솔","mis":"SC6-1-u2-X22"},{"t":"하늘","mis":"SC6-1-u2-X22"},{"t":"셋 모두 같다","mis":"SC6-1-u2-X24"}],"explanation":["같은 50 m예요.","가장 짧은 시간이에요.","9.0초인 바다예요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#5','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C17',1,'mc','auto','속력을 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X26']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C17","difficulty":1,"kind":"mc","stem":"속력을 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"이동 거리 ÷ 걸린 시간","correct":true},{"t":"걸린 시간 ÷ 이동 거리","mis":"SC6-1-u2-X26"},{"t":"이동 거리 × 걸린 시간","mis":"SC6-1-u2-X26"},{"t":"이동 거리 + 걸린 시간","mis":"SC6-1-u2-X26"}],"explanation":["거리를 시간으로 나눠요.","거리가 앞이에요.","이동 거리 ÷ 걸린 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#6','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C23',1,'mc','auto','푸름반 일지 ⑦에서 횡단보도 앞에 있어 운전자가 속력을 줄이도록 하는 것은 어느 것인가요?',ARRAY['SC6-1-u2-X36']::text[],false,'{"seq":6,"concept":"SC6-1-u2-C23","difficulty":1,"kind":"mc","stem":"푸름반 일지 ⑦에서 횡단보도 앞에 있어 운전자가 속력을 줄이도록 하는 것은 어느 것인가요?","options":[{"t":"과속 방지턱","correct":true},{"t":"에어백","mis":"SC6-1-u2-X36"},{"t":"안전띠","mis":"SC6-1-u2-X36"},{"t":"차간 거리 유지 장치","mis":"SC6-1-u2-X36"}],"explanation":["도로에 있는 것이에요.","횡단보도 앞에 있어요.","과속 방지턱이에요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#7','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C25',1,'mc','auto','푸름반 일지 ⑧에서 서아가 일주일 내내 표시한 수칙은 어느 것인가요?',ARRAY['SC6-1-u2-X40','SC6-1-u2-X39']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"mc","stem":"푸름반 일지 ⑧에서 서아가 일주일 내내 표시한 수칙은 어느 것인가요?","options":[{"t":"①","correct":true},{"t":"②","mis":"SC6-1-u2-X40"},{"t":"③","mis":"SC6-1-u2-X40"},{"t":"세 수칙 모두","mis":"SC6-1-u2-X39"}],"explanation":["표시한 날을 봐요.","7일인 것을 찾아요.","①이에요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#8','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C27',1,'mc','auto','초고속 카메라는 주로 어디에 놓이나요?',ARRAY['SC6-1-u2-X42']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C27","difficulty":1,"kind":"mc","stem":"초고속 카메라는 주로 어디에 놓이나요?","options":[{"t":"결승선","correct":true},{"t":"선수의 등","mis":"SC6-1-u2-X42"},{"t":"관객석 의자 밑","mis":"SC6-1-u2-X42"},{"t":"선수의 신발 속","mis":"SC6-1-u2-X42"}],"explanation":["누가 먼저 도착했는지 봐요.","도착하는 곳이에요.","결승선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#9','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C6',2,'mc','auto','푸름반 일지 ①의 학교 버스를 가장 알맞게 판단한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X09','SC6-1-u2-X05']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C6","difficulty":2,"kind":"mc","stem":"푸름반 일지 ①의 학교 버스를 가장 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"지금은 운동하지 않지만 출발해 위치가 변하면 운동하는 물체가 된다","correct":true},{"t":"버스는 언제나 운동하는 물체이다","mis":"SC6-1-u2-X09"},{"t":"한 번 서 있던 버스는 계속 운동할 수 없다","mis":"SC6-1-u2-X09"},{"t":"버스는 커서 운동하는 물체가 아니다","mis":"SC6-1-u2-X05"}],"explanation":["10초 동안 위치를 봐요.","그대로 서 있어요.","경우에 따라 달라요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#10','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C9',2,'mc','auto','푸름반 운동장 판의 로봇은 한 칸 이동하는 데 2초가 걸려요. 정문에서 화단까지 가장 짧게 이동하면 몇 초가 걸리나요?',ARRAY['SC6-1-u2-X15']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C9","difficulty":2,"kind":"mc","stem":"푸름반 운동장 판의 로봇은 한 칸 이동하는 데 2초가 걸려요. 정문에서 화단까지 가장 짧게 이동하면 몇 초가 걸리나요?","options":[{"t":"10초","correct":true},{"t":"5초","mis":"SC6-1-u2-X15"},{"t":"8초","mis":"SC6-1-u2-X15"},{"t":"12초","mis":"SC6-1-u2-X15"}],"explanation":["칸 수부터 세요.","왼쪽 2칸, 위쪽 3칸이에요.","5칸 × 2초 = 10초예요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#11','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C10',2,'mc','auto','푸름반 일지 ③의 세 친구를 빠른 순서대로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X20']::text[],false,'{"seq":11,"concept":"SC6-1-u2-C10","difficulty":2,"kind":"mc","stem":"푸름반 일지 ③의 세 친구를 빠른 순서대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"바다, 하늘, 솔","correct":true},{"t":"솔, 하늘, 바다","mis":"SC6-1-u2-X17"},{"t":"하늘, 바다, 솔","mis":"SC6-1-u2-X20"},{"t":"순서를 알 수 없다","mis":"SC6-1-u2-X20"}],"explanation":["같은 10초예요.","거리가 긴 순서예요.","55, 52, 48 m 순이에요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#12','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C14',2,'mc','auto','푸름반 일지 ④의 세 친구를 빠른 순서대로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":12,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"mc","stem":"푸름반 일지 ④의 세 친구를 빠른 순서대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"바다, 하늘, 솔","correct":true},{"t":"솔, 하늘, 바다","mis":"SC6-1-u2-X22"},{"t":"하늘, 솔, 바다","mis":"SC6-1-u2-X22"},{"t":"거리가 같아 순서를 알 수 없다","mis":"SC6-1-u2-X24"}],"explanation":["같은 50 m예요.","시간이 짧은 순서예요.","9.0, 9.4, 10.1초 순이에요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#13','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C19',2,'mc','auto','푸름반 일지 ⑤의 세 가지를 빠른 순서대로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X29','SC6-1-u2-X31','SC6-1-u2-X26']::text[],false,'{"seq":13,"concept":"SC6-1-u2-C19","difficulty":2,"kind":"mc","stem":"푸름반 일지 ⑤의 세 가지를 빠른 순서대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"기차, 버스, 자전거 동아리","correct":true},{"t":"자전거 동아리, 버스, 기차","mis":"SC6-1-u2-X29"},{"t":"버스, 기차, 자전거 동아리","mis":"SC6-1-u2-X31"},{"t":"셋 모두 같다","mis":"SC6-1-u2-X26"}],"explanation":["속력을 각각 구해요.","110, 80, 15 km/h예요.","기차, 버스, 자전거 순이에요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#14','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C21',2,'mc','auto','푸름반 일지 ⑦에서 학교 앞 차선을 지그재그로 그린 까닭은 무엇인가요?',ARRAY['SC6-1-u2-X32','SC6-1-u2-X33']::text[],false,'{"seq":14,"concept":"SC6-1-u2-C21","difficulty":2,"kind":"mc","stem":"푸름반 일지 ⑦에서 학교 앞 차선을 지그재그로 그린 까닭은 무엇인가요?","options":[{"t":"운전자가 도로 폭을 좁게 느껴 속력을 줄이게 하려고","correct":true},{"t":"자동차가 더 빨리 지나가게 하려고","mis":"SC6-1-u2-X32"},{"t":"도로를 꾸미려고","mis":"SC6-1-u2-X32"},{"t":"브레이크 없이도 바로 멈추게 하려고","mis":"SC6-1-u2-X33"}],"explanation":["학교 앞이에요.","속력과 관계있어요.","속력을 줄이게 해요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#15','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C25',2,'mc','auto','푸름반 일지 ⑧의 서아의 다짐이 알맞은 까닭은 무엇인가요?',ARRAY['SC6-1-u2-X39','SC6-1-u2-X40','SC6-1-u2-X41']::text[],false,'{"seq":15,"concept":"SC6-1-u2-C25","difficulty":2,"kind":"mc","stem":"푸름반 일지 ⑧의 서아의 다짐이 알맞은 까닭은 무엇인가요?","options":[{"t":"잘 지키지 못한 수칙을 찾아 다음 주에 더 노력하려 하기 때문","correct":true},{"t":"다음 주에는 칸을 모두 채우겠다는 다짐이기 때문","mis":"SC6-1-u2-X39"},{"t":"점검표를 그만두겠다는 다짐이기 때문","mis":"SC6-1-u2-X40"},{"t":"친구의 잘못을 찾겠다는 다짐이기 때문","mis":"SC6-1-u2-X41"}],"explanation":["다짐을 읽어요.","②와 ③을 더 지키려 해요.","노력하려는 다짐이에요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#16','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C27',2,'mc','auto','3D 선수 추적 기술은 무엇을 이용하나요?',ARRAY['SC6-1-u2-X42']::text[],false,'{"seq":16,"concept":"SC6-1-u2-C27","difficulty":2,"kind":"mc","stem":"3D 선수 추적 기술은 무엇을 이용하나요?","options":[{"t":"경기장 둘레에 설치한 여러 대의 카메라","correct":true},{"t":"선수의 등에 붙인 센서 하나","mis":"SC6-1-u2-X42"},{"t":"결승선에 놓인 카메라 한 대","mis":"SC6-1-u2-X42"},{"t":"관객의 휴대 전화","mis":"SC6-1-u2-X42"}],"explanation":["삼차원으로 보여 줘요.","여러 방향에서 찍어요.","여러 대의 카메라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#17','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C9',3,'mc','auto','푸름반 운동장 판의 로봇(한 칸에 2초)이 그네에서 정문까지 가장 짧게 이동하면 몇 초가 걸리나요?',ARRAY['SC6-1-u2-X15']::text[],false,'{"seq":17,"concept":"SC6-1-u2-C9","difficulty":3,"kind":"mc","stem":"푸름반 운동장 판의 로봇(한 칸에 2초)이 그네에서 정문까지 가장 짧게 이동하면 몇 초가 걸리나요?","options":[{"t":"12초","correct":true},{"t":"6초","mis":"SC6-1-u2-X15"},{"t":"10초","mis":"SC6-1-u2-X15"},{"t":"14초","mis":"SC6-1-u2-X15"}],"explanation":["칸 수부터 세요.","오른쪽 5칸, 아래쪽 1칸이에요.","6칸 × 2초 = 12초예요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#18','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C10',3,'error','auto','푸름반 일지 ⑥의 토론에서 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X22']::text[],false,'{"seq":18,"concept":"SC6-1-u2-C10","difficulty":3,"kind":"error","stem":"푸름반 일지 ⑥의 토론에서 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민재 — 「같은 시간 동안 짧게 간 자동차가 더 빨라.」","correct":true,"mis_target":"SC6-1-u2-X17"},{"t":"소율 — 「같은 시간이면 길게 간 쪽이 빨라.」","mis":"SC6-1-u2-X17"},{"t":"지후 — 「같은 거리면 짧은 시간에 간 쪽이 빨라.」","mis":"SC6-1-u2-X22"}],"explanation":["같은 시간이에요.","길게 간 쪽이 빨라요.","민재가 잘못 말했어요."],"asset":{"type":"passage","lines":["민재 — 「같은 시간 동안 짧게 간 자동차가 더 빨라.」","예린 — 「10 km/h가 5 m/s보다 빨라. 10이 더 크잖아.」","도하 — 「안전띠를 맸으니 학교 앞에서도 빨리 달려도 돼.」","선생님 — 세 친구의 말을 배운 내용으로 하나씩 따져 보자."],"title":"푸름반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#19','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C19',3,'ox','auto','푸름반 일지 ⑤에서 버스는 기차보다 짧은 시간 동안 달렸으니 기차보다 더 빨라요.',ARRAY['SC6-1-u2-X31']::text[],false,'{"seq":19,"concept":"SC6-1-u2-C19","difficulty":3,"kind":"ox","stem":"푸름반 일지 ⑤에서 버스는 기차보다 짧은 시간 동안 달렸으니 기차보다 더 빨라요.","answer":"X","reason_options":[{"t":"거리와 시간이 모두 다르므로 속력을 구해야 하고, 기차가 110 km/h로 더 빠르기 때문에","correct":true},{"t":"짧은 시간 동안 달린 쪽이 언제나 더 빠르기 때문에","mis":"SC6-1-u2-X31"}],"mis":"SC6-1-u2-X31","explanation":["거리도 시간도 달라요.","속력을 구해요.","기차가 더 빨라요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#20','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C20',3,'mc','auto','「빠르기를 속력으로 나타내면 의사소통하기에 편리하다」에 가장 잘 맞는 말은 어느 것인가요?',ARRAY['SC6-1-u2-X27','SC6-1-u2-X30']::text[],false,'{"seq":20,"concept":"SC6-1-u2-C20","difficulty":3,"kind":"mc","stem":"「빠르기를 속력으로 나타내면 의사소통하기에 편리하다」에 가장 잘 맞는 말은 어느 것인가요?","options":[{"t":"「버스는 80 km/h로 달렸어.」","correct":true},{"t":"「버스는 엄청 빨랐어.」","mis":"SC6-1-u2-X27"},{"t":"「버스는 160 km를 갔어.」","mis":"SC6-1-u2-X27"},{"t":"「버스는 매 시간 똑같이 80 km씩 갔어.」","mis":"SC6-1-u2-X30"}],"explanation":["숫자와 단위가 있나요?","빠르기를 정확히 말해요.","80 km/h예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#21','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C22',3,'mc','auto','친구가 자동계단에서 빨리 가려고 뛰어 올라가려고 해요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X34','SC6-1-u2-X37','SC6-1-u2-X35']::text[],false,'{"seq":21,"concept":"SC6-1-u2-C22","difficulty":3,"kind":"mc","stem":"친구가 자동계단에서 빨리 가려고 뛰어 올라가려고 해요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"손잡이를 잡고 서서 함께 올라가자고 말한다","correct":true},{"t":"나도 따라 뛰어 올라간다","mis":"SC6-1-u2-X34"},{"t":"자동계단에는 안전장치가 있으니 괜찮다고 말한다","mis":"SC6-1-u2-X37"},{"t":"안전은 어른들 몫이니 그냥 둔다","mis":"SC6-1-u2-X35"}],"explanation":["자동계단 수칙이에요.","뛰지 않아요.","손잡이를 잡고 서요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#22','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C27',3,'mc','auto','스포츠 첨단 기술에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X43','SC6-1-u2-X42']::text[],false,'{"seq":22,"concept":"SC6-1-u2-C27","difficulty":3,"kind":"mc","stem":"스포츠 첨단 기술에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"사람의 눈으로 가리기 어려운 도착 순서를 초고속 카메라로 확인해 공정한 판정을 돕는다","correct":true},{"t":"첨단 기술이 있으니 심판과 선수의 연습은 필요 없다","mis":"SC6-1-u2-X43"},{"t":"움직임 센서가 결승선에서 1초에 수천 장을 찍는다","mis":"SC6-1-u2-X42"},{"t":"3D 선수 추적 기술은 선수의 등에 붙인다","mis":"SC6-1-u2-X42"}],"explanation":["기술마다 하는 일이 달라요.","공정한 판정을 도와요.","초고속 카메라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#23','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C10',4,'mc','auto','푸름반 일지 ③과, 일지 ④의 결과(바다가 50 m를 가장 짧은 9.0초에 달림)를 함께 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X17','SC6-1-u2-X22','SC6-1-u2-X24']::text[],false,'{"seq":23,"concept":"SC6-1-u2-C10","difficulty":4,"kind":"mc","stem":"푸름반 일지 ③과, 일지 ④의 결과(바다가 50 m를 가장 짧은 9.0초에 달림)를 함께 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바다는 같은 시간 동안 가장 멀리 갔고 같은 거리를 가장 짧은 시간에 갔으니 두 방법 모두 바다가 가장 빠르다","correct":true},{"t":"일지 ③에서는 가장 짧게 달린 솔이 가장 빠르다","mis":"SC6-1-u2-X17"},{"t":"일지 ④에서는 가장 오래 걸린 솔이 가장 빠르다","mis":"SC6-1-u2-X22"},{"t":"두 일지는 비교 방법이 달라 아무것도 알 수 없다","mis":"SC6-1-u2-X24"}],"explanation":["③은 같은 시간이에요.","④는 같은 거리예요.","두 방법 모두 바다예요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#24','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C3',4,'essay','teacher','푸름반 일지 ①의 여섯 가지를 운동한 것과 운동하지 않은 것으로 나누고 근거를 쓰세요. 그리고 지우와 학교 버스를 예로 들어 과학에서 말하는 운동의 뜻을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u2-C3","difficulty":4,"kind":"essay","stem":"푸름반 일지 ①의 여섯 가지를 운동한 것과 운동하지 않은 것으로 나누고 근거를 쓰세요. 그리고 지우와 학교 버스를 예로 들어 과학에서 말하는 운동의 뜻을 설명하세요.","answer_guide":{"answer":"예: 운동한 것은 서진, 비둘기, 공이고, 운동하지 않은 것은 국기 게양대, 지우, 학교 버스이다. 서진은 정문 앞에서 화단 옆으로, 비둘기는 지붕 위에서 나무 위로, 공은 골대 앞에서 골대 안으로 10초 동안 위치가 변했기 때문이다. 지우는 철봉에 매달려 몸에 힘을 주고 있지만 위치가 그대로이므로 과학에서는 운동하지 않은 것이다. 학교 버스도 지금은 서 있어 운동하지 않지만 출발하면 운동하는 물체가 된다. 과학에서 운동은 시간이 지남에 따라 물체의 위치가 변하는 것이다.","scoring_points":["여섯 가지를 바르게 나누었는가","위치 변화로 근거를 썼는가","지우·학교 버스로 운동의 뜻을 설명했는가"]},"explanation":["위치 변화를 견줘요.","둘로 나눠요.","운동의 뜻을 설명해요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_a#25','sci',6,1,'u2','','g6_1_sci_u2_review_a','unit_review','SC6-1-u2-C17',4,'essay','teacher','푸름반 일지 ⑤의 버스, 기차, 자전거 동아리의 속력을 각각 구하는 과정과 함께 쓰고, 빠른 순서대로 늘어놓으세요. 속력을 쓸 때 주의할 점도 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u2-C17","difficulty":4,"kind":"essay","stem":"푸름반 일지 ⑤의 버스, 기차, 자전거 동아리의 속력을 각각 구하는 과정과 함께 쓰고, 빠른 순서대로 늘어놓으세요. 속력을 쓸 때 주의할 점도 한 가지 쓰세요.","answer_guide":{"answer":"예: 속력은 이동 거리를 걸린 시간으로 나누어 구한다. 버스는 160 km ÷ 2 h = 80 km/h, 기차는 330 km ÷ 3 h = 110 km/h, 자전거 동아리는 30 km ÷ 2 h = 15 km/h이다. 단위가 모두 km/h로 같으므로 숫자가 큰 순서대로 기차, 버스, 자전거 동아리 순으로 빠르다. 속력을 쓸 때는 숫자와 단위를 함께 써야 한다.","scoring_points":["세 속력을 과정과 함께 바르게 구했는가","빠른 순서를 바르게 썼는가","단위를 함께 쓰는 등 주의할 점을 썼는가"]},"explanation":["나눗셈 식을 세워요.","단위를 확인해요.","순서를 정해요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#1','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C3',1,'ox','auto','푸름반 일지 ①의 비둘기는 운동한 물체예요.',ARRAY['SC6-1-u2-X07']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C3","difficulty":1,"kind":"ox","stem":"푸름반 일지 ①의 비둘기는 운동한 물체예요.","answer":"O","reason_options":[{"t":"10초 동안 지붕 위에서 나무 위로 위치가 변했기 때문에","correct":true},{"t":"비둘기는 동물이라 물체가 아니기 때문에","mis":"SC6-1-u2-X07"}],"mis":"SC6-1-u2-X07","explanation":["처음과 10초 뒤를 견줘요.","자리가 바뀌었어요.","운동한 물체예요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#2','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C7',1,'ox','auto','「서진은 10초 동안 정문 앞에서 화단 옆으로 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.',ARRAY['SC6-1-u2-X12']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"ox","stem":"「서진은 10초 동안 정문 앞에서 화단 옆으로 이동했다.」는 물체의 운동을 알맞게 표현한 거예요.","answer":"O","reason_options":[{"t":"걸린 시간, 처음 위치, 나중 위치가 모두 들어 있기 때문에","correct":true},{"t":"걸린 시간만 있으면 되므로 위치는 넣지 않아도 되기 때문에","mis":"SC6-1-u2-X12"}],"mis":"SC6-1-u2-X12","explanation":["세 가지를 찾아요.","10초, 정문 앞, 화단 옆이에요.","알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#3','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C10',1,'ox','auto','같은 시간 동안 이동한 물체는 이동 거리가 짧을수록 더 빨라요.',ARRAY['SC6-1-u2-X17']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"ox","stem":"같은 시간 동안 이동한 물체는 이동 거리가 짧을수록 더 빨라요.","answer":"X","reason_options":[{"t":"같은 시간 동안 긴 거리를 이동한 물체가 더 빠르기 때문에","correct":true},{"t":"짧게 갈수록 힘을 덜 써서 더 빠르기 때문에","mis":"SC6-1-u2-X17"}],"mis":"SC6-1-u2-X17","explanation":["같은 시간이에요.","길게 간 쪽이 빨라요.","짧을수록이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#4','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C14',1,'ox','auto','같은 거리를 이동했다면 걸린 시간이 짧을수록 더 빨라요.',ARRAY['SC6-1-u2-X22']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"ox","stem":"같은 거리를 이동했다면 걸린 시간이 짧을수록 더 빨라요.","answer":"O","reason_options":[{"t":"같은 거리를 더 짧은 시간에 이동한 물체가 더 빠르기 때문에","correct":true},{"t":"오래 걸릴수록 더 힘차게 움직였기 때문에","mis":"SC6-1-u2-X22"}],"mis":"SC6-1-u2-X22","explanation":["같은 거리예요.","빨리 닿을수록 빨라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#5','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C18',1,'ox','auto','80 km/h는 「팔십 킬로미터 매 시」라고 읽어요.',ARRAY['SC6-1-u2-X28']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C18","difficulty":1,"kind":"ox","stem":"80 km/h는 「팔십 킬로미터 매 시」라고 읽어요.","answer":"O","reason_options":[{"t":"km/h는 킬로미터 매 시로 읽기 때문에","correct":true},{"t":"km/h는 킬로미터 매 초로 읽기 때문에","mis":"SC6-1-u2-X28"}],"mis":"SC6-1-u2-X28","explanation":["h는 시간이에요.","매 시로 읽어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#6','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C21',1,'ox','auto','속력이 빠른 자동차도 브레이크를 밟으면 그 자리에서 바로 멈춰요.',ARRAY['SC6-1-u2-X33']::text[],false,'{"seq":6,"concept":"SC6-1-u2-C21","difficulty":1,"kind":"ox","stem":"속력이 빠른 자동차도 브레이크를 밟으면 그 자리에서 바로 멈춰요.","answer":"X","reason_options":[{"t":"브레이크를 밟은 뒤에도 멈출 때까지 더 움직이고, 빠를수록 그 거리가 길기 때문에","correct":true},{"t":"속력이 빠를수록 더 빨리 멈추기 때문에","mis":"SC6-1-u2-X33"}],"mis":"SC6-1-u2-X33","explanation":["제동 거리를 떠올려요.","바로 멈추지 않아요.","빠를수록 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#7','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C25',1,'ox','auto','푸름반 일지 ⑧의 서아가 실천하지 못한 날을 표시하지 않고 그대로 둔 것은 알맞은 태도예요.',ARRAY['SC6-1-u2-X39']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"ox","stem":"푸름반 일지 ⑧의 서아가 실천하지 못한 날을 표시하지 않고 그대로 둔 것은 알맞은 태도예요.","answer":"O","reason_options":[{"t":"점검표는 실천한 날만 양심적으로 표시하는 것이기 때문에","correct":true},{"t":"칸을 모두 채워야 좋은 점검표이기 때문에","mis":"SC6-1-u2-X39"}],"mis":"SC6-1-u2-X39","explanation":["점검표의 목적이에요.","정직하게 표시해요.","알맞아요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#8','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C1',1,'ox','auto','나무토막 옮기기에서 나무토막을 떨어뜨리면 출발선으로 돌아와 다시 시작해요.',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"ox","stem":"나무토막 옮기기에서 나무토막을 떨어뜨리면 출발선으로 돌아와 다시 시작해요.","answer":"O","reason_options":[{"t":"놀이 규칙이 처음부터 다시 하는 것이기 때문에","correct":true},{"t":"떨어진 자리에서 이어 가도 되기 때문에","mis":"SC6-1-u2-X01"}],"mis":"SC6-1-u2-X01","explanation":["규칙을 떠올려요.","처음부터 다시예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#9','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C5',2,'error','auto','푸름반 일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X08']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"error","stem":"푸름반 일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예서 — 「국기 게양대는 10초 동안 위치가 바뀌었어.」","correct":true,"mis_target":"SC6-1-u2-X08"},{"t":"로하 — 「서진은 정문 앞에서 화단 옆으로 옮겨 갔어.」","mis":"SC6-1-u2-X08"},{"t":"채아 — 「공은 골대 앞에서 골대 안으로 들어갔어.」","mis":"SC6-1-u2-X08"}],"explanation":["국기 게양대를 봐요.","운동장 끝 그대로예요.","예서가 잘못 말했어요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#10','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C7',2,'mc','auto','로봇이 10초 동안 정문에서 화단까지 이동했어요. 로봇의 운동을 알맞게 표현한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X13','SC6-1-u2-X12']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C7","difficulty":2,"kind":"mc","stem":"로봇이 10초 동안 정문에서 화단까지 이동했어요. 로봇의 운동을 알맞게 표현한 것은 어느 것인가요?","options":[{"t":"로봇은 10초 동안 정문에서 화단으로 이동했다","correct":true},{"t":"로봇은 10초 동안 화단에서 정문으로 이동했다","mis":"SC6-1-u2-X13"},{"t":"로봇은 정문에서 화단으로 이동했다","mis":"SC6-1-u2-X12"},{"t":"로봇은 10초 동안 이동했다","mis":"SC6-1-u2-X12"}],"explanation":["세 가지를 넣어요.","정문에서 출발했어요.","모두 들어간 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#11','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C10',2,'sa','auto','푸름반 일지 ③에서 바다는 솔보다 몇 m 더 달렸나요?','{}'::text[],false,'{"seq":11,"concept":"SC6-1-u2-C10","difficulty":2,"kind":"sa","stem":"푸름반 일지 ③에서 바다는 솔보다 몇 m 더 달렸나요?","answer":["7","7 m","7m"],"explanation":["두 거리를 견줘요.","55에서 48을 빼요.","7 m예요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"},"mis":"SC6-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#12','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C14',2,'sa','auto','푸름반 일지 ④에서 하늘은 바다보다 몇 초 더 걸렸나요?','{}'::text[],false,'{"seq":12,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"sa","stem":"푸름반 일지 ④에서 하늘은 바다보다 몇 초 더 걸렸나요?","answer":["0.4","0.4초"],"explanation":["두 시간을 견줘요.","9.4에서 9.0을 빼요.","0.4초예요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"},"mis":"SC6-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#13','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C17',2,'sa','auto','푸름반 일지 ⑤에서 기차의 속력은 몇 km/h인가요?','{}'::text[],false,'{"seq":13,"concept":"SC6-1-u2-C17","difficulty":2,"kind":"sa","stem":"푸름반 일지 ⑤에서 기차의 속력은 몇 km/h인가요?","answer":["110","110 km/h","110km/h"],"explanation":["330 km를 3시간에 갔어요.","330 ÷ 3이에요.","110 km/h예요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"},"mis":"SC6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#14','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C23',2,'error','auto','푸름반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X36']::text[],false,'{"seq":14,"concept":"SC6-1-u2-C23","difficulty":2,"kind":"error","stem":"푸름반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정민 — 「인도와 차도 사이의 안전 울타리는 자동차의 속력을 숫자로 보여 줘.」","correct":true,"mis_target":"SC6-1-u2-X36"},{"t":"보라 — 「안전 울타리는 충돌할 때 충격을 흡수하고 보행자를 보호해.」","mis":"SC6-1-u2-X36"},{"t":"태호 — 「과속 방지턱은 운전자가 속력을 줄이게 해.」","mis":"SC6-1-u2-X36"}],"explanation":["숫자를 보여 주는 것은 무엇인가요?","전광판이에요.","정민이 잘못 말했어요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#15','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C26',2,'error','auto','서아의 발표를 듣고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X41']::text[],false,'{"seq":15,"concept":"SC6-1-u2-C26","difficulty":2,"kind":"error","stem":"서아의 발표를 듣고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태린 — 「②를 네 번밖에 못 했으니 서아는 잘못한 거야.」","correct":true,"mis_target":"SC6-1-u2-X41"},{"t":"규아 — 「스마트 기기를 보지 않으려고 노력한 점이 좋아.」","mis":"SC6-1-u2-X41"},{"t":"하온 — 「서아가 깨달은 점을 들으니 나도 돌아보게 돼.」","mis":"SC6-1-u2-X41"}],"explanation":["듣는 태도를 봐요.","노력한 점을 칭찬해요.","태린이 알맞지 않아요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#16','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C13',2,'match','auto','1초 동안 이동할 수 있는 거리 자료를 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC6-1-u2-C13","difficulty":2,"kind":"match","stem":"1초 동안 이동할 수 있는 거리 자료를 알맞게 이으세요.","pairs":[{"l":"루지","r":"약 39 m"},{"l":"거북","r":"약 0.3 m"},{"l":"송골매","r":"약 108 m"}],"mis":"SC6-1-u2-X21","explanation":["자료를 읽어요.","거북이 가장 짧아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["거북 — 약 0.3 m","사람 — 약 10 m","루지 — 약 39 m","송골매 — 약 108 m","드론 — 약 133 m","※ 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값이다."],"title":"1초 동안 이동할 수 있는 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#17','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C11',3,'mc','auto','푸름반 일지 ③에서 솔이 출발 신호보다 2초 늦게 출발했다는 것을 알았어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['SC6-1-u2-X18','SC6-1-u2-X19']::text[],false,'{"seq":17,"concept":"SC6-1-u2-C11","difficulty":3,"kind":"mc","stem":"푸름반 일지 ③에서 솔이 출발 신호보다 2초 늦게 출발했다는 것을 알았어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"같은 시간이라는 조건이 깨졌으니 다시 동시에 출발해 재야 한다","correct":true},{"t":"그래도 솔이 가장 느리다고 정한다","mis":"SC6-1-u2-X18"},{"t":"지금 맨 앞에 있었던 친구가 가장 빠르다고 정한다","mis":"SC6-1-u2-X19"},{"t":"솔이 늦은 만큼 거리를 어림해 더해 준다","mis":"SC6-1-u2-X18"}],"explanation":["같아야 하는 것을 떠올려요.","동시에 출발해야 해요.","다시 재요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#18','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C23',3,'error','auto','푸름반 일지 ⑥의 도하의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X37','SC6-1-u2-X36','SC6-1-u2-X34']::text[],false,'{"seq":18,"concept":"SC6-1-u2-C23","difficulty":3,"kind":"error","stem":"푸름반 일지 ⑥의 도하의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「안전띠를 맸으니 학교 앞에서도 빨리 달려도 돼.」","correct":true,"mis_target":"SC6-1-u2-X37"},{"t":"윤아 — 「안전띠는 탑승자를 좌석에 고정해 줘.」","mis":"SC6-1-u2-X36"},{"t":"건희 — 「학교 앞에서는 정해진 속력보다 천천히 달려야 해.」","mis":"SC6-1-u2-X34"}],"explanation":["장치와 수칙을 견줘요.","둘 다 지켜야 해요.","도하가 잘못 말했어요."],"asset":{"type":"passage","lines":["민재 — 「같은 시간 동안 짧게 간 자동차가 더 빨라.」","예린 — 「10 km/h가 5 m/s보다 빨라. 10이 더 크잖아.」","도하 — 「안전띠를 맸으니 학교 앞에서도 빨리 달려도 돼.」","선생님 — 세 친구의 말을 배운 내용으로 하나씩 따져 보자."],"title":"푸름반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#19','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C14',3,'ox','auto','푸름반 일지 ④의 세 친구는 같은 50 m를 달렸으니 걸린 시간만으로 빠르기를 견줄 수 있어요.',ARRAY['SC6-1-u2-X24']::text[],false,'{"seq":19,"concept":"SC6-1-u2-C14","difficulty":3,"kind":"ox","stem":"푸름반 일지 ④의 세 친구는 같은 50 m를 달렸으니 걸린 시간만으로 빠르기를 견줄 수 있어요.","answer":"O","reason_options":[{"t":"이동한 거리가 같을 때는 걸린 시간이 짧을수록 빠르기 때문에","correct":true},{"t":"거리가 같아도 지금 앞서 있는 사람을 봐야 하기 때문에","mis":"SC6-1-u2-X24"}],"mis":"SC6-1-u2-X24","explanation":["거리가 같아요.","시간으로 견줄 수 있어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#20','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C13',3,'mc','auto','1초 동안 이동할 수 있는 거리 자료를 바르게 읽은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X21','SC6-1-u2-X17']::text[],false,'{"seq":20,"concept":"SC6-1-u2-C13","difficulty":3,"kind":"mc","stem":"1초 동안 이동할 수 있는 거리 자료를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"송골매는 1초 동안 사람보다 훨씬 긴 거리를 이동한 기록이 있다","correct":true},{"t":"송골매는 언제나 1초에 108 m를 난다","mis":"SC6-1-u2-X21"},{"t":"거북이 드론보다 빠르다","mis":"SC6-1-u2-X17"},{"t":"사람은 누구나 1초에 10 m를 달린다","mis":"SC6-1-u2-X21"}],"explanation":["자료 끝의 설명을 봐요.","기록을 바탕으로 했어요.","송골매가 사람보다 길어요."],"asset":{"type":"passage","lines":["거북 — 약 0.3 m","사람 — 약 10 m","루지 — 약 39 m","송골매 — 약 108 m","드론 — 약 133 m","※ 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값이다."],"title":"1초 동안 이동할 수 있는 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#21','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C24',3,'mc','auto','누리망에서 찾은 안전 수칙 자료 두 개의 내용이 서로 달라요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X38']::text[],false,'{"seq":21,"concept":"SC6-1-u2-C24","difficulty":3,"kind":"mc","stem":"누리망에서 찾은 안전 수칙 자료 두 개의 내용이 서로 달라요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"믿을 만한 곳에서 낸 자료인지 확인하고 출처를 밝혀 쓴다","correct":true},{"t":"더 눈길을 끄는 자료를 골라 출처 없이 쓴다","mis":"SC6-1-u2-X38"},{"t":"두 자료를 출처 없이 섞어 쓴다","mis":"SC6-1-u2-X38"},{"t":"아무 자료나 골라 친구 이름과 함께 올린다","mis":"SC6-1-u2-X38"}],"explanation":["자료를 따져 봐요.","믿을 만한지 확인해요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#22','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C4',3,'mc','auto','과학에서 말하는 운동을 한 경우는 어느 것인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X11']::text[],false,'{"seq":22,"concept":"SC6-1-u2-C4","difficulty":3,"kind":"mc","stem":"과학에서 말하는 운동을 한 경우는 어느 것인가요?","options":[{"t":"계단을 걸어 2층에서 3층으로 올라간 친구","correct":true},{"t":"철봉에 가만히 매달린 친구","mis":"SC6-1-u2-X06"},{"t":"물 절약 운동에 참여한 반","mis":"SC6-1-u2-X06"},{"t":"자리에 앉아 책장을 넘기는 친구","mis":"SC6-1-u2-X11"}],"explanation":["위치가 변한 것을 찾아요.","2층에서 3층으로 갔어요.","계단을 오른 친구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#23','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C19',4,'mc','auto','푸름반 일지 ⑤의 세 가지를 속력으로 비교할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X31','SC6-1-u2-X29']::text[],false,'{"seq":23,"concept":"SC6-1-u2-C19","difficulty":4,"kind":"mc","stem":"푸름반 일지 ⑤의 세 가지를 속력으로 비교할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"거리도 시간도 다르지만 속력을 구하면 단위가 모두 km/h로 같아 숫자로 견줄 수 있다","correct":true},{"t":"거리가 가장 긴 기차가 가장 빠르다고 바로 알 수 있어서","mis":"SC6-1-u2-X31"},{"t":"시간이 가장 짧은 쪽이 언제나 가장 빨라서","mis":"SC6-1-u2-X31"},{"t":"속력의 숫자는 단위와 관계없이 견줄 수 있어서","mis":"SC6-1-u2-X29"}],"explanation":["거리와 시간이 모두 달라요.","속력을 구해요.","단위가 같아야 숫자로 견줘요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#24','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C9',4,'essay','teacher','푸름반 운동장 판의 로봇(한 칸에 2초)을 매점에서 출발시켜 화단까지 가장 짧게 이동시키려고 해요. 이동할 방향과 칸 수, 걸린 시간을 쓰고, 로봇의 운동을 걸린 시간·처음 위치·나중 위치가 모두 들어가게 한 문장으로 표현하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u2-C9","difficulty":4,"kind":"essay","stem":"푸름반 운동장 판의 로봇(한 칸에 2초)을 매점에서 출발시켜 화단까지 가장 짧게 이동시키려고 해요. 이동할 방향과 칸 수, 걸린 시간을 쓰고, 로봇의 운동을 걸린 시간·처음 위치·나중 위치가 모두 들어가게 한 문장으로 표현하세요.","answer_guide":{"answer":"예: 매점에서 오른쪽으로 2칸, 위쪽으로 4칸 이동하면 화단에 닿는다. 모두 6칸이고 한 칸에 2초가 걸리므로 걸린 시간은 12초이다. 로봇은 12초 동안 매점에서 화단으로 이동했다.","scoring_points":["방향과 칸 수를 바르게 썼는가","걸린 시간을 바르게 구했는가","세 가지가 모두 들어간 문장으로 표현했는가"]},"explanation":["매점 자리를 찾아요.","칸을 세어 시간을 구해요.","한 문장으로 표현해요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_b#25','sci',6,1,'u2','','g6_1_sci_u2_review_b','unit_review','SC6-1-u2-C19',4,'essay','teacher','푸름반 일지 ⑥의 민재와 예린의 말이 각각 왜 옳지 않은지 배운 내용을 근거로 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u2-C19","difficulty":4,"kind":"essay","stem":"푸름반 일지 ⑥의 민재와 예린의 말이 각각 왜 옳지 않은지 배운 내용을 근거로 바로잡아 쓰세요.","answer_guide":{"answer":"예: 민재야, 같은 시간 동안 이동했다면 이동 거리가 긴 자동차가 더 빨라. 짧게 간 자동차는 더 느린 거야. 예린아, 10 km/h와 5 m/s는 단위가 달라서 숫자만 보고 10이 크다고 더 빠르다고 할 수 없어. 속력은 단위가 같을 때에만 숫자가 클수록 더 빨라.","scoring_points":["민재의 말을 같은 시간·긴 거리로 바로잡았는가","예린의 말을 단위로 바로잡았는가","근거를 들어 친구에게 설명했는가"]},"explanation":["민재부터 따져요.","예린은 단위를 봐요.","근거를 들어 써요."],"asset":{"type":"passage","lines":["민재 — 「같은 시간 동안 짧게 간 자동차가 더 빨라.」","예린 — 「10 km/h가 5 m/s보다 빨라. 10이 더 크잖아.」","도하 — 「안전띠를 맸으니 학교 앞에서도 빨리 달려도 돼.」","선생님 — 세 친구의 말을 배운 내용으로 하나씩 따져 보자."],"title":"푸름반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#1','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C7',1,'sa','auto','푸름반 일지 ①에서 공의 나중 위치를 쓰세요. (□□ □)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u2-C7","difficulty":1,"kind":"sa","stem":"푸름반 일지 ①에서 공의 나중 위치를 쓰세요. (□□ □)","answer":["골대 안","골대안"],"explanation":["10초 뒤를 봐요.","공이 들어갔어요.","골대 안이에요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"},"mis":"SC6-1-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#2','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C8',1,'sa','auto','푸름반 운동장 판에서 그네는 국기대에서 왼쪽으로 몇 칸 떨어져 있나요?','{}'::text[],false,'{"seq":2,"concept":"SC6-1-u2-C8","difficulty":1,"kind":"sa","stem":"푸름반 운동장 판에서 그네는 국기대에서 왼쪽으로 몇 칸 떨어져 있나요?","answer":["2","2칸"],"explanation":["국기대에서 출발해요.","왼쪽으로 세어요.","2칸이에요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false},"mis":"SC6-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#3','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C10',1,'sa','auto','푸름반 일지 ③에서 가장 짧은 거리를 달린 친구는 누구인가요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C10","difficulty":1,"kind":"sa","stem":"푸름반 일지 ③에서 가장 짧은 거리를 달린 친구는 누구인가요?","answer":["솔"],"explanation":["세 거리를 견줘요.","48 m가 가장 짧아요.","솔이에요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"},"mis":"SC6-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#4','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C14',1,'sa','auto','푸름반 일지 ④에서 가장 오래 걸린 친구는 누구인가요?','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"sa","stem":"푸름반 일지 ④에서 가장 오래 걸린 친구는 누구인가요?","answer":["솔"],"explanation":["세 시간을 견줘요.","10.1초가 가장 길어요.","솔이에요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"},"mis":"SC6-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#5','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C17',1,'sa','auto','푸름반 일지 ⑤에서 버스의 속력은 몇 km/h인가요?','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u2-C17","difficulty":1,"kind":"sa","stem":"푸름반 일지 ⑤에서 버스의 속력은 몇 km/h인가요?","answer":["80","80 km/h","80km/h"],"explanation":["160 km를 2시간에 갔어요.","160 ÷ 2예요.","80 km/h예요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"},"mis":"SC6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#6','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C23',1,'sa','auto','푸름반 일지 ⑦에서 지나가는 자동차의 속력을 재어 숫자로 알려 주는 안전장치의 이름을 쓰세요. (□□ □□ □□□)','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C23","difficulty":1,"kind":"sa","stem":"푸름반 일지 ⑦에서 지나가는 자동차의 속력을 재어 숫자로 알려 주는 안전장치의 이름을 쓰세요. (□□ □□ □□□)","answer":["과속 경보 시스템","과속경보시스템","과속 경보시스템"],"explanation":["전광판에 숫자가 나와요.","속력을 재어 알려 줘요.","과속 경보 시스템이에요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"},"mis":"SC6-1-u2-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#7','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C25',1,'sa','auto','푸름반 일지 ⑧에서 서아가 ②를 표시한 날은 며칠인가요?','{}'::text[],false,'{"seq":7,"concept":"SC6-1-u2-C25","difficulty":1,"kind":"sa","stem":"푸름반 일지 ⑧에서 서아가 ②를 표시한 날은 며칠인가요?","answer":["4","4일"],"explanation":["표시한 날을 봐요.","② 칸이에요.","4일이에요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"},"mis":"SC6-1-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#8','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C2',1,'sa','auto','나무토막 옮기기에서 결승선을 가장 먼저 통과한 친구는 가장 빠르게 걸은 친구인가요, 가장 느리게 걸은 친구인가요? (빠르게 · 느리게 중에서 쓰세요)','{}'::text[],false,'{"seq":8,"concept":"SC6-1-u2-C2","difficulty":1,"kind":"sa","stem":"나무토막 옮기기에서 결승선을 가장 먼저 통과한 친구는 가장 빠르게 걸은 친구인가요, 가장 느리게 걸은 친구인가요? (빠르게 · 느리게 중에서 쓰세요)","answer":["빠르게","가장 빠르게"],"explanation":["같은 곳까지 걸었어요.","먼저 닿았어요.","빠르게예요."],"mis":"SC6-1-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#9','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C4',2,'match','auto','푸름반 일지 ①의 대상과 판단을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC6-1-u2-C4","difficulty":2,"kind":"match","stem":"푸름반 일지 ①의 대상과 판단을 알맞게 이으세요.","pairs":[{"l":"비둘기","r":"위치가 변해 운동했다"},{"l":"국기 게양대","r":"위치가 그대로라 운동하지 않았다"},{"l":"지우","r":"매달려 있지만 위치가 그대로라 과학에서의 운동이 아니다"}],"mis":"SC6-1-u2-X06","explanation":["하나씩 견줘요.","위치가 변했는지 봐요.","지우는 그대로예요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#10','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C8',2,'sa','auto','푸름반 운동장 판에서 화단은 국기대에서 오른쪽으로 1칸, 위쪽으로 몇 칸 떨어져 있나요?','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u2-C8","difficulty":2,"kind":"sa","stem":"푸름반 운동장 판에서 화단은 국기대에서 오른쪽으로 1칸, 위쪽으로 몇 칸 떨어져 있나요?","answer":["3","3칸"],"explanation":["국기대에서 출발해요.","오른쪽 1칸 뒤 위쪽으로 세어요.","3칸이에요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false},"mis":"SC6-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#11','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C12',2,'error','auto','푸름반 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X19','SC6-1-u2-X17']::text[],false,'{"seq":11,"concept":"SC6-1-u2-C12","difficulty":2,"kind":"error","stem":"푸름반 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「솔이 5 m 앞에서 출발했어도 지금 맨 앞에 있으면 가장 빠른 거야.」","correct":true,"mis_target":"SC6-1-u2-X19"},{"t":"아린 — 「같은 출발선에서 동시에 출발했으니 거리로 견줄 수 있어.」","mis":"SC6-1-u2-X19"},{"t":"주아 — 「같은 10초 동안 가장 길게 간 친구가 가장 빨라.」","mis":"SC6-1-u2-X17"}],"explanation":["출발선이 다르면 어떨까요?","앞에 있다고 빠르지 않아요.","은우가 잘못 말했어요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#12','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C15',2,'error','auto','같은 거리 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X23']::text[],false,'{"seq":12,"concept":"SC6-1-u2-C15","difficulty":2,"kind":"error","stem":"같은 거리 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"선율 — 「자동차의 뒷부분을 출발선에 맞추자.」","correct":true,"mis_target":"SC6-1-u2-X23"},{"t":"유나 — 「줄자는 결승선을 표시할 때만 쓰자.」","mis":"SC6-1-u2-X23"},{"t":"찬이 — 「앞부분이 결승선에 닿은 시간을 재자.」","mis":"SC6-1-u2-X23"}],"explanation":["어느 부분을 맞추나요?","앞부분이에요.","선율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#13','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C18',2,'error','auto','속력의 단위를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X28']::text[],false,'{"seq":13,"concept":"SC6-1-u2-C18","difficulty":2,"kind":"error","stem":"속력의 단위를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「15 km/h는 1초 동안 15 km를 가는 빠르기야.」","correct":true,"mis_target":"SC6-1-u2-X28"},{"t":"도영 — 「110 km/h는 1시간 동안 110 km를 가는 빠르기야.」","mis":"SC6-1-u2-X28"},{"t":"세아 — 「km/h는 킬로미터 매 시라고 읽어.」","mis":"SC6-1-u2-X28"}],"explanation":["h의 뜻을 봐요.","1시간마다예요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#14','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C23',2,'match','auto','푸름반 일지 ⑦의 안전장치와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC6-1-u2-C23","difficulty":2,"kind":"match","stem":"푸름반 일지 ⑦의 안전장치와 하는 일을 알맞게 이으세요.","pairs":[{"l":"과속 방지턱","r":"운전자가 속력을 줄이도록 유도한다"},{"l":"속력이 나타나는 전광판","r":"자동차의 속력을 재어 알려 준다"},{"l":"안전 울타리","r":"충격을 흡수하고 보행자를 보호한다"}],"mis":"SC6-1-u2-X36","explanation":["장치를 하나씩 봐요.","모두 도로에 있어요.","하는 일을 이어요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#15','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C24',2,'mc','auto','학교 앞 도로 사진을 반 공유 플랫폼에 올릴 때 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X38']::text[],false,'{"seq":15,"concept":"SC6-1-u2-C24","difficulty":2,"kind":"mc","stem":"학교 앞 도로 사진을 반 공유 플랫폼에 올릴 때 알맞은 것은 어느 것인가요?","options":[{"t":"지나가는 사람의 얼굴이 나오지 않게 찍고 찍은 곳과 날짜를 밝힌다","correct":true},{"t":"지나가는 사람의 얼굴이 크게 나오게 찍어 올린다","mis":"SC6-1-u2-X38"},{"t":"다른 사람이 찍은 사진을 출처 없이 올린다","mis":"SC6-1-u2-X38"},{"t":"다른 모둠 사진에 거친 말로 댓글을 단다","mis":"SC6-1-u2-X38"}],"explanation":["개인 정보를 지켜요.","밝힐 것은 밝혀요.","얼굴은 나오지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#16','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C2',2,'error','auto','걷기 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X03','SC6-1-u2-X04']::text[],false,'{"seq":16,"concept":"SC6-1-u2-C2","difficulty":2,"kind":"error","stem":"걷기 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「모든 사람은 똑같은 빠르기로 걸어.」","correct":true,"mis_target":"SC6-1-u2-X03"},{"t":"미소 — 「사람마다 걷는 빠르기가 달라.」","mis":"SC6-1-u2-X03"},{"t":"준혁 — 「먼저 통과한 친구가 더 빠르게 걸었어.」","mis":"SC6-1-u2-X04"}],"explanation":["걷기 결과를 떠올려요.","빠르기가 달랐어요.","라온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#17','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C19',3,'mc','auto','푸름반 일지 ⑥의 예린의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X29','SC6-1-u2-X31']::text[],false,'{"seq":17,"concept":"SC6-1-u2-C19","difficulty":3,"kind":"mc","stem":"푸름반 일지 ⑥의 예린의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 속력은 단위가 달라 숫자만으로 바로 비교할 수 없다","correct":true},{"t":"10이 5보다 크니 예린의 말이 맞다","mis":"SC6-1-u2-X29"},{"t":"m/s가 들어가면 언제나 더 빠르다","mis":"SC6-1-u2-X29"},{"t":"속력은 어떤 경우에도 비교할 수 없다","mis":"SC6-1-u2-X31"}],"explanation":["단위를 봐요.","km/h와 m/s예요.","단위가 같아야 해요."],"asset":{"type":"passage","lines":["민재 — 「같은 시간 동안 짧게 간 자동차가 더 빨라.」","예린 — 「10 km/h가 5 m/s보다 빨라. 10이 더 크잖아.」","도하 — 「안전띠를 맸으니 학교 앞에서도 빨리 달려도 돼.」","선생님 — 세 친구의 말을 배운 내용으로 하나씩 따져 보자."],"title":"푸름반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#18','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C17',3,'error','auto','호랑이가 100 m를 25초에 달렸어요. 속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X26']::text[],false,'{"seq":18,"concept":"SC6-1-u2-C17","difficulty":3,"kind":"error","stem":"호랑이가 100 m를 25초에 달렸어요. 속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「속력은 25를 100으로 나눠서 구해.」","correct":true,"mis_target":"SC6-1-u2-X26"},{"t":"나윤 — 「속력은 이동 거리를 걸린 시간으로 나눠.」","mis":"SC6-1-u2-X26"},{"t":"승우 — 「100 ÷ 25 = 4이니 4 m/s야.」","mis":"SC6-1-u2-X26"}],"explanation":["나누는 순서를 봐요.","거리 ÷ 시간이에요.","하람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#19','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C12',3,'ox','auto','먼저 출발한 오토바이가 지금 맨 앞에 있다면 그 오토바이가 가장 빠르다고 할 수 있어요.',ARRAY['SC6-1-u2-X19']::text[],false,'{"seq":19,"concept":"SC6-1-u2-C12","difficulty":3,"kind":"ox","stem":"먼저 출발한 오토바이가 지금 맨 앞에 있다면 그 오토바이가 가장 빠르다고 할 수 있어요.","answer":"X","reason_options":[{"t":"출발 시각이 달라 지금 위치만으로는 비교할 수 없기 때문에","correct":true},{"t":"맨 앞에 있으면 언제나 가장 빠르기 때문에","mis":"SC6-1-u2-X19"}],"mis":"SC6-1-u2-X19","explanation":["출발 시각이 달라요.","먼저 출발했어요.","그렇게 말할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#20','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C15',3,'mc','auto','같은 거리 실험에서 초시계에 4.23초가 나왔어요. 기록하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X23']::text[],false,'{"seq":20,"concept":"SC6-1-u2-C15","difficulty":3,"kind":"mc","stem":"같은 거리 실험에서 초시계에 4.23초가 나왔어요. 기록하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"4.2초","correct":true},{"t":"4.23초","mis":"SC6-1-u2-X23"},{"t":"4초","mis":"SC6-1-u2-X23"},{"t":"5초","mis":"SC6-1-u2-X23"}],"explanation":["소수 첫째 자리까지예요.","둘째 자리에서 반올림해요.","4.2초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#21','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C26',3,'mc','auto','푸름반 일지 ⑧의 서아 발표를 들은 친구의 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X41','SC6-1-u2-X39']::text[],false,'{"seq":21,"concept":"SC6-1-u2-C26","difficulty":3,"kind":"mc","stem":"푸름반 일지 ⑧의 서아 발표를 들은 친구의 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「스마트 기기를 보고 있었다는 걸 깨닫고 고치려는 점이 멋져. 나도 해 볼게.」","correct":true},{"t":"「③을 다 못 지켰으니 처음부터 다시 해.」","mis":"SC6-1-u2-X41"},{"t":"「표시가 적으니 네 점검표는 별로야.」","mis":"SC6-1-u2-X39"},{"t":"「내 차례가 언제야? 빨리 끝내.」","mis":"SC6-1-u2-X41"}],"explanation":["노력한 점을 찾아요.","칭찬하고 배워요.","첫 번째 말이 알맞아요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#22','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C3',3,'mc','auto','푸름반 일지 ①에서 운동한 것을 빠짐없이 모은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X08']::text[],false,'{"seq":22,"concept":"SC6-1-u2-C3","difficulty":3,"kind":"mc","stem":"푸름반 일지 ①에서 운동한 것을 빠짐없이 모은 것은 어느 것인가요?","options":[{"t":"서진, 비둘기, 공","correct":true},{"t":"지우, 서진, 공","mis":"SC6-1-u2-X06"},{"t":"국기 게양대, 학교 버스","mis":"SC6-1-u2-X08"},{"t":"서진, 비둘기","mis":"SC6-1-u2-X08"}],"explanation":["위치가 바뀐 것을 모두 찾아요.","셋이 바뀌었어요.","서진, 비둘기, 공이에요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#23','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C21',4,'mc','auto','푸름반 일지 ⑦의 지그재그 차선, 과속 방지턱, 속력 전광판이 함께 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X32','SC6-1-u2-X37']::text[],false,'{"seq":23,"concept":"SC6-1-u2-C21","difficulty":4,"kind":"mc","stem":"푸름반 일지 ⑦의 지그재그 차선, 과속 방지턱, 속력 전광판이 함께 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자동차의 속력을 줄이거나 알려 주어, 빨리 달릴 때 바로 멈추기 어려운 위험을 줄인다","correct":true},{"t":"자동차가 학교 앞을 더 빨리 지나가게 한다","mis":"SC6-1-u2-X32"},{"t":"이런 장치가 있으니 보행자는 수칙을 지키지 않아도 된다","mis":"SC6-1-u2-X37"},{"t":"도로를 꾸미는 장식일 뿐이다","mis":"SC6-1-u2-X32"}],"explanation":["세 가지의 공통점을 찾아요.","모두 속력과 관계있어요.","위험을 줄여요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#24','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C12',4,'essay','teacher','푸름반 일지 ③의 결과로 세 친구를 빠른 순서대로 쓰고 그 근거를 쓰세요. 그리고 이 비교가 바르게 되려면 반드시 지켜야 하는 조건 두 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u2-C12","difficulty":4,"kind":"essay","stem":"푸름반 일지 ③의 결과로 세 친구를 빠른 순서대로 쓰고 그 근거를 쓰세요. 그리고 이 비교가 바르게 되려면 반드시 지켜야 하는 조건 두 가지를 쓰세요.","answer_guide":{"answer":"예: 빠른 순서는 바다, 하늘, 솔이다. 세 친구는 같은 10초 동안 달렸고, 같은 시간 동안 긴 거리를 이동할수록 빠르므로 55 m를 달린 바다가 가장 빠르고 48 m를 달린 솔이 가장 느리다. 이 비교가 바르게 되려면 세 친구가 같은 출발선에서 출발해야 하고, 동시에 출발해야 한다. 출발선이 다르거나 늦게 출발하면 맨 앞에 있다고 가장 빠르다고 할 수 없다.","scoring_points":["빠른 순서를 바르게 썼는가","같은 시간·긴 거리로 근거를 썼는가","같은 출발선·동시 출발 두 조건을 썼는가"]},"explanation":["거리를 견줘요.","근거를 써요.","조건 두 가지를 써요."],"asset":{"type":"passage","lines":["체육 시간에 셋이 같은 출발선에서 동시에 출발해 10초 동안 달렸다.","하늘 — 52 m","바다 — 55 m","솔 — 48 m"],"title":"푸름반 일지 ③ 10초 동안 달린 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_c#25','sci',6,1,'u2','','g6_1_sci_u2_review_c','unit_review','SC6-1-u2-C23',4,'essay','teacher','푸름반 일지 ⑦의 안전장치 세 가지가 각각 하는 일을 쓰고, 일지 ⑥의 도하의 말이 왜 옳지 않은지 안전장치와 안전 수칙의 관계로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u2-C23","difficulty":4,"kind":"essay","stem":"푸름반 일지 ⑦의 안전장치 세 가지가 각각 하는 일을 쓰고, 일지 ⑥의 도하의 말이 왜 옳지 않은지 안전장치와 안전 수칙의 관계로 설명하세요.","answer_guide":{"answer":"예: 과속 방지턱은 운전자가 속력을 줄이도록 유도하고, 속력 전광판(과속 경보 시스템)은 자동차의 속력을 재어 알려 주며, 안전 울타리는 충돌할 때 충격을 흡수하고 보행자를 보호한다. 도하의 말처럼 안전띠를 맸다고 빨리 달려도 되는 것은 아니다. 속력이 빠르면 바로 멈추기 어려워 사고 위험이 커지므로, 안전장치가 있어도 학교 앞에서는 정해진 속력보다 천천히 달리는 수칙을 함께 지켜야 한다.","scoring_points":["세 장치가 하는 일을 썼는가","도하의 말이 옳지 않음을 썼는가","장치와 수칙을 함께 지켜야 하는 까닭을 썼는가"]},"explanation":["장치를 하나씩 써요.","도하의 말을 따져요.","장치와 수칙을 이어요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#1','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C4',1,'mc','auto','푸름반 일지 ①의 지우를 옳게 판단한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X06','SC6-1-u2-X09','SC6-1-u2-X07']::text[],false,'{"seq":1,"concept":"SC6-1-u2-C4","difficulty":1,"kind":"mc","stem":"푸름반 일지 ①의 지우를 옳게 판단한 것은 어느 것인가요?","options":[{"t":"운동하지 않았다 — 위치가 그대로이기 때문","correct":true},{"t":"운동했다 — 몸에 힘을 주고 있기 때문","mis":"SC6-1-u2-X06"},{"t":"운동했다 — 사람은 언제나 운동하기 때문","mis":"SC6-1-u2-X09"},{"t":"판단할 수 없다 — 사람은 물체가 아니기 때문","mis":"SC6-1-u2-X07"}],"explanation":["위치를 봐요.","그대로 매달려 있어요.","운동하지 않았어요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#2','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C8',1,'mc','auto','푸름반 운동장 판에서 국기대로부터 오른쪽으로 3칸 떨어진 곳은 어디인가요?',ARRAY['SC6-1-u2-X14']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C8","difficulty":1,"kind":"mc","stem":"푸름반 운동장 판에서 국기대로부터 오른쪽으로 3칸 떨어진 곳은 어디인가요?","options":[{"t":"정문","correct":true},{"t":"화단","mis":"SC6-1-u2-X14"},{"t":"그네","mis":"SC6-1-u2-X14"},{"t":"매점","mis":"SC6-1-u2-X14"}],"explanation":["국기대에서 출발해요.","오른쪽으로 3칸이에요.","정문이에요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#3','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C11',1,'blank','auto','「같은 시간 동안의 빠르기를 비교하려면 같은 출발선에서 (    ) 출발해야 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u2-X18','SC6-1-u2-X19']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C11","difficulty":1,"kind":"blank","stem":"「같은 시간 동안의 빠르기를 비교하려면 같은 출발선에서 (    ) 출발해야 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"동시에","correct":true},{"t":"따로따로","mis":"SC6-1-u2-X18"},{"t":"먼저","mis":"SC6-1-u2-X19"},{"t":"늦게","mis":"SC6-1-u2-X18"}],"explanation":["출발 시각을 떠올려요.","같은 시간이어야 해요.","동시에예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#4','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C16',1,'mc','auto','같은 거리를 이동하는 데 걸린 시간으로 순위를 정하는 경기는 어느 것인가요?',ARRAY['SC6-1-u2-X25']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C16","difficulty":1,"kind":"mc","stem":"같은 거리를 이동하는 데 걸린 시간으로 순위를 정하는 경기는 어느 것인가요?","options":[{"t":"쇼트트랙","correct":true},{"t":"줄넘기를 넘은 횟수를 세는 경기","mis":"SC6-1-u2-X25"},{"t":"공을 넣은 개수를 세는 경기","mis":"SC6-1-u2-X25"},{"t":"들어 올린 무게를 재는 경기","mis":"SC6-1-u2-X25"}],"explanation":["시간을 재는 경기예요.","얼음 트랙을 돌아요.","쇼트트랙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#5','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C19',1,'mc','auto','푸름반 일지 ⑤에서 속력이 가장 빠른 것은 어느 것인가요?',ARRAY['SC6-1-u2-X31','SC6-1-u2-X26']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C19","difficulty":1,"kind":"mc","stem":"푸름반 일지 ⑤에서 속력이 가장 빠른 것은 어느 것인가요?","options":[{"t":"기차","correct":true},{"t":"버스","mis":"SC6-1-u2-X31"},{"t":"자전거 동아리","mis":"SC6-1-u2-X31"},{"t":"셋 모두 같다","mis":"SC6-1-u2-X26"}],"explanation":["속력을 각각 구해요.","80, 110, 15 km/h예요.","기차예요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#6','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C22',1,'mc','auto','횡단보도를 건널 때 지켜야 할 안전 수칙은 어느 것인가요?',ARRAY['SC6-1-u2-X34']::text[],false,'{"seq":6,"concept":"SC6-1-u2-C22","difficulty":1,"kind":"mc","stem":"횡단보도를 건널 때 지켜야 할 안전 수칙은 어느 것인가요?","options":[{"t":"좌우를 살피며 천천히 건넌다","correct":true},{"t":"스마트 기기를 보면서 건넌다","mis":"SC6-1-u2-X34"},{"t":"킥보드를 탄 채로 빠르게 건넌다","mis":"SC6-1-u2-X34"},{"t":"신호가 바뀌자마자 좌우를 보지 않고 뛰어 건넌다","mis":"SC6-1-u2-X34"}],"explanation":["주위를 살펴요.","좌우를 봐요.","천천히 건너요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#7','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C26',1,'mc','auto','친구가 실천 결과를 발표할 때 알맞은 태도는 어느 것인가요?',ARRAY['SC6-1-u2-X41']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C26","difficulty":1,"kind":"mc","stem":"친구가 실천 결과를 발표할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"바른 자세로 끝까지 듣는다","correct":true},{"t":"내 발표 차례만 기다리며 딴생각을 한다","mis":"SC6-1-u2-X41"},{"t":"못 지킨 날을 들추어 탓한다","mis":"SC6-1-u2-X41"},{"t":"발표 중에 끼어들어 내 이야기를 한다","mis":"SC6-1-u2-X41"}],"explanation":["듣는 태도예요.","바른 자세로요.","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#8','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C5',1,'mc','auto','운동하는 물체를 찾으려고 찍은 사진은 관찰이 끝난 뒤 어떻게 하나요?',ARRAY['SC6-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C5","difficulty":1,"kind":"mc","stem":"운동하는 물체를 찾으려고 찍은 사진은 관찰이 끝난 뒤 어떻게 하나요?","options":[{"t":"삭제한다","correct":true},{"t":"누리망에 올린다","mis":"SC6-1-u2-X10"},{"t":"친구 얼굴 사진만 골라 나눈다","mis":"SC6-1-u2-X10"},{"t":"반 누리집에 모두 올려 둔다","mis":"SC6-1-u2-X10"}],"explanation":["다른 사람이 찍혔어요.","개인 정보예요.","삭제해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#9','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C6',2,'ox','auto','푸름반 일지 ①의 지우가 철봉에서 내려와 교실로 걸어가면 그때는 운동하는 물체예요.',ARRAY['SC6-1-u2-X09']::text[],false,'{"seq":9,"concept":"SC6-1-u2-C6","difficulty":2,"kind":"ox","stem":"푸름반 일지 ①의 지우가 철봉에서 내려와 교실로 걸어가면 그때는 운동하는 물체예요.","answer":"O","reason_options":[{"t":"시간이 지남에 따라 위치가 변하기 때문에","correct":true},{"t":"한 번 운동하지 않은 물체는 계속 운동하지 않기 때문에","mis":"SC6-1-u2-X09"}],"mis":"SC6-1-u2-X09","explanation":["걸어가면 어떻게 되나요?","위치가 변해요.","운동하는 물체예요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#10','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C8',2,'error','auto','푸름반 운동장 판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X14']::text[],false,'{"seq":10,"concept":"SC6-1-u2-C8","difficulty":2,"kind":"error","stem":"푸름반 운동장 판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시온 — 「매점은 국기대에서 아래쪽으로 1칸 떨어져 있어.」","correct":true,"mis_target":"SC6-1-u2-X14"},{"t":"다희 — 「정문은 국기대에서 오른쪽으로 3칸 떨어져 있어.」","mis":"SC6-1-u2-X14"},{"t":"우진 — 「그네는 국기대에서 왼쪽 2칸, 위쪽 1칸 떨어져 있어.」","mis":"SC6-1-u2-X14"}],"explanation":["매점 자리를 봐요.","왼쪽으로도 1칸 가야 해요.","시온이 잘못 말했어요."],"asset":{"type":"geo","items":[{"w":280,"h":200,"grid":40,"lab":[[[140,140],"국기대"],[[60,100],"그네"],[[260,140],"정문"],[[180,20],"화단"],[[100,180],"매점"]],"cap":"푸름반 일지 ② 운동장 판"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#11','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C11',2,'ox','auto','같은 시간 실험에서는 자동차마다 사진 찍는 시각을 다르게 해도 돼요.',ARRAY['SC6-1-u2-X18']::text[],false,'{"seq":11,"concept":"SC6-1-u2-C11","difficulty":2,"kind":"ox","stem":"같은 시간 실험에서는 자동차마다 사진 찍는 시각을 다르게 해도 돼요.","answer":"X","reason_options":[{"t":"같은 시간 동안 이동한 거리를 견주어야 하기 때문에","correct":true},{"t":"각자 편할 때 찍어도 이동한 거리는 같기 때문에","mis":"SC6-1-u2-X18"}],"mis":"SC6-1-u2-X18","explanation":["무엇이 같아야 하나요?","시간이에요.","같은 순간에 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#12','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C16',2,'match','auto','운동 종목과 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC6-1-u2-C16","difficulty":2,"kind":"match","stem":"운동 종목과 설명을 알맞게 이으세요.","pairs":[{"l":"달리기","r":"트랙을 달리는 데 걸린 시간을 잰다"},{"l":"조정","r":"노를 저어 뒤로 나아가며 결승선까지 간다"},{"l":"봅슬레이","r":"썰매로 얼음 트랙을 내려간다"}],"mis":"SC6-1-u2-X25","explanation":["종목을 떠올려요.","모두 걸린 시간을 재요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#13','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C20',2,'ox','auto','푸름반 일지 ⑤의 버스는 1시간째에도 2시간째에도 반드시 똑같이 80 km씩 갔어요.',ARRAY['SC6-1-u2-X30']::text[],false,'{"seq":13,"concept":"SC6-1-u2-C20","difficulty":2,"kind":"ox","stem":"푸름반 일지 ⑤의 버스는 1시간째에도 2시간째에도 반드시 똑같이 80 km씩 갔어요.","answer":"X","reason_options":[{"t":"속력은 전체 이동 거리를 전체 걸린 시간으로 나눈 값이라 매 시간 똑같이 갔다는 뜻이 아니기 때문에","correct":true},{"t":"속력이 80 km/h면 매 시간 똑같이 80 km씩 가기 때문에","mis":"SC6-1-u2-X30"}],"mis":"SC6-1-u2-X30","explanation":["속력을 어떻게 구했나요?","전체 거리 ÷ 전체 시간이에요.","반드시 똑같지는 않아요."],"asset":{"type":"passage","lines":["버스 — 2시간 동안 160 km","기차 — 3시간 동안 330 km","자전거 동아리 — 2시간 동안 30 km"],"title":"푸름반 일지 ⑤ 체험 학습 날 이동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#14','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C22',2,'ox','auto','어린이 보호 구역에서는 자동차가 정해진 속력보다 천천히 달려야 해요.',ARRAY['SC6-1-u2-X34']::text[],false,'{"seq":14,"concept":"SC6-1-u2-C22","difficulty":2,"kind":"ox","stem":"어린이 보호 구역에서는 자동차가 정해진 속력보다 천천히 달려야 해요.","answer":"O","reason_options":[{"t":"어린이가 많이 다니는 곳이라 바로 멈출 수 있게 천천히 달려야 하기 때문에","correct":true},{"t":"어린이 보호 구역도 다른 도로와 똑같기 때문에","mis":"SC6-1-u2-X34"}],"mis":"SC6-1-u2-X34","explanation":["표지판을 떠올려요.","속력을 제한해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#15','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C25',2,'ox','auto','교통안전 실천 점검표는 활동이 끝나면 버리고 수칙도 그만 지켜도 돼요.',ARRAY['SC6-1-u2-X40']::text[],false,'{"seq":15,"concept":"SC6-1-u2-C25","difficulty":2,"kind":"ox","stem":"교통안전 실천 점검표는 활동이 끝나면 버리고 수칙도 그만 지켜도 돼요.","answer":"X","reason_options":[{"t":"꾸준히 실천해 습관이 되어야 하기 때문에","correct":true},{"t":"일주일 동안만 지키면 되기 때문에","mis":"SC6-1-u2-X40"}],"mis":"SC6-1-u2-X40","explanation":["점검표를 만든 까닭이에요.","습관이 되어야 해요.","계속 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#16','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C27',2,'ox','auto','초고속 카메라는 사람의 눈으로 판단하기 어려운 경우에 공정한 판정을 도와요.',ARRAY['SC6-1-u2-X43']::text[],false,'{"seq":16,"concept":"SC6-1-u2-C27","difficulty":2,"kind":"ox","stem":"초고속 카메라는 사람의 눈으로 판단하기 어려운 경우에 공정한 판정을 도와요.","answer":"O","reason_options":[{"t":"1초에 수천 장의 사진으로 먼저 도착한 선수를 보여 주기 때문에","correct":true},{"t":"경기를 재미있게 꾸미는 일만 하기 때문에","mis":"SC6-1-u2-X43"}],"mis":"SC6-1-u2-X43","explanation":["카메라가 하는 일이에요.","아주 짧은 순간을 찍어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#17','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C21',3,'mc','auto','비가 오는 날 푸름반 일지 ⑦의 학교 앞 도로를 지나는 운전자에게 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X33','SC6-1-u2-X37','SC6-1-u2-X32']::text[],false,'{"seq":17,"concept":"SC6-1-u2-C21","difficulty":3,"kind":"mc","stem":"비가 오는 날 푸름반 일지 ⑦의 학교 앞 도로를 지나는 운전자에게 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평소보다 더 천천히 달리고 앞차와의 거리를 넉넉히 둔다","correct":true},{"t":"도로가 미끄러우면 제동 거리가 짧아지니 평소처럼 달린다","mis":"SC6-1-u2-X33"},{"t":"안전장치가 많으니 속력을 줄이지 않아도 된다","mis":"SC6-1-u2-X37"},{"t":"비와 속력은 관계가 없다","mis":"SC6-1-u2-X32"}],"explanation":["미끄러운 도로예요.","제동 거리가 길어져요.","더 천천히 달려요."],"asset":{"type":"passage","lines":["학교 앞 차선이 지그재그로 그려져 있다.","횡단보도 앞에 과속 방지턱이 있다.","도로 옆 전광판에 지나가는 자동차의 속력이 숫자로 나타난다.","인도와 차도 사이에 안전 울타리가 있다.","어린이 보호 구역 표지판이 서 있다."],"title":"푸름반 일지 ⑦ 학교 앞 도로 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#18','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C7',3,'error','auto','푸름반 일지 ①의 서진의 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X16','SC6-1-u2-X12','SC6-1-u2-X13']::text[],false,'{"seq":18,"concept":"SC6-1-u2-C7","difficulty":3,"kind":"error","stem":"푸름반 일지 ①의 서진의 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이현 — 「정문 앞과 화단 옆 사이의 중간 위치를 꼭 말해야 해.」","correct":true,"mis_target":"SC6-1-u2-X16"},{"t":"가윤 — 「걸린 시간 10초를 넣어야 해.」","mis":"SC6-1-u2-X12"},{"t":"서후 — 「처음 위치는 정문 앞이야.」","mis":"SC6-1-u2-X13"}],"explanation":["위치 변화를 떠올려요.","처음과 나중이에요.","이현이 잘못 말했어요."],"asset":{"type":"passage","lines":["국기 게양대 — 처음: 운동장 끝 · 10초 뒤: 운동장 끝","지우 — 처음: 철봉에 가만히 매달림 · 10초 뒤: 그대로 매달림","서진 — 처음: 정문 앞 · 10초 뒤: 화단 옆","비둘기 — 처음: 지붕 위 · 10초 뒤: 나무 위","학교 버스 — 처음: 주차장에 서 있음 · 10초 뒤: 주차장에 서 있음","공 — 처음: 골대 앞 · 10초 뒤: 골대 안"],"title":"푸름반 일지 ① 10초 간격 운동장 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#19','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C21',3,'ox','auto','같은 30 km/h로 달려도 빙판길에서는 마른 노면보다 제동 거리가 더 길어요.',ARRAY['SC6-1-u2-X33']::text[],false,'{"seq":19,"concept":"SC6-1-u2-C21","difficulty":3,"kind":"ox","stem":"같은 30 km/h로 달려도 빙판길에서는 마른 노면보다 제동 거리가 더 길어요.","answer":"O","reason_options":[{"t":"미끄러운 도로에서는 브레이크를 밟은 뒤 멈출 때까지 더 많이 움직이기 때문에","correct":true},{"t":"속력이 같으면 도로 상태와 관계없이 제동 거리가 같기 때문에","mis":"SC6-1-u2-X33"}],"mis":"SC6-1-u2-X33","explanation":["자료의 30 km/h 줄을 봐요.","1.5 m와 10.7 m예요.","맞는 말이에요."],"asset":{"type":"passage","lines":["속력 30 km/h — 마른 노면 1.5 m · 빙판길 10.7 m","속력 50 km/h — 마른 노면 4.6 m · 빙판길 33.2 m","속력 60 km/h — 마른 노면 10.1 m · 빙판길 49.9 m","제동 거리: 브레이크를 밟은 뒤 완전히 멈출 때까지 움직인 거리","※ 자료에 실린 값이다."],"title":"자동차의 속력과 도로 상태에 따른 제동 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#20','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C11',3,'mc','auto','같은 시간 실험에서 5초 뒤 사진을 보니 이동 거리가 134.6 cm였어요. 기록하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X18']::text[],false,'{"seq":20,"concept":"SC6-1-u2-C11","difficulty":3,"kind":"mc","stem":"같은 시간 실험에서 5초 뒤 사진을 보니 이동 거리가 134.6 cm였어요. 기록하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"135 cm","correct":true},{"t":"134.6 cm","mis":"SC6-1-u2-X18"},{"t":"134 cm","mis":"SC6-1-u2-X18"},{"t":"130 cm","mis":"SC6-1-u2-X18"}],"explanation":["일의 자리까지예요.","소수 첫째 자리에서 반올림해요.","135 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#21','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C25',3,'mc','auto','점검표에 넣을 수칙을 정하다가 모둠원 모두가 하나씩 더 넣자고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC6-1-u2-X40','SC6-1-u2-X39']::text[],false,'{"seq":21,"concept":"SC6-1-u2-C25","difficulty":3,"kind":"mc","stem":"점검표에 넣을 수칙을 정하다가 모둠원 모두가 하나씩 더 넣자고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"의논해서 꼭 필요한 수칙을 몇 가지로 정해 실천하기 쉽게 만든다","correct":true},{"t":"나온 수칙을 모두 넣어 길게 만든다","mis":"SC6-1-u2-X40"},{"t":"모둠장이 혼자 정한다","mis":"SC6-1-u2-X40"},{"t":"표시가 많아 보이도록 쉬운 수칙만 여러 번 넣는다","mis":"SC6-1-u2-X39"}],"explanation":["너무 복잡하지 않게 해요.","함께 의논해요.","꼭 필요한 것으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#22','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C1',3,'mc','auto','나무토막 옮기기 활동의 목적에 가장 가까운 것은 어느 것인가요?',ARRAY['SC6-1-u2-X02','SC6-1-u2-X03','SC6-1-u2-X01']::text[],false,'{"seq":22,"concept":"SC6-1-u2-C1","difficulty":3,"kind":"mc","stem":"나무토막 옮기기 활동의 목적에 가장 가까운 것은 어느 것인가요?","options":[{"t":"다양한 모습으로 걸으며 물체의 움직임과 빠르기에 관심을 가진다","correct":true},{"t":"가장 빨리 들어온 친구에게 상을 준다","mis":"SC6-1-u2-X02"},{"t":"모든 친구가 같은 빠르기로 걷는지 확인한다","mis":"SC6-1-u2-X03"},{"t":"무거운 나무토막을 빨리 나르는 연습을 한다","mis":"SC6-1-u2-X01"}],"explanation":["겨루기가 아니에요.","걷는 모습을 살펴요.","움직임에 관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#23','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C25',4,'mc','auto','푸름반 일지 ⑧의 서아의 점검표를 가장 알맞게 해석한 것은 어느 것인가요?',ARRAY['SC6-1-u2-X39','SC6-1-u2-X40']::text[],false,'{"seq":23,"concept":"SC6-1-u2-C25","difficulty":4,"kind":"mc","stem":"푸름반 일지 ⑧의 서아의 점검표를 가장 알맞게 해석한 것은 어느 것인가요?","options":[{"t":"표시 개수로 잘함을 정하지 않고, 못 지킨 까닭을 깨달아 다음 주에 더 노력하려는 것이 점검표를 만든 목적에 맞다","correct":true},{"t":"표시가 가장 많은 ①만 중요하다","mis":"SC6-1-u2-X39"},{"t":"빈칸이 있으니 실패한 점검표이다","mis":"SC6-1-u2-X39"},{"t":"다음 주에는 점검표 없이 지내도 된다","mis":"SC6-1-u2-X40"}],"explanation":["점검표의 목적을 떠올려요.","실천과 습관이에요.","노력하려는 다짐이 중요해요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#24','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C14',4,'essay','teacher','푸름반 일지 ④의 결과로 1위를 한 친구와 그 까닭을 쓰고, 일지 ③(같은 시간 동안 달린 거리)과 일지 ④가 빠르기를 비교한 방법이 어떻게 다른지 견주어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u2-C14","difficulty":4,"kind":"essay","stem":"푸름반 일지 ④의 결과로 1위를 한 친구와 그 까닭을 쓰고, 일지 ③(같은 시간 동안 달린 거리)과 일지 ④가 빠르기를 비교한 방법이 어떻게 다른지 견주어 설명하세요.","answer_guide":{"answer":"예: 1위는 바다이다. 세 친구가 같은 50 m를 달렸는데 바다가 9.0초로 걸린 시간이 가장 짧기 때문이다. 일지 ③은 시간을 10초로 같게 하고 이동한 거리를 재어 거리가 긴 쪽이 빠르다고 비교했다. 일지 ④는 거리를 50 m로 같게 하고 걸린 시간을 재어 시간이 짧은 쪽이 빠르다고 비교했다.","scoring_points":["1위와 까닭을 바르게 썼는가","일지 ③의 비교 방법을 썼는가","두 방법이 무엇을 같게 하고 무엇을 재는지 견주었는가"]},"explanation":["시간을 견줘요.","같게 한 것을 찾아요.","두 방법을 견줘요."],"asset":{"type":"passage","lines":["다음 날 셋이 50 m를 한 사람씩 달려 걸린 시간을 쟀다.","하늘 — 9.4초","바다 — 9.0초","솔 — 10.1초"],"title":"푸름반 일지 ④ 50 m를 달린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u2_review_d#25','sci',6,1,'u2','','g6_1_sci_u2_review_d','unit_review','SC6-1-u2-C25',4,'essay','teacher','푸름반 일지 ⑧의 서아의 점검표를 보고 잘한 점과 더 노력할 점을 하나씩 쓰고, 교통안전 실천 점검표를 쓸 때 왜 양심적으로 표시하고 꾸준히 실천해야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u2-C25","difficulty":4,"kind":"essay","stem":"푸름반 일지 ⑧의 서아의 점검표를 보고 잘한 점과 더 노력할 점을 하나씩 쓰고, 교통안전 실천 점검표를 쓸 때 왜 양심적으로 표시하고 꾸준히 실천해야 하는지 쓰세요.","answer_guide":{"answer":"예: 서아는 ① 골목에서 멈추고 좌우 살피기를 일주일 내내 실천한 점이 잘했다. ②와 ③은 다 지키지 못했으므로 다음 주에 더 노력하면 좋겠다. 특히 건널 때 스마트 기기를 보고 있었다는 것을 깨달은 점이 좋다. 점검표는 칸을 채우는 것이 목적이 아니라 실제로 실천했는지 스스로 점검하는 것이므로 양심적으로 표시해야 한다. 안전 수칙은 한 번 안다고 지켜지지 않으므로 꾸준히 실천해 습관이 되어야 안전사고를 줄일 수 있다.","scoring_points":["잘한 점을 썼는가","더 노력할 점을 썼는가","양심적 표시와 꾸준한 실천의 까닭을 썼는가"]},"explanation":["표시한 날을 봐요.","잘한 점과 노력할 점을 찾아요.","까닭을 써요."],"asset":{"type":"passage","lines":["서아의 수칙 ① 골목에서 나올 때 멈추고 좌우 살피기","서아의 수칙 ② 자전거를 탈 때 보호 장비 착용하기","서아의 수칙 ③ 스마트 기기를 보지 않고 횡단보도 건너기","표시한 날 — ① 7일 · ② 4일 · ③ 5일","느낀 점 — 건널 때 스마트 기기를 보고 있었다는 것을 깨달았다.","다짐 — 다음 주에는 ②와 ③을 더 꾸준히 지키겠다."],"title":"푸름반 일지 ⑧ 서아의 일주일 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
